window.VISIE_CONTENT = [{"id":"samenvatting","letter":null,"titel":"De ondernemer als motor voor de maatschappelijke opgaves","intro":"","html":"\n<div class=\"meta-row\">\n    <span class=\"meta-badge\">Visiedocument</span>\n    <span class=\"meta-badge\">April 2026</span>\n    <span class=\"meta-badge\">VIC / JUMP</span>\n  </div>\n\n<h1>Veenweide<span>boeren</span> — visie</h1>\n\n<h2>De ondernemer als motor voor de maatschappelijke opgaves</h2>\n\n<div style=\"background:var(--bg3);border:1px solid rgba(0,0,0,.08);border-left:3px solid var(--accent);border-radius:var(--radius);padding:1.25rem 1.5rem;margin:1.5rem 0 2rem;font-size:13.5px;line-height:1.65\">\n    <strong style=\"display:block;margin-bottom:8px;font-size:14px\">Managementsamenvatting</strong>\n    <p style=\"margin:0 0 .75rem\"><strong>Het probleem.</strong> In het veenweidegebied zit de middengroep klem — de familieondernemers die 70–80% van het gebied beheren. Niet door eigen falen, maar door een systeem dat alleen schaal en liters beloont. Zolang die klem bestaat, wordt geen van de zeven maatschappelijke opgaves gehaald: klimaat, water, natuur, voedselzekerheid, cultuur &amp; landschap, grondstoffen &amp; kringloop, wonen.</p>\n    <p style=\"margin:0 0 .75rem\"><strong>De analyse: drie aktes.</strong> Akte I — doorgaan op de huidige weg — houdt de uitstoot onverminderd hoog en holt het rentmeesterschap uit. Akte II — de huidige maatregelen en plannen: peilfixatie, normering, compensatie — lijkt aanvankelijk te werken: het peil stijgt, de cijfers verbeteren. Maar de verbetering keert. Precies de boeren die de opgaves moeten dragen worden het gebied uitgeduwd; wat overblijft zijn beheerders op afstand. In brede zin worden de opgaves juist níet gehaald. Akte III hanteert dezelfde maatregelen en dezelfde doelen, maar legt er de pijlers onder die van de boer een ondernemer maken.</p>\n    <p style=\"margin:0 0 .75rem\"><strong>De oplossing: de veenweideboer.</strong> Een nieuwe typologie: een ondernemer die naast voedsel maatschappelijke diensten levert — koolstofopslag, schoon water, biodiversiteit, landschap — als volwaardig product. De kern is één omkering: <strong>van subsidies naar vergoedingen voor geleverde maatschappelijke diensten.</strong> Niet de boer compenseren als slachtoffer van beleid, maar betalen als leverancier van publieke waarde. De overheid bepaalt wát geleverd wordt; de boer bepaalt hóe. Hetzelfde geld — circa €1,3 miljard tot 2035 — ander instrument, fundamenteel ander effect.</p>\n    <p style=\"margin:0\"><strong>Te nemen acties.</strong> Eén: voer het gesprek over de juridische status van maatschappelijke diensten als primair landbouwproduct — in de eerste fase, niet de laatste. Twee: zet de €1,3 miljard om van compensatielogica naar langjarige maatschappelijke opdrachten. Drie: creëer de veenweidecategorie in het omgevingsplan.</p>\n  </div>\n","werkstand":{"nummer":"—","ronde":"6","stand":"laag 1, wordt als laatste gemaakt uit het afgeronde verhaal"}},{"id":"walkthrough","letter":null,"titel":"Walkthrough","intro":"Zestien stappen. Klik door het verhaal — elke stap bouwt voort op de vorige. Ook met pijltjestoetsen of spatiebalk.","html":"\n<h2>Walkthrough</h2>\n\n<p>Zestien stappen. Klik door het verhaal — elke stap bouwt voort op de vorige. Ook met pijltjestoetsen of spatiebalk.</p>\n\n<div id=\"wt-container\" style=\"margin:1.5rem 0\">\n    <!-- Progress bar -->\n    <div style=\"display:flex;gap:4px;margin-bottom:1.5rem\" id=\"wt-progress\"></div>\n\n    <!-- Slide area -->\n    <div id=\"wt-slide\" style=\"min-height:340px;background:var(--bg3);border:1px solid rgba(0,0,0,.06);border-radius:var(--radius-lg);padding:2.5rem;position:relative;overflow:hidden;transition:background .4s ease, border-color .4s ease\">\n    </div>\n\n    <!-- Navigation -->\n    <div style=\"display:flex;justify-content:space-between;align-items:center;margin-top:1rem\">\n      <button id=\"wt-prev\" onclick=\"wtNav(-1)\" style=\"background:var(--bg2);border:1px solid rgba(0,0,0,.1);border-radius:var(--radius);padding:8px 20px;font-family:var(--font-body);font-size:13px;color:var(--text2);cursor:pointer;transition:all .15s\">← Vorige</button>\n      <span id=\"wt-counter\" style=\"font-family:var(--font-mono);font-size:12px;color:var(--text3)\"></span>\n      <button id=\"wt-next\" onclick=\"wtNav(1)\" style=\"background:var(--accent);border:none;border-radius:var(--radius);padding:8px 24px;font-family:var(--font-body);font-size:13px;color:#fff;cursor:pointer;font-weight:500;transition:all .15s\">Volgende →</button>\n    </div>\n  </div>\n","werkstand":{"nummer":"—","ronde":"—","stand":"leeshulp van de website, geen hoofdstuk"}},{"id":"scope","letter":"1","titel":"Waar dit over gaat","intro":"Dit visiedocument schetst een nieuw perspectief voor het veenweidegebied: dit gebied kan meer maatschappelijke opgaven dragen dan voedselproductie alleen. Dat vermogen zit niet in de grond, maar in de ondernemer die het land beheert. De grote maatschappelijke opgaven — van klimaat en water tot voedselzekerheid en wonen — zijn alleen haalbaar als boeren niet uitsluitend worden aangesproken op productie, maar ook worden beloond voor de publieke diensten die zij leveren. Daarmee verschuift het debat van probleemdenken naar oplossingskracht. Voor een deel van het gebied is reguliere melkveehouderij op termijn niet meer houdbaar en is een fundamenteel ander bedrijfsmodel nodig. Dit document beschrijft hoe dat eruitziet, welke condities daarvoor nodig zijn, en hoe de boer daarmee weer motor wordt van de gebiedstransitie.","html":"\n<h2>1 — Waar dit over gaat</h2>\n\n<div style=\"background:var(--bg3);border:1px solid rgba(0,0,0,.08);border-left:3px solid var(--accent);border-radius:var(--radius);padding:1.25rem 1.5rem;margin:1.5rem 0 2rem;font-size:13.5px;line-height:1.65\">\n    <strong style=\"display:block;margin-bottom:8px;font-size:14px\">Voor wie is dit document?</strong>\n    <p style=\"margin:0 0 .75rem\"><strong>Voor boeren in het veenweidegebied</strong> — veenweideboer is geen categorie waarin u wel of niet valt, maar een schaal waarop u zelf een plek kiest: van melk met het landbeheer dat er nu al bij hoort zonder dat iemand ervoor betaalt, tot een bedrijf zonder koeien waar maatschappelijke diensten het hele product zijn. Elke plek op die schaal is een goede plek. Wie tevreden is met de huidige bedrijfsvoering en zijn opgaven binnen het bestaande model haalt: prima, geen religie en geen opgedrongen verhaal. Wie de bui ziet hangen — een perceel dat te nat wordt, krimpende stikstofruimte, een melkprijs die het niet meer dekt — vindt hier een aanbod. Niet \"zo moet u het gaan doen\", maar \"zo zou het kunnen worden, als u het wilt\". Wat wij vragen is dat schuiven mogelijk wordt, niet dat er geschoven wordt.</p>\n    <p style=\"margin:0 0 .75rem\"><strong>Voor overheden die over het veenweidegebied gaan</strong> — voor de gebieden waar reguliere melkveehouderij houdbaar blijft, hoeft dit document niet leidend te zijn. Voor de gebieden waar dat niet zo is, biedt het een alternatief voor de twee routes die nu overblijven: doorgaan zoals het is, of uitkopen. De opdracht aan de overheid is daarmee scherper, niet zwaarder: schep het kader waarin het verdienmodel van de veenweideboer kan ontstaan. Wat mag kost weinig en werkt alleen als het breed geldt; wat betaalt landt smal, daar waar het nodig is.</p>\n    <div style=\"padding-top:.85rem;border-top:1px solid rgba(0,0,0,.08)\">\n      <strong style=\"display:block;margin-bottom:8px;font-size:14px\">Wat voor soort document is dit?</strong>\n      <p style=\"margin:0\">Dit stuk is het naslagwerk: de volledige redenering, met de cijfers, de bronnen en de afbakeningen erbij. Er komt ook een korte versie met de kern, en een leesversie die het verhaal doorlopend vertelt. Kern, feiten en positie tegenover het beleid zijn in alle versies gelijk; alleen de ingang en de weglatingen verschillen.</p>\n    </div>\n  </div>\n\n<h3>1.1 Wat dit document voorstelt</h3>\n\n<p>Dit visiedocument schetst een nieuw perspectief voor het veenweidegebied: dit gebied kan meer maatschappelijke opgaven dragen dan voedselproductie alleen. Dat vermogen zit niet in de grond, maar in de ondernemer die het land beheert. De grote maatschappelijke opgaven — van klimaat en water tot voedselzekerheid en wonen — zijn alleen haalbaar als boeren niet uitsluitend worden aangesproken op productie, maar ook worden beloond voor de publieke diensten die zij leveren. Daarmee verschuift het debat van probleemdenken naar oplossingskracht. Voor een deel van het gebied is reguliere melkveehouderij op termijn niet meer houdbaar en is een fundamenteel ander bedrijfsmodel nodig. Dit document beschrijft hoe dat eruitziet, welke condities daarvoor nodig zijn, en hoe de boer daarmee weer motor wordt van de gebiedstransitie.</p>\n\n<p>Dat is urgent. De ondernemers voor wie dit bedoeld is zitten nu al klem: middelgrote familiebedrijven die tegelijk landschapsbeheerder zijn, en die vastlopen op kosten en omzet, niet op vakmanschap of motivatie. Hoe die klem werkt is de analyse van hoofdstuk 3; hier is alleen van belang dat de klem nu al knelt en niet wacht op de uitkomst van dit document. Wie stopt komt niet terug, en met dat bedrijf verdwijnt het beheer waarop de opgaven rusten.</p>\n\n<div style=\"background:var(--bg2);border-left:3px solid var(--text2);border-radius:var(--radius);padding:1.25rem 1.5rem;margin:1.5rem 0 0;font-size:13.5px;line-height:1.65\">\n    <div style=\"display:flex;align-items:center;gap:1.1rem;margin-bottom:10px\">\n      <img src=\"data:image/png;base64,\" alt=\"Veenweiden Innovatiecentrum\" style=\"width:132px;height:auto;flex:none;display:block\">\n      <strong style=\"font-size:14px\">Wie dit zegt, en waarom</strong>\n    </div>\n    <p style=\"margin:0 0 .75rem\">Het Veenweiden Innovatiecentrum is een onafhankelijke kennisinstelling voor het veengebied. Onze <strong>missie</strong> staat in artikel 2.1 van onze statuten: onderzoek doen, ontwikkeling en innovatie aanjagen en kennis uitbreiden, en dat <em>voor een duurzaam en klimaatadaptief (en waar mogelijk klimaatmitigerend) én tevens vitaal veengebied in Nederland, waarin ondernemerschap bloeit binnen nieuwe maatschappelijke spelregels.</em> Dit document gaat over die laatste woorden. Ons werkgebied is statutair het hele Nederlandse veengebied, en wat wij vinden is openbaar, zonder voorrang voor wie het onderzoek betaalt.</p>\n    <p style=\"margin:0 0 .75rem\">Onze <strong>ambitie</strong> voor de komende zes jaar is te laten zien dat er meer mogelijk is dan melkvee alleen: hetzelfde gebied kan schoon water, vastgehouden koolstof, biodiversiteit, landschap én voedsel leveren, voor de BV Nederland en voor de maatschappij Nederland. De ondernemer die die diensten levert is daarbij de motor. Die jaren zetten wij in om te bewijzen dat het werkt, en om de spelregels mogelijk te maken die daarvoor nodig zijn.</p>\n    <p style=\"margin:0\">Daarom komen wij met deze <strong>visie</strong>. In het programma JUMP ontwikkelen wij vergaande bedrijfsconcepten voor ondernemers op veen: topvoedsel, waterdiensten, biodiversiteit, koolstofopslag, natte teelt. Wat daar blijkt is dat het knelpunt niet technisch is. De maatregelen bestaan. Wat ontbreekt is een verdienmodel eronder en een overheidskader dat dat toelaat. Dat is niet met een proefveld op te lossen, en daarom staat het hier.</p>\n  </div>\n\n<h3>1.2 Hoe dit zich verhoudt tot het huidige beleid</h3>\n\n<p>Twee dossiers vormen de directe aanleiding voor dit document. Het Rijk werkt aan een gebiedsspecifieke aanpak voor het veenweidegebied; de Veenweidenbrief daarover wordt na de zomer verwacht, en de precieze inhoud zoals die nu is aangekondigd staat in bijlage 16. Daarnaast is stikstof op dit moment het politiek meest urgente dossier van Nederland, want bouwen, uitbreiding van het stroomnet en defensie-investeringen lopen vrijwel allemaal vast op stikstofruimte.</p>\n\n<p>De beperkingen die daaruit volgen zijn nodig, en de maatregelen zijn terecht. Die urgentie delen wij. Wat hier staat is geen alternatief voor dat beleid, maar een manier om het te laten slagen. Een lagere veedichtheid op hetzelfde areaal levert structureel minder ammoniak, terwijl het bedrijf voedsel blijft produceren. En de ondernemer blijft op het land, met al het landbeheer dat daar nu onbeprijsd bij hoort en dat anders uit publiek geld moet komen.</p>\n\n<p><strong>Wij vragen geen wijziging van het huidige beleid en geen euro uit de lopende programma's.</strong> Die middelen zijn toegewezen en die maatregelen worden uitgerold; dat is de ronde die nu loopt. Wij vragen de ruimte om te bouwen wat de volgende ronde nodig heeft: het bewijs dat maatschappelijke diensten een verdienmodel kunnen zijn, en de spelregels die dat mogelijk maken. Daar zijn wij al jaren mee bezig, en er zijn nog jaren nodig voordat het klaar is. Daarom moet dit werk nu doorlopen: het moet klaar zijn op het moment dat die volgende ronde wordt ingericht, niet erna.</p>\n\n<h3>1.3 Over welk deel van het gebied</h3>\n\n<p>Het Nederlandse veenweidegebied beslaat ongeveer 200.000 hectare, en op het grootste deel daarvan is er geen groot probleem. Daar kan melkveehouderij op reguliere wijze doorgaan, mits aan de generieke milieu-, stikstof- en waterkwaliteitseisen wordt voldaan, zelfs bij een enigszins verhoogd slootwaterpeil.</p>\n\n<p>Toch is dit voor het hele gebied interessant. Ook een bedrijf dat gewoon melkvee houdt kan schoon water, vastgehouden koolstof, biodiversiteit en landschap leveren. Maatschappelijke diensten als volwaardig product naast voedsel: die redenering geldt dus voor het hele veenweidegebied, en de juridische ruimte die ervoor nodig is ook. Die ruimte kost weinig en werkt alleen als ze breed is.</p>\n\n<p>Waar dit document over gaat is smaller. Op ongeveer 20 tot 30% van het gebied stapelen de opgaven zich zo op dat reguliere melkveehouderij op termijn niet houdbaar is. Vier vormen van fysieke druk wegen daarin het zwaarst, naast een aantal andere die hoofdstuk 3 erbij zet:</p>\n\n<ul style=\"margin:.85rem 0 1.1rem;padding-left:1.35rem\">\n    <li style=\"margin-bottom:.45rem\"><strong>Gebieden die structureel te nat worden</strong>, door een hoger slootwaterpeil of door autonome vernatting.</li>\n    <li style=\"margin-bottom:.45rem\"><strong>Snelle bodemdaling en veenoxidatie.</strong> Diezelfde oxidatie is de bron van de broeikasgasuitstoot, dus de klimaatopgave vraagt hier hetzelfde als de bodemopgave.</li>\n    <li style=\"margin-bottom:.45rem\"><strong>Ligging in of tegen Natura 2000.</strong> Hier is de stikstofruimte het knelpunt, en die krimpt.</li>\n    <li><strong>Sterke kwel en verzilting.</strong> Waterdruk van onderaf beïnvloedt de bedrijfsvoering structureel, ook zonder peilmaatregel.</li>\n  </ul>\n\n<p>Zelden is één vorm beslissend. Het is de stapeling die het bedrijfsmodel onhoudbaar maakt, en dat is ook waarom de grens niet als een lijn op de kaart te trekken valt: hij loopt door bedrijven heen. Waar die stapeling optreedt is een fundamenteel ander bedrijfsmodel nodig, met een aanzienlijk lagere veedichtheid. De criteria voor dat bedrijfsmodel zijn uitgewerkt in hoofdstuk 9. In het hele veengebied gaat het om ongeveer 2.300 melkveebedrijven<span class=\"fiche-wrap\"><button class=\"fiche-btn\" type=\"button\" aria-label=\"Bron tonen\">ⓘ</button><span class=\"fiche-popup\"><span class=\"fiche-label\">Bron</span><span class=\"fiche-source\">CBS-Landbouwtelling 2023, bewerking Wageningen Economic Research, in RIVM-rapport 2024-0137, tabel B1.1. Afbakening: de Veenregio van het Landelijk Meetnet effecten Mestbeleid, waar deze bedrijven samen circa 148.000 hectare cultuurgrond gebruiken, waarvan 135.000 hectare grasland. Bedrijven onder 10 hectare of onder €25.000 standaardopbrengst vallen buiten de telling.</span><span class=\"fiche-note\">Dat is een andere afbakening dan de 200.000 hectare grasland op veen hierboven, die uit de emissierapportage komt. Een exacter aantal bestaat niet: de PlanMER bij het Nationaal Programma Landelijk Gebied stelt in 2023 vast dat landbouwinformatie per grondsoortgebied niet voorhanden is.</span></span></span>. Hoeveel daarvan in de 20 tot 30% vallen, valt niet te tellen, en dat is geen gebrek aan statistiek maar dezelfde grens die door bedrijven heen loopt.</p>\n\n<p>Op een klein deel, ongeveer 10.000 hectare, is helemaal geen vee meer mogelijk. Daar zijn dezelfde vier vormen van druk nog scherper. De redenering blijft er gelden, en juist daar kunnen maatschappelijke diensten het hele product worden. Maar het bedrijfsmodel dat dit document beschrijft gaat uit van melkvee met een lagere veedichtheid, en dat houdt hier op. De vergaande concepten voor deze gebieden komen uit het programma JUMP.</p>\n\n<div style=\"background:var(--bg3);border:1px solid rgba(0,0,0,.06);border-radius:var(--radius-lg);padding:1.25rem 1.5rem;margin:1rem 0 1.5rem;overflow-x:auto\">\n    <p style=\"font-family:var(--font-display);font-size:15px;font-weight:600;color:var(--text);margin:0 0 .75rem\">Waar gaat dit over</p>\n    <table style=\"width:100%;border-collapse:collapse;font-size:12.5px;line-height:1.55\">\n      <thead>\n        <tr style=\"border-bottom:1px solid rgba(0,0,0,.1)\">\n          <th style=\"text-align:left;padding:.6rem .75rem;width:34%;font-weight:600;color:var(--text2);font-size:11px;text-transform:uppercase;letter-spacing:.05em\">Deel van het gebied</th>\n          <th style=\"text-align:left;padding:.6rem .75rem;width:20%;font-weight:600;color:var(--text2);font-size:11px;text-transform:uppercase;letter-spacing:.05em\">Omvang</th>\n          <th style=\"text-align:left;padding:.6rem .75rem;width:46%;font-weight:600;color:var(--text2);font-size:11px;text-transform:uppercase;letter-spacing:.05em\">Bron</th>\n        </tr>\n      </thead>\n      <tbody>\n        <tr style=\"border-bottom:1px solid rgba(0,0,0,.05)\">\n          <td style=\"padding:.6rem .75rem;vertical-align:top\"><strong>Het hele veenweidegebied</strong></td>\n          <td style=\"padding:.6rem .75rem;vertical-align:top;color:var(--text2)\">circa 200.000 ha</td>\n          <td style=\"padding:.6rem .75rem;vertical-align:top;color:var(--text3)\">Compendium voor de Leefomgeving (CBS, PBL, WUR); CBS bodemgebruik Nederland</td>\n        </tr>\n        <tr style=\"border-bottom:1px solid rgba(0,0,0,.05)\">\n          <td style=\"padding:.6rem .75rem;vertical-align:top\"><strong>Waar de opgaven zich stapelen</strong></td>\n          <td style=\"padding:.6rem .75rem;vertical-align:top;color:var(--text2)\">20 tot 30% daarvan</td>\n          <td style=\"padding:.6rem .75rem;vertical-align:top;color:var(--text3)\">Eigen analyse VIC/JUMP, op basis van de vier vormen van druk hierboven</td>\n        </tr>\n        <tr>\n          <td style=\"padding:.6rem .75rem;vertical-align:top\"><strong>Waar geen vee meer mogelijk is</strong></td>\n          <td style=\"padding:.6rem .75rem;vertical-align:top;color:var(--text2)\">circa 10.000 ha</td>\n          <td style=\"padding:.6rem .75rem;vertical-align:top;color:var(--text3)\">Eigen analyse VIC/JUMP</td>\n        </tr>\n      </tbody>\n    </table>\n    <p style=\"font-size:11.5px;line-height:1.5;color:var(--text3);margin:.85rem 0 0\">De 200.000 hectare is de statistische telling van grasland op veen; een bodemkundige telling komt hoger uit, op 250.000 tot 360.000 hectare, afhankelijk van of moerige gronden meetellen. Twee getallen die vaak in dezelfde adem vallen: de middengroep waar dit document zich op richt bestaat uit bedrijven van 40 tot 80 hectare met 80 tot 130 koeien, en het VIC test dit zelf op ongeveer 500 hectare, een kwart procent van het gebied. Beide: eigen typologie en opgave VIC.</p>\n  </div>\n","werkstand":{"nummer":"1","ronde":"1","stand":"herzien"},"skelet":[{"nummer":"1","titel":"Waar dit over gaat","bron":"scope","stand":"ronde 1 · af","deel":"Deel I — Vooraf","kern":"Dit gebied kan meer maatschappelijke opgaven dragen dan voedsel alleen, en dat vermogen zit niet in de grond maar in de ondernemer. Hier staat wie dat zegt, hoe het zich verhoudt tot het beleid dat nu wordt uitgerold, en over welk deel van het gebied het gaat: de redenering geldt voor alle 200.000 hectare, het geld landt op 20 tot 30 procent.","secties":[{"kop":"1.1 Wat dit document voorstelt","elementen":[{"t":"dit gebied kan meer maatschappelijke opgaven dragen dan voedsel alleen, en dat vermogen zit in de ondernemer","v":"tekst","h":"auteurs","n":""},{"t":"**het openingskader zegt in één alinea voor wie dit is en wie veenweideboer is**: iedereen die in het veenweidegebied boert, want het is geen categorie maar een schaal — van melk met onbeprijsd beheer tot diensten als heel product, en elke plek erop is goed. Met de bestaande erkenning erin (wie tevreden is: prima, geen religie) en de slotregel: wij vragen dat schuiven mogelijk wordt, niet dat er geschoven wordt","v":"kader","h":"auteurs + nieuw","n":"Tim, 19-8: de \"voor wie\"-vraag en de schaal zijn één antwoord, dus één alinea. De uitwerking staat in 9.2"},{"t":"wie dit zegt en waarom: het VIC, de statutaire missie, de ambitie, JUMP","v":"kader","h":"","n":""},{"t":"de urgentie: deze ondernemers zitten nu al klem, en wie stopt komt niet terug","v":"tekst","h":"nieuw","n":""}]},{"kop":"1.2 Hoe dit zich verhoudt tot het huidige beleid","elementen":[{"t":"twee aanleidingen: de gebiedsspecifieke aanpak en het stikstofdossier","v":"tekst","h":"nieuw","n":""},{"t":"de beperkingen zijn nodig; dit is geen alternatief maar een manier om het te laten slagen","v":"tekst","h":"nieuw","n":""},{"t":"wij vragen geen euro uit de lopende middelen, wel de ruimte om de volgende ronde te bouwen","v":"tekst","h":"nieuw","n":""}]},{"kop":"1.3 Over welk deel van het gebied","elementen":[{"t":"op het grootste deel is geen groot probleem en kan melkveehouderij regulier doorgaan","v":"tekst","h":"auteurs","n":""},{"t":"de redenering geldt tóch voor het hele gebied, en de juridische ruimte ook","v":"tekst","h":"nieuw","n":""},{"t":"op 20 tot 30% stapelen vier vormen van fysieke druk; op een klein deel is geen vee meer mogelijk","v":"lijst + tabel","h":"","n":""}]}],"noot":""}],"deel":"Deel I — Vooraf"},{"id":"aannames","letter":"2","titel":"Waarop dit rust","intro":"Vier aannames dragen dit verhaal. Wij denken dat ze kloppen, en hieronder staat per aanname wat wij zien en wat er moet gebeuren om het waar te maken. Ze staan bij elkaar en vooraan, zodat de rest van het document zijn beweringen kan neerzetten zonder er bij elke zin een voorbehoud bij te maken. Zo'n voorbehoud per zin maakt een stuk namelijk onleesbaar, en het verbergt welke onzekerheden echt tellen: als alles onder voorbehoud staat, staat niets dat. Blijkt een van deze vier niet te kloppen, dan moet dit verhaal op dat punt om.","html":"\n<h2>2 — Waarop dit rust</h2>\n\n<h3>2.1 Feit, standpunt en aanname</h3>\n\n<p>Vier aannames dragen dit verhaal. Wij denken dat ze kloppen, en hieronder staat per aanname wat wij zien en wat er moet gebeuren om het waar te maken. Ze staan bij elkaar en vooraan, zodat de rest van het document zijn beweringen kan neerzetten zonder er bij elke zin een voorbehoud bij te maken. Zo'n voorbehoud per zin maakt een stuk namelijk onleesbaar, en het verbergt welke onzekerheden echt tellen: als alles onder voorbehoud staat, staat niets dat. Blijkt een van deze vier niet te kloppen, dan moet dit verhaal op dat punt om.</p>\n\n<p>Een feit, een standpunt en een aanname zijn in dit document op drie manieren kenbaar.</p>\n\n<div style=\"overflow-x:auto\">\n    <table class=\"layer-table\">\n      <thead>\n        <tr>\n          <th style=\"width:22%\">Soort bewering</th>\n          <th style=\"width:78%\">Hoe dit document het kenbaar maakt</th>\n        </tr>\n      </thead>\n      <tbody>\n        <tr>\n          <td><strong>Feit</strong></td>\n          <td>de bron staat in een fiche, en bij elk getal staat de bron of het label erbij. Waar wij zelf gerekend hebben, heet dat eigen analyse</td>\n        </tr>\n        <tr>\n          <td><strong>Standpunt</strong></td>\n          <td>de formulering zegt het: \"onze analyse\", \"wij vinden\", \"wij denken\"</td>\n        </tr>\n        <tr>\n          <td><strong>Aanname</strong></td>\n          <td>hij staat in dit hoofdstuk, met de grond eronder en met wat er nog moet gebeuren</td>\n        </tr>\n      </tbody>\n    </table>\n  </div>\n\n<h3>2.2 De vier aannames</h3>\n\n<div class=\"decision-card\" style=\"margin-bottom:12px\">\n    <div class=\"label\">Aanname 1</div>\n    <div class=\"title\" style=\"font-size:15px;line-height:1.4\">Maatschappelijke diensten kunnen een verdienmodel dragen</div>\n    <p style=\"font-size:13.5px;line-height:1.65;margin:.7rem 0 0\">Wij denken dat een bedrijf een substantieel en langjarig deel van zijn inkomen kan halen uit wat het aan de samenleving levert, naast voedsel. Dat lijkt op wat er al bestaat, en dat is het niet. Voor weidevogel- en landschapsbeheer gaat er wel publiek geld naar boerenland, maar die regeling vergoedt de kosten van het beheer, de gederfde inkomsten en de transactiekosten, en een winstmarge is daarin geen post.<span class=\"fiche-wrap\"><button class=\"fiche-btn\" type=\"button\" aria-label=\"Bron tonen\">ⓘ</button><span class=\"fiche-popup\"><span class=\"fiche-label\">Bron</span><span class=\"fiche-source\">Subsidieregeling natuur- en landschapsbeheer, artikel 3.5 (provinciale regeling; hier Overijssel 2024): subsidiabel zijn de kosten van de beheeractiviteiten, de gederfde inkomsten en de transactiekosten. Europese grondslag: GLB-verordening (EU) 2021/2115, artikel 70, over milieu-, klimaat- en andere beheersverbintenissen.</span><span class=\"fiche-note\">Bij natuurbeheer onder het Subsidiestelsel Natuur en Landschap bedraagt het tarief 84 procent van de standaardkostprijs (BIJ12); de ANLb-tarieven stellen de provincies jaarlijks vast. BoerenNatuur en drie collectieven stelden in 2023 dat het stelsel bij intensief weidevogelbeheer de kosten en de gederfde inkomsten niet dekt.</span></span></span> Wij verwachten dat het bedrag anders wordt bepaald: niet afgeleid van wat de ondernemer misloopt, maar van wat de dienst voor de afnemer (lees: de maatschappij) waard is. Of dat juridisch kan, is aanname 4.</p>\n    <p style=\"font-size:13.5px;line-height:1.65;margin:.55rem 0 0\"><strong>Wat wij zien.</strong> Een maatschappelijke dienst is als product te omschrijven. Bij water is dat het duidelijkst: zelfvoorzienendheid van een gebied is te meten, in een contract te zetten en af te rekenen op een prestatie. En het apparaat om zo’n dienst te leveren en te controleren staat er al, met collectieven, beheerpakketten en toezicht. De sector vraagt zelf al om die andere manier van rekenen.</p>\n    <p style=\"font-size:13.5px;line-height:1.65;margin:.55rem 0 0\"><strong>Wat er moet gebeuren om dit te laten werken.</strong> Een prijs die hoog genoeg is, een looptijd die lang genoeg is, en meten en beoordelen die niet zoveel kosten dat er van de dienst weinig overblijft. Één contract met zo’n prijs en een afrekenbare prestatie is het bewijs.</p>\n  </div>\n\n<div class=\"decision-card\" style=\"margin-bottom:12px\">\n    <div class=\"label\">Aanname 2</div>\n    <div class=\"title\" style=\"font-size:15px;line-height:1.4\">Naast de overheid komt er een tweede geldstroom uit de markt</div>\n    <p style=\"font-size:13.5px;line-height:1.65;margin:.7rem 0 0\">Waar aanname 1 over de aard van de betaling gaat, gaat deze over de herkomst van het geld. Wij verwachten dat een deel van de opdrachten van private partijen komt: afnemers die zelf een doel hebben dat zij zonder dit gebied niet halen. Een markt ontstaat op twee voorwaarden, een afnemer met een eigen belang en een kader waarin de transactie is vast te leggen. Blijft die tweede geldstroom weg, dan hangt het model volledig aan de overheid en levert de ondernemer zijn zelfstandigheid in; dat risico staat in hoofdstuk 14.</p>\n    <p style=\"font-size:13.5px;line-height:1.65;margin:.55rem 0 0\"><strong>Wat wij zien.</strong> Bij water is de afnemer er al. Oasen wint zijn drinkwater als oevergrondwater midden in dit gebied, in de Krimpenerwaard en de Alblasserwaard, en Waternet haalt ongeveer een derde van het zijne uit de Bethunepolder in het Utrechtse veenweide. Betalen doen zij vandaag alleen voor schade, want dat is wettelijk verplicht, en niet voor een geleverde dienst. Die stap is elders wel gezet: Vitens draagt bij aan de meerkosten van precisietoepassing in grondwaterbeschermingsgebieden, en in de Achterhoek worden grondeigenaren per hectare betaald voor zes blauwe diensten.<span class=\"fiche-wrap\"><button class=\"fiche-btn\" type=\"button\" aria-label=\"Bron tonen\">ⓘ</button><span class=\"fiche-popup\"><span class=\"fiche-label\">Bron</span><span class=\"fiche-source\">Vitens, pagina Landbouw, 2026: een bijdrage van 25 euro per hectare voor spotspray in uitspoelingsgevoelige grondwaterbeschermingsgebieden in 2025 en 2026, de helft van de meerkosten. In het gebied 't Klooster betalen provincie Gelderland, Vitens en waterschap Rijn en IJssel grondeigenaren per hectare voor zes blauwe diensten, drie jaar vanaf 1 januari 2026, uitgevoerd via VALA (Waterforum, 12 januari 2026). Beide op zandgrond.</span><span class=\"fiche-note\">In het veenweidegebied bestaat zo'n regeling nog niet. Oasen wint ook bij Kamerik in Utrecht en betaalt agrariërs uitsluitend de wettelijk verplichte droogteschade bij grondwateronttrekking. Dunea staat hier niet bij: dat bedrijf neemt water in uit de Afgedamde Maas en de Lek en beschermt zijn bron stroomopwaarts in de Bommelerwaard, buiten het veen.</span></span></span> Bij koolstof komt het kader eraan, met een Europees certificeringsstelsel in de maak en Valuta voor Veen als bestaande Nederlandse route. In de zuivelketen hangt de Biodiversiteitsmonitor al aan de melkprijs, en dat is betalen voor een prestatie, ook al heet het zo niet. Banken hebben zelf belang bij een langjarig prestatiecontract, want dat is onderpand. De partijen staan in hoofdstuk 12. Vandaag is die markt nog dun, en voor biodiversiteit is er nauwelijks een afnemer.</p>\n    <p style=\"font-size:13.5px;line-height:1.65;margin:.55rem 0 0\"><strong>Wat er moet gebeuren om dit te laten werken.</strong> Er moet één private partij zijn die betaalt voor een geleverde dienst in plaats van voor schade, met een contract dat navolgbaar is voor de volgende. Dat weerlegt tegelijk het weerwoord dat dit subsidie met een ander etiket is.</p>\n  </div>\n\n<div class=\"decision-card\" style=\"margin-bottom:12px\">\n    <div class=\"label\">Aanname 3</div>\n    <div class=\"title\" style=\"font-size:15px;line-height:1.4\">De middengroep is het onderwerp van deze visie</div>\n    <p style=\"font-size:13.5px;line-height:1.65;margin:.7rem 0 0\">Wij denken dat juist de middengroep de groep is die deze omslag gaat maken: de familiebedrijven van 40 tot 80 hectare met 80 tot 130 koeien, die 70 tot 80 procent van alle melkveebedrijven in dit gebied vormen. Zij zijn het onderwerp van dit document, en dat is een keuze.</p>\n    <p style=\"font-size:13.5px;line-height:1.65;margin:.55rem 0 0\"><strong>Wat wij zien.</strong> De vorm van de populatie, beschreven in hoofdstuk 3. De grote bedrijven, met meer dan 250 koeien en een groei richting 500 en meer, ondernemen op volume en hebben het kapitaal om die weg verder te gaan. De kleine nichebedrijven, onder de 70 koeien, hebben hun eigen markt, waar marge en een bijzonder product het werk doen. Beide hebben een werkend bedrijfsmodel en hebben deze visie niet nodig. Daartussen zit de groep die geen van beide routes open heeft; daar moet dus een ander bedrijfsmodel vandaan komen. De maten zijn onze eigen typologie, uitgewerkt in hoofdstuk 9.</p>\n    <p style=\"font-size:13.5px;line-height:1.65;margin:.55rem 0 0\"><strong>Wat er moet gebeuren om dit te laten werken.</strong> Deze groep moet de omslag zelf willen maken; hoofdstuk 13 gaat daarover. En het percentage moet onderbouwd worden. [[CIJFER: onderbouwing van het aandeel van de middengroep, 70 tot 80 procent van de bedrijven; niet bevestigd en niet weerlegd]]</p>\n  </div>\n\n<div class=\"decision-card\" style=\"margin-bottom:12px\">\n    <div class=\"label\">Aanname 4</div>\n    <div class=\"title\" style=\"font-size:15px;line-height:1.4\">De Europese regels gaan opdrachten voor maatschappelijke diensten toestaan</div>\n    <p style=\"font-size:13.5px;line-height:1.65;margin:.7rem 0 0\">Wij denken dat het Europese kader hierin meebeweegt: dat een overheid een maatschappelijke dienst bij een agrarisch ondernemer kan inkopen als opdracht, met een prijs en een prestatie, in plaats van alleen kosten en gederfde inkomsten te vergoeden. Binnen de huidige kaders kan dat niet zonder meer, en dat weten wij.</p>\n    <p style=\"font-size:13.5px;line-height:1.65;margin:.55rem 0 0\"><strong>Wat wij zien.</strong> De regels volgen de doelen. Europa stelt zelf doelen voor water, klimaat en biodiversiteit die zonder de grondgebruiker niet te halen zijn, en er komen kaders aan die zulke prestaties certificeerbaar maken. Het instrument zelf is niet nieuw: een overheid die een dienst inkoopt bij een private partij, is in elke andere sector gewoon.</p>\n    <p style=\"font-size:13.5px;line-height:1.65;margin:.55rem 0 0\"><strong>Wat er moet gebeuren om dit te laten werken.</strong> De wet en de kaders moeten worden aangepast, zodat een overheid een maatschappelijke dienst als opdracht kan inkopen. Zolang dat niet zo is, blijft de subsidieroute de tweede weg; beide staan in hoofdstuk 11.</p>\n  </div>\n","werkstand":{"nummer":"2","ronde":"1","stand":"herzien; 1 markering open (onderbouwing 70-80%)"},"skelet":[{"nummer":"2","titel":"Waarop dit rust","bron":"aannames","stand":"ronde 1 · af","deel":"Deel I — Vooraf","kern":"Vier aannames dragen dit verhaal. Wij zeggen ze stellig en zetten eronder waarop wij ze baseren; valt er één, dan moet het verhaal op dat punt om. Wat er moet gebeuren om ze waar te maken staat niet hier maar achteraan, in hoofdstuk 14.","secties":[{"kop":"2.1 Feit, standpunt en aanname","elementen":[{"t":"vier aannames dragen dit verhaal; valt er één, dan moet het verhaal op dat punt om","v":"tekst","h":"nieuw","n":""},{"t":"hoe dit document een feit, een standpunt en een aanname kenbaar maakt","v":"tabel","h":"","n":""}]},{"kop":"2.2 De vier aannames","elementen":[{"t":"1 diensten kunnen een verdienmodel dragen · 2 naast de overheid komt er een tweede geldstroom uit de markt","v":"kaarten","h":"","n":""},{"t":"3 de middengroep is het onderwerp van deze visie · 4 de Europese regels gaan opdrachten toestaan","v":"kaarten","h":"","n":""},{"t":"per aanname: wat wij denken, en **wat wij zien** waarop wij dat baseren","v":"kaarten","h":"","n":""},{"t":"**wat er moet gebeuren om het te laten werken staat niet hier maar in hoofdstuk 14**, met één regel per aanname die daarheen wijst","v":"tekst","h":"nieuw","n":"besluit 19-8: dit hoofdstuk zegt waarop het rust, de agenda staat achteraan"}]}],"noot":""}],"deel":"Deel I — Vooraf"},{"id":"intro","letter":null,"titel":"Wachtkamer — wat er over is van de oude intro","intro":"Dit is geen hoofdstuk. Hier staat wat nog een bestemming zoekt: het stikstofdossier gaat naar het sluitstuk, het begrippenkader naar de bijlage. Zodra dat gebeurd is, verdwijnt deze wachtkamer.","html":"\n<h2>Wachtkamer — wat er over is van de oude intro</h2>\n\n<p><em>Dit is geen hoofdstuk. Hier staat wat nog een bestemming zoekt: het stikstofdossier gaat naar het sluitstuk, het begrippenkader naar de bijlage. Zodra dat gebeurd is, verdwijnt deze wachtkamer.</em></p>\n\n<div style=\"background:var(--bg2);border-left:3px solid var(--text2);border-radius:var(--radius);padding:1.25rem 1.5rem;margin:1rem 0 0;font-size:13.5px;line-height:1.65\">\n    <strong style=\"display:block;margin-bottom:6px;font-size:14px\">Daarnaast: het stikstofdossier, raakvlak met dit verhaal</strong>\n    <p style=\"margin:0 0 .75rem\">Naast het driesporenbeleid loopt een tweede dossier dat dit verhaal raakt zonder ermee samen te vallen: stikstof. Het is op dit moment het politiek meest urgente dossier in Nederland — bouwen, uitbreiding van het stroomnet, defensie-investeringen, industriële ontwikkeling lopen vrijwel allemaal vast op stikstofruimte. Wie stikstof oplost, ontklemt een groot deel van het land. De aanpak focust op gebieden grenzend aan natuur, waar minder ammoniak de meeste reductie oplevert. Dat zijn deels veenweidegebieden in Natura 2000-bufferzones, maar even nadrukkelijk ook zandgebieden (Veluwerand, Brabantse Peelrand, Drenthe-randen) en kleigebieden in vergelijkbare ligging. De twee dossiers overlappen op de randen, maar de zwaartepunten liggen elders.</p>\n    <p style=\"margin:0\"><strong>Voor dit verhaal is stikstof zowel rugwind als risico.</strong> Rugwind, omdat het politieke gewicht en de financiering nu aanwezig zijn om de transitie in beweging te zetten. Risico, omdat een eenzijdige stikstof-focus de zeven maatschappelijke opgaves overschaduwt — en omdat het mechanisme waarmee stikstof wordt opgelost (minder koeien, dus boeren weg) precies de dragers verwijdert die nodig zijn om die opgaves overeind te houden. Het scherpst geformuleerd: <em>stikstofbeleid zonder breder ondernemersperspectief is akte II onder een nieuwe naam.</em> Stikstof verdient daarom een plek in dit verhaal — niet als aparte opgave naast de zeven, en niet als onderdeel van het driesporenbeleid, maar als zelfstandig dossier dat het veenweide-dossier deels raakt en deels overstijgt.</p>\n  </div>\n\n<!-- BEGRIPPENKADER (A2, Anna) -->\n\n<div style=\"background:var(--bg3);border:1px solid rgba(0,0,0,.06);border-radius:var(--radius-lg);padding:1.25rem 1.5rem;margin:1.5rem 0 0\">\n  <p style=\"font-family:var(--font-display);font-size:15px;font-weight:600;color:var(--text);margin:0 0 .75rem\">Begrippenkader — de dragende termen in dit document</p>\n  <table style=\"width:100%;border-collapse:collapse;font-size:13px;line-height:1.55\">\n    <tbody>\n    <tr><td style=\"padding:.3rem .75rem .3rem 0;white-space:nowrap;vertical-align:top\"><strong>Veenweideboer</strong></td><td style=\"padding:.3rem 0;color:var(--text2)\">Bedrijfsmodel, geen geografische aanduiding: voedsel én maatschappelijke diensten als gelijkwaardige producten, met lagere veedichtheid.</td></tr>\n    <tr><td style=\"padding:.3rem .75rem .3rem 0;white-space:nowrap;vertical-align:top\"><strong>Maatschappelijke opgaves</strong></td><td style=\"padding:.3rem 0;color:var(--text2)\">De zeven opgaves voor het gebied: klimaat, water, natuur, voedselzekerheid, cultuur &amp; landschap, grondstoffen &amp; kringloop, wonen.</td></tr>\n    <tr><td style=\"padding:.3rem .75rem .3rem 0;white-space:nowrap;vertical-align:top\"><strong>Maatschappelijke diensten</strong></td><td style=\"padding:.3rem 0;color:var(--text2)\">Wat de boer levert: koolstofopslag, schoon water, biodiversiteit, landschap.</td></tr>\n    <tr><td style=\"padding:.3rem .75rem .3rem 0;white-space:nowrap;vertical-align:top\"><strong>Maatschappelijke opdrachten</strong></td><td style=\"padding:.3rem 0;color:var(--text2)\">Het contractinstrument waarmee de overheid die diensten inkoopt.</td></tr>\n    <tr><td style=\"padding:.3rem .75rem .3rem 0;white-space:nowrap;vertical-align:top\"><strong>Sporen (1, 2, 3)</strong></td><td style=\"padding:.3rem 0;color:var(--text2)\">Het driesporenbeleid van het Rijk. Arabische cijfers, altijd.</td></tr>\n    <tr><td style=\"padding:.3rem .75rem .3rem 0;white-space:nowrap;vertical-align:top\"><strong>Aktes (I, II, III)</strong></td><td style=\"padding:.3rem 0;color:var(--text2)\">De drie verhaallijnen van dit document: doorgaan op de huidige weg (I), ingrijpen zonder pijlers (II), ingrijpen mét pijlers (III). Romeinse cijfers, altijd.</td></tr>\n    <tr><td style=\"padding:.3rem .75rem .3rem 0;white-space:nowrap;vertical-align:top\"><strong>Het kader / de pijlers</strong></td><td style=\"padding:.3rem 0;color:var(--text2)\">De zes lagen die de overheid moet leggen: maatregelen, doelen, juridische ruimte, vangnet, opdrachten en coördinatie (F2).</td></tr>\n    <tr><td style=\"padding:.3rem .75rem .3rem 0;white-space:nowrap;vertical-align:top\"><strong>Toolbox / bouwstenen</strong></td><td style=\"padding:.3rem 0;color:var(--text2)\">De instrumenten waarmee de ondernemer de doelen haalt (F1).</td></tr>\n    <tr><td style=\"padding:.3rem .75rem .3rem 0;white-space:nowrap;vertical-align:top\"><strong>Doelsturing</strong></td><td style=\"padding:.3rem 0;color:var(--text2)\">De overheid stuurt op wát geleverd wordt; de boer bepaalt hóe.</td></tr>\n    <tr><td style=\"padding:.3rem .75rem .3rem 0;white-space:nowrap;vertical-align:top\"><strong>JUMP</strong></td><td style=\"padding:.3rem 0;color:var(--text2)\">Het VIC-programma met vergaande bedrijfsconcepten — mét en zonder dieren — richting 2040–2045; dit document vertaalt die bouwstenen naar de komende vijf jaar.</td></tr>\n    </tbody>\n  </table>\n</div>\n","werkstand":{"nummer":"—","ronde":"—","stand":"wachtkamer, hoort leeg te raken; nog 2 blokken (stikstofdossier → ronde 4, begrippen → bijlage 16.4). Routering in de correctielijst"}},{"id":"a-klem","letter":"3","titel":"Waarom de ondernemer klem komt te zitten","intro":"In het Nederlandse veenweidegebied loopt de overgrote meerderheid van de melkveebedrijven vast op kosten en omzet. Dat is deels hoe het systeem uitpakt en deels het gevolg van eigen keuzes in schaal, financiering en tempo. Wie loopt vast, en waarom?","html":"\n<h2>3 — Waarom de ondernemer klem komt te zitten</h2>\n\n<h3>3.1 Om welke bedrijven het gaat</h3>\n\n<p>In het Nederlandse veenweidegebied loopt de overgrote meerderheid van de melkveebedrijven vast op kosten en omzet. Dat is deels hoe het systeem uitpakt en deels het gevolg van eigen keuzes in schaal, financiering en tempo. Wie loopt vast, en waarom?</p>\n\n<!-- POPULATIEMODEL SVG -->\n\n<div style=\"background:var(--bg3);border:1px solid rgba(0,0,0,.06);border-radius:var(--radius-lg);padding:1.5rem;margin:1rem 0 1.5rem;overflow-x:auto\">\n    <p style=\"font-family:var(--font-display);font-size:15px;font-weight:600;color:var(--text);text-align:center;margin:0 0 1rem\">Ontwikkeling melkveehouderij in het veenweidegebied tot 2040</p>\n    <svg viewBox=\"0 0 780 340\" style=\"width:100%;display:block\" xmlns=\"http://www.w3.org/2000/svg\">\n      <defs>\n        <marker id=\"arrowR\" markerWidth=\"8\" markerHeight=\"6\" refX=\"7\" refY=\"3\" orient=\"auto\"><path d=\"M0,0 L8,3 L0,6\" fill=\"#5C5A54\"></path></marker>\n      </defs>\n\n      <!-- Tijdslabels -->\n      <text x=\"160\" y=\"315\" text-anchor=\"middle\" font-family=\"var(--font-display)\" font-size=\"14\" font-weight=\"700\" fill=\"var(--text)\">Vandaag</text>\n      <text x=\"640\" y=\"315\" text-anchor=\"middle\" font-family=\"var(--font-display)\" font-size=\"14\" font-weight=\"700\" fill=\"var(--text)\">2040</text>\n\n      <!-- ═══════════ BOVENSTE BAND: BULKMARKT ═══════════ -->\n      <!-- Annotaties links van bolletje -->\n      <text x=\"105\" y=\"42\" text-anchor=\"end\" font-family=\"var(--font-body)\" font-size=\"9.5\" fill=\"var(--text3)\">&gt;250 koeien</text>\n      <text x=\"105\" y=\"52\" text-anchor=\"end\" font-family=\"var(--font-body)\" font-size=\"9.5\" fill=\"var(--text3)\">schaalgedreven</text>\n      <!-- Cirkel links -->\n      <circle cx=\"160\" cy=\"46\" r=\"18\" fill=\"#5C5A54\" opacity=\"0.1\" stroke=\"#5C5A54\" stroke-width=\"1.5\"></circle>\n      <text x=\"160\" y=\"42\" text-anchor=\"middle\" font-family=\"var(--font-body)\" font-size=\"10.5\" fill=\"#5C5A54\" font-weight=\"600\">~5–7%</text>\n      <text x=\"160\" y=\"52\" text-anchor=\"middle\" font-family=\"var(--font-body)\" font-size=\"8.5\" fill=\"#5C5A54\">bulkmarkt</text>\n      <!-- Pijl links -->\n      <line x1=\"180\" y1=\"46\" x2=\"310\" y2=\"46\" stroke=\"#5C5A54\" stroke-width=\"1.5\" opacity=\"0.4\"></line>\n      <!-- Strategievak: groen -->\n      <rect x=\"312\" y=\"30\" width=\"195\" height=\"26\" rx=\"4\" fill=\"var(--accent-light)\" stroke=\"var(--accent)\" stroke-width=\"1\"></rect>\n      <text x=\"410\" y=\"47\" text-anchor=\"middle\" font-family=\"var(--font-body)\" font-size=\"10\" fill=\"var(--accent2)\" font-weight=\"500\">groeien in melkproductie, koeien en land</text>\n      <!-- Pijl rechts -->\n      <line x1=\"509\" y1=\"46\" x2=\"613\" y2=\"46\" stroke=\"#5C5A54\" stroke-width=\"1.5\" opacity=\"0.4\" marker-end=\"url(#arrowR)\"></line>\n      <!-- Cirkel rechts -->\n      <circle cx=\"640\" cy=\"46\" r=\"22\" fill=\"#5C5A54\" opacity=\"0.08\" stroke=\"#5C5A54\" stroke-width=\"1.5\"></circle>\n      <text x=\"640\" y=\"42\" text-anchor=\"middle\" font-family=\"var(--font-body)\" font-size=\"10.5\" fill=\"#5C5A54\" font-weight=\"600\">~15%</text>\n      <text x=\"640\" y=\"52\" text-anchor=\"middle\" font-family=\"var(--font-body)\" font-size=\"8.5\" fill=\"#5C5A54\">bulkmarkt</text>\n      <!-- Annotatie rechts -->\n      <text x=\"670\" y=\"46\" font-family=\"var(--font-body)\" font-size=\"9.5\" fill=\"var(--text3)\">&gt;500 koeien</text>\n\n      <!-- ═══════════ MIDDELSTE BAND: MIDDENGROEP ═══════════ -->\n      <!-- Cirkel links -->\n      <circle cx=\"160\" cy=\"170\" r=\"55\" fill=\"#5C5A54\" opacity=\"0.06\" stroke=\"#5C5A54\" stroke-width=\"1.5\"></circle>\n      <text x=\"160\" y=\"155\" text-anchor=\"middle\" font-family=\"var(--font-body)\" font-size=\"12\" fill=\"#3F3D38\" font-weight=\"700\">~70–80%</text>\n      <text x=\"160\" y=\"170\" text-anchor=\"middle\" font-family=\"var(--font-body)\" font-size=\"10.5\" fill=\"#5C5A54\" font-weight=\"500\">middengroep</text>\n      <text x=\"160\" y=\"185\" text-anchor=\"middle\" font-family=\"var(--font-body)\" font-size=\"9.5\" fill=\"var(--text3)\">40–80 ha, 80–130 koeien</text>\n      <!-- Pijl links, dan de drie routes uit hoofdstuk 13, dan de pijl verder -->\n      <line x1=\"217\" y1=\"170\" x2=\"271\" y2=\"170\" stroke=\"#5C5A54\" stroke-width=\"1.5\" opacity=\"0.4\"></line>\n\n      <rect x=\"273\" y=\"133\" width=\"264\" height=\"26\" rx=\"4\" fill=\"var(--amber-light)\" stroke=\"var(--amber)\" stroke-width=\"1\"></rect>\n      <text x=\"405\" y=\"150\" text-anchor=\"middle\" font-family=\"var(--font-body)\" font-size=\"10.5\" fill=\"#5C5A54\" font-weight=\"500\">doorgaan zoals het is</text>\n\n      <rect x=\"273\" y=\"163\" width=\"264\" height=\"26\" rx=\"4\" fill=\"#5C5A54\" fill-opacity=\"0.06\" stroke=\"#5C5A54\" stroke-width=\"1\" stroke-opacity=\"0.5\"></rect>\n      <text x=\"405\" y=\"180\" text-anchor=\"middle\" font-family=\"var(--font-body)\" font-size=\"10.5\" fill=\"#5C5A54\" font-weight=\"500\">stoppen</text>\n\n      <rect x=\"273\" y=\"193\" width=\"264\" height=\"26\" rx=\"4\" fill=\"var(--accent-light)\" stroke=\"var(--accent)\" stroke-width=\"1\"></rect>\n      <text x=\"405\" y=\"210\" text-anchor=\"middle\" font-family=\"var(--font-body)\" font-size=\"10\" fill=\"var(--accent2)\" font-weight=\"600\">maatschappelijke diensten erbij, van klein tot volledig</text>\n\n      <line x1=\"539\" y1=\"170\" x2=\"593\" y2=\"170\" stroke=\"#5C5A54\" stroke-width=\"1.5\" opacity=\"0.4\" marker-end=\"url(#arrowR)\"></line>\n      <!-- Cirkel rechts -->\n      <circle cx=\"640\" cy=\"170\" r=\"42\" fill=\"#5C5A54\" opacity=\"0.04\" stroke=\"#5C5A54\" stroke-width=\"1.5\"></circle>\n      <text x=\"640\" y=\"162\" text-anchor=\"middle\" font-family=\"var(--font-body)\" font-size=\"11\" fill=\"#3F3D38\" font-weight=\"700\">~55–70%</text>\n      <text x=\"640\" y=\"176\" text-anchor=\"middle\" font-family=\"var(--font-body)\" font-size=\"9.5\" fill=\"#5C5A54\">middengroep</text>\n      <!-- Gestippelde pijl naar bulk -->\n      <path d=\"M200,128 C300,110 480,75 615,52\" stroke=\"#5C5A54\" stroke-width=\"0.8\" fill=\"none\" opacity=\"0.3\" stroke-dasharray=\"4 3\"></path>\n      <!-- Gestippelde pijl naar niche -->\n      <path d=\"M200,215 C300,235 480,255 615,272\" stroke=\"#5C5A54\" stroke-width=\"0.8\" fill=\"none\" opacity=\"0.3\" stroke-dasharray=\"4 3\"></path>\n\n      <!-- ═══════════ ONDERSTE BAND: NICHEMARKT ═══════════ -->\n      <!-- Annotaties links van bolletje -->\n      <text x=\"105\" y=\"270\" text-anchor=\"end\" font-family=\"var(--font-body)\" font-size=\"9.5\" fill=\"var(--text3)\">&lt;70 koeien</text>\n      <text x=\"105\" y=\"280\" text-anchor=\"end\" font-family=\"var(--font-body)\" font-size=\"9.5\" fill=\"var(--text3)\">extensief, niche</text>\n      <!-- Cirkel links -->\n      <circle cx=\"160\" cy=\"275\" r=\"18\" fill=\"#5C5A54\" opacity=\"0.1\" stroke=\"#5C5A54\" stroke-width=\"1.5\"></circle>\n      <text x=\"160\" y=\"271\" text-anchor=\"middle\" font-family=\"var(--font-body)\" font-size=\"10.5\" fill=\"#5C5A54\" font-weight=\"600\">~15%</text>\n      <text x=\"160\" y=\"281\" text-anchor=\"middle\" font-family=\"var(--font-body)\" font-size=\"8.5\" fill=\"#5C5A54\">nichemarkt</text>\n      <!-- Pijl links -->\n      <line x1=\"180\" y1=\"275\" x2=\"310\" y2=\"275\" stroke=\"#5C5A54\" stroke-width=\"1.5\" opacity=\"0.4\"></line>\n      <!-- Strategievak: groen -->\n      <rect x=\"312\" y=\"260\" width=\"195\" height=\"26\" rx=\"4\" fill=\"var(--accent-light)\" stroke=\"var(--accent)\" stroke-width=\"1\"></rect>\n      <text x=\"410\" y=\"277\" text-anchor=\"middle\" font-family=\"var(--font-body)\" font-size=\"10\" fill=\"var(--accent2)\" font-weight=\"500\">niche versterken en uitbreiden</text>\n      <!-- Pijl rechts -->\n      <line x1=\"509\" y1=\"275\" x2=\"613\" y2=\"275\" stroke=\"#5C5A54\" stroke-width=\"1.5\" opacity=\"0.4\" marker-end=\"url(#arrowR)\"></line>\n      <!-- Cirkel rechts -->\n      <circle cx=\"640\" cy=\"275\" r=\"22\" fill=\"#5C5A54\" opacity=\"0.08\" stroke=\"#5C5A54\" stroke-width=\"1.5\"></circle>\n      <text x=\"640\" y=\"271\" text-anchor=\"middle\" font-family=\"var(--font-body)\" font-size=\"10.5\" fill=\"#5C5A54\" font-weight=\"600\">~15–20%</text>\n      <text x=\"640\" y=\"281\" text-anchor=\"middle\" font-family=\"var(--font-body)\" font-size=\"8.5\" fill=\"#5C5A54\">nichemarkt</text>\n\n    </svg>\n    <p style=\"font-size:12px;color:var(--text3);margin-top:8px;text-align:center\">Percentages tonen het aandeel binnen de sector. De sector als geheel krimpt ook in absolute aantallen, minder bedrijven in 2040 dan vandaag. De middengroep krimpt het sterkst. De drie routes staan uitgewerkt in hoofdstuk 13.</p>\n  </div>\n\n<p>Een kleine groep grote boeren (meer dan 250 koeien, schaalgedreven, gericht op de bulkmarkt) groeit vanzelf, schaalvergroting duwt ze richting 500+ koeien. Een relatief kleine groep nicheboeren (minder dan 70 koeien, een lage veedichtheid, gericht op specifieke markten) groeit alleen als het beleid dat mogelijk maakt. Zij hebben al een werkend bedrijfsmodel; dit document gaat daarom over de groep die dat niet heeft. De middengroep — de 40-80 hectare bedrijven met 80-130 koeien — krimpt hoe dan ook. De vraag is niet óf ze krimpt, maar welke toekomst er is voor de ondernemers die de schaalsprong niet willen of kunnen maken.</p>\n\n<h3>3.2 Waarom het zakelijk niet meer vol te houden is</h3>\n\n<p>Dat de middengroep klem zit is geen toeval en geen persoonlijk falen. Vergelijking met andere Europese landen — zoals Oostenrijk, Frankrijk en Noord-Italië — laat zien dat de richting van de melkveehouderij in elk land bepaald wordt door drie samenhangende condities: de grondmarkt, het beleidskader en de ketenstructuur. Nederland is daarin een extreme variant, niet het gemiddelde.</p>\n\n<div style=\"display:grid;grid-template-columns:repeat(3,1fr);gap:12px;margin:1rem 0 1.5rem\">\n    <div style=\"background:var(--bg3);border:1px solid rgba(0,0,0,.06);border-radius:var(--radius);padding:1rem;font-size:12.5px;line-height:1.5\">\n      <div style=\"font-weight:600;color:var(--text);margin-bottom:4px\">Grondmarkt</div>\n      <div style=\"color:var(--text2)\">Grond is schaars en duur. Dat dwingt tot maximale productie per hectare. Niet groeien betekent relatief duur produceren. Het systeem duwt richting schaal, niet uit keuze, maar uit noodzaak.</div>\n    </div>\n    <div style=\"background:var(--bg3);border:1px solid rgba(0,0,0,.06);border-radius:var(--radius);padding:1rem;font-size:12.5px;line-height:1.5\">\n      <div style=\"font-weight:600;color:var(--text);margin-bottom:4px\">Beleidskader</div>\n      <div style=\"color:var(--text2)\">Historisch gericht op productie en efficiëntie, niet op begrenzing van schaal. Een rem bestond wél: de bergboerenregeling voor natuurlijke handicaps, die ook hier gold. Zij was klein en verdween per 2014;<span class=\"fiche-wrap\"><button class=\"fiche-btn\" type=\"button\" aria-label=\"Bron tonen\">ⓘ</button><span class=\"fiche-popup\"><span class=\"fiche-label\">Bron</span><span class=\"fiche-source\">De bergboerenregeling is de Nederlandse uitvoering van het Europese probleemgebiedenbeleid, dat sinds 1975 bestaat (richtlijn 75/268/EEG) en in 2007-2013 liep als maatregel 212 van het Plattelandsontwikkelingsprogramma, betalingen aan landbouwers in gebieden met natuurlijke handicaps (verordening (EG) 1698/2005). De vergoeding was € 94 per hectare per jaar en was gekoppeld aan de Subsidieregeling Agrarisch Natuurbeheer. Ruim 6.000 bedrijven maakten er gebruik van; in 2006 ontving een derde van het aangewezen probleemgebied de premie. Bron: LEI, I.J. Terluin, *De bergboerenregeling in Nederland*, 2008.</span><span class=\"fiche-note\">Het veenweidegebied zat er wél in: in Midden-Delfland was 3.698 hectare aangewezen als probleemgebied, met de landschapskenmerken van het veenweidegebied als handicap, tegen dezelfde € 94 per hectare. Met de overgang van het natuurbeleid naar de provincies per 2014 verviel het budget; de provincie Fryslân stelde in 2019 na een rechterlijke uitspraak nog een afbouwregeling vast die de jaren 2014 tot 2016 met 75, 50 en 25 procent afbouwde.</span></span></span> in Oostenrijk bestaat zij nog.</div>\n    </div>\n    <div style=\"background:var(--bg3);border:1px solid rgba(0,0,0,.06);border-radius:var(--radius);padding:1rem;font-size:12.5px;line-height:1.5\">\n      <div style=\"font-weight:600;color:var(--text);margin-bottom:4px\">Ketenstructuur</div>\n      <div style=\"color:var(--text2)\">De zuivelketen beloont volume en efficiëntie. Zolang de keten bulk en liters beloont, blijft de druk op schaalvergroting bestaan. Nichemarkten zijn de enige structurele tegenkracht, maar die moeten bewust gebouwd worden.</div>\n    </div>\n  </div>\n\n<p>Die drie condities duwen van buitenaf richting schaal. Wat decennialang het gaspedaal was, werkt nu als de rem. Van binnenuit loopt het systeem óók vast: opvolging wordt onbetaalbaar bij kapitaalintensieve bedrijven, de grondmarkt raakt minder liquide, externe investeerders komen in beeld. Het loopt dus niet alleen vast op deze drie condities maar ook op zichzelf. Dat raakt niet alleen wat Nederland van dit gebied vraagt; het is als bedrijfsmodel niet vol te houden.</p>\n\n<p>En de uitweg die zich het eerst aandient is er geen. Minder koeien per hectare betekent minder melk per hectare, terwijl de grond, de gebouwen en de financiering hetzelfde blijven kosten. Precies die kostenstructuur is wat de drie condities hebben opgebouwd, en daarom daalt het inkomen zodra de veedichtheid omlaag gaat en er niets betaalds naast staat. Dat is een rekensom, geen aanname, en het is de reden dat dit document over geld gaat en niet over goede wil.</p>\n\n<h3>3.3 Waar de uitdaging het scherpst is</h3>\n\n<p>Die rekensom geldt voor elk bedrijf dat de veedichtheid verlaagt. Het verschil zit in de vraag of die verlaging een keuze is of niet. Op het grootste deel van het veenweidegebied is er een keuze: daar kan reguliere melkveehouderij door, aangepast maar herkenbaar, en hoofdstuk 1 zet die verhouding neer. Dit hoofdstuk gaat over het deel waar de omstandigheden zelf een ander bedrijfsmodel vragen. Dat zijn gebieden waar één of meer van de volgende kenmerken spelen:</p>\n\n<ul style=\"margin:.75rem 0 .75rem 1.25rem;font-size:14px;line-height:1.8;color:var(--text2)\">\n    <li><strong>Gebieden die structureel te nat worden</strong> — vanuit beleid (verhoging van het slootwaterpeil) of vanuit autonome vernatting waardoor reguliere bedrijfsvoering structureel onhaalbaar wordt</li>\n    <li><strong>Ligging in of tegen Natura 2000</strong> — in het gebied zelf of in de bufferzones eromheen, waar extra regeldruk en beperkingen op stikstof en grondgebruik de bedrijfsvoering inperken</li>\n    <li><strong>Sterke kwel en verzilting</strong> — waar waterdruk van onderaf de bedrijfsvoering structureel beïnvloedt — hier zijn nieuwe bedrijfsconcepten sowieso nodig, zelfs zonder enige klimaat- of peildoelstelling</li>\n    <li><strong>Stedelijke randen</strong> — waar waterberging, ruimtedruk en functiemenging samenkomen</li>\n    <li><strong>Snelste bodemdaling en veenoxidatie</strong> — zones waar de fysieke schade het hardst en snelst optreedt</li>\n    <li><strong>Gebieden waar de infrastructuur niet meekan met schaalvergroting</strong>: polders met smalle ontsluiting, kleinschalige verkaveling, slechte bereikbaarheid voor zwaar materieel — kenmerkend voor délen van diverse veenweidegebieden, niet voor hele regio's</li>\n    <li><strong>Dunne veenpakketten met hydrologische functie</strong> — gebieden waar het veen als kurk op de fles functioneert. Verdwijning beïnvloedt regionale grondwaterstromen (bijv. Fries plateau)</li>\n  </ul>\n\n<p>Deze gebieden liggen niet als aaneengesloten blokken op de kaart. Vernatting valt als hagelslag: delen van percelen, niet hele bedrijven. En waar geen van deze kenmerken speelt, is een ander bedrijfsmodel ook niet nodig: op een polder met een kleidek op het veen, weinig kwel en geen Natura 2000 in de buurt kan een melkveehouder prima door met een aangepast bedrijf.<span class=\"fiche-wrap\"><button class=\"fiche-btn\" type=\"button\" aria-label=\"Toelichting tonen\">ⓘ</button><span class=\"fiche-popup\"><span class=\"fiche-label\">Tegenvoorbeeld</span><span class=\"fiche-source\">Zo'n polder ligt bijvoorbeeld in Friesland: kleidek op het veen, geen Natura 2000 in de buurt, nauwelijks kwel en beperkte bodemdaling. Doelsturing op stikstof en waterkwaliteit geldt er gewoon, maar een ander bedrijfsmodel is er niet nodig.</span><span class=\"fiche-note\">Het onderscheid doet werk: niet elk bedrijf op veen heeft een ander bedrijfsmodel nodig. Het gaat om de gebieden waar de reguliere weg doodloopt.</span></span></span></p>\n\n<p><strong>Het scherpst is het waar die vormen van druk samenkomen</strong>, want zij werken niet op dezelfde schaal. De grondwaterstand is per perceel te regelen: vernatten waar dat moet, en op het droge deel doorgaan met melkvee. Stikstof niet, want vee, voer en stal zijn niet per perceel te verlagen; dat raakt het bedrijf in één keer. Zulke verspreide vernatting is dus te dragen, zolang stikstof niet óók klemt. <strong>In en tegen Natura 2000 klemmen ze samen</strong>, en daar is stikstof het doorslaggevende dossier dat reguliere melkveehouderij onhoudbaar maakt. Hoeveel hectares per bedrijf het raakt is sterk plaatsgebonden en niet in algemene termen te kwantificeren.</p>\n","werkstand":{"nummer":"3","ronde":"2","stand":"**herzien**; 77% van de woorden van de auteurs. Eén open punt: het cijfer voor het inkomensgat (JUMP)"},"skelet":[{"nummer":"3","titel":"Waarom de ondernemer klem komt te zitten (A — De ondernemer klem)","bron":"a-klem","stand":"ronde 2 · af","deel":"Deel II — Wat er aan de hand is en wat er kan","kern":"De ondernemer op veen loopt vast op kosten en omzet: grond is duur, de kostprijs stijgt en de ruimte om te ondernemen krimpt. Dat is deels hoe het systeem uitpakt en deels het gevolg van eigen keuzes in schaal, financiering en tempo, want niet iedereen zit er even diep in. Dit hoofdstuk laat zien om welke bedrijven het gaat, waarom het zakelijk niet meer vol te houden is, waar de uitdaging het scherpst is, en wat een andere koers kost. Het is de uitwerking van de klem die hoofdstuk 1 aankondigt, dus de scope wordt hier niet opnieuw opgebouwd.","secties":[{"kop":"3.1 Om welke bedrijven het gaat","elementen":[{"t":"de meerderheid van de ondernemers in dit gebied loopt vast op kosten en omzet, en dat is deels systeem en deels eigen keuze","v":"tekst","h":"auteurs","n":"de openingsalinea, nu onder een kop; toetsregel 5a in één regel, de uitwerking staat in 3.2"},{"t":"de vorm van de populatie: een kleine groep grote bedrijven, een middengroep, een kleine niche","v":"beeld","h":"auteurs","n":""},{"t":"de middengroep krimpt hoe dan ook; de twee andere groepen hebben al een werkend bedrijfsmodel","v":"tekst","h":"auteurs","n":"— \"eruit vallen\" anders gezegd (Lian a-klem:2)"}]},{"kop":"3.2 Waarom het zakelijk niet meer vol te houden is","elementen":[{"t":"drie condities bepalen de richting van de melkveehouderij: de grondmarkt, het beleidskader, de ketenstructuur","v":"tabel","h":"auteurs","n":"— nu een kader met drie kolommen, wordt een tabel conform de vormronde van 19-8. **Let op:** de bewering dat een rem als de Oostenrijkse bergboerenregeling in Nederland \"nooit heeft bestaan\" is 19-8 onjuist bevonden en rechtgezet, met bronfiche"},{"t":"het systeem loopt ook intern vast: opvolging wordt onbetaalbaar en de grondmarkt raakt minder liquide. Plus: het gaspedaal werd de rem, één zin","v":"tekst","h":"auteurs + nieuw","n":"besluit 17-8"},{"t":"**en er zijn eigen keuzes gemaakt.** Schaal, financiering en het moment van investeren waren beslissingen van de ondernemer zelf, en niet iedereen zit even diep in de klem. Geen verwijt, maar de andere kant van ondernemerschap: daarom is er ook binnen de klem ruimte om te kiezen, en dat is hoofdstuk 13","v":"tekst","h":"nieuw","n":"Tim, 19-8"},{"t":"**de conclusie sluit de sectie, en de wetmatigheid hoort erbij:** het loopt vast op de drie condities én op zichzelf, en de uitweg die zich het eerst aandient is er geen. Minder koeien per hectare geeft minder melk per hectare terwijl grond, gebouwen en financiering hetzelfde blijven kosten — precies de kostenstructuur die de drie condities hebben opgebouwd. Geen aanname maar een rekensom, en de reden dat dit document over geld gaat","v":"tekst","h":"verhuisd + nieuw","n":"uit hoofdstuk 2 (Tim, 19-8: dit hoort als laatste conclusie in 3.2 en niet in een eigen sectie, want het is de uitkomst van de drie condities)"}]},{"kop":"3.3 Waar de uitdaging het scherpst is","elementen":[{"t":"de kenmerken waaraan je het gebied herkent","v":"lijst","h":"auteurs","n":"— **hier staan de vormen van fysieke druk, volledig** (Tim, 19-8). **De lijst begint met de vier uit 1.3, in dezelfde woorden en dezelfde orde** (serieuze bodemdaling · hoge broeikasgasemissies · ligging in of tegen Natura 2000 · toenemende verzilting), en daarna komen de kenmerken die 1.3 niet noemt: gebieden die structureel te nat worden, stedelijke randen, polders waar de infrastructuur niet meekan, en dunne veenpakketten met een hydrologische functie. Zo staan de twee lijsten in dezelfde lijn en spreken zij elkaar niet tegen (Tim, 19-8)"},{"t":"tegenvoorbeeld: waar het níet over gaat","v":"fiche","h":"auteurs","n":"— nu een accentkader"},{"t":"**de conclusie van de sectie, en zij staat vooraan: het scherpst is het waar meerdere vormen van druk samenkomen.** Omdat zij niet op dezelfde schaal werken: de grondwaterstand is per perceel hanteerbaar, stikstof raakt het hele bedrijf. Vernatting die als hagelslag valt is te dragen zolang stikstof niet óók klemt, en in en tegen Natura 2000 klemmen ze samen","v":"tekst","h":"auteurs","n":"— zonder de coördinatie-conclusie, want dat is oplossing en hoort in hoofdstuk 11 (Lian a-klem:11). **Niet \"per opgave\"** (Tim, 19-8): de zeven opgaven worden pas in hoofdstuk 4 geïntroduceerd, dus dat woord wijst hier naar iets wat de lezer nog niet kent"}]}],"noot":"Wat hier uit het hoofdstuk verdwijnt, en waarheen: de scope-opbouw (200.000 hectare, \"dit gaat niet over het hele gebied\", de schattingsdiscussie over de 20 tot 30 procent) staat in 1.3 en wordt hier alleen aangehaald · het driesporenkader \"de scope van spoor 3 is te smal\" gaat naar bijlage 16 · de vraag \"wanneer kom je in aanmerking voor de veenweideboerencategorie\" vervalt, want dat begrip wordt pas in hoofdstuk 9 gedefinieerd (Lian a-klem:9 wordt daar beantwoord) · de twee akte-vermeldingen vervallen, toetsregel 13."}],"deel":"Deel II — Wat er aan de hand is en wat er kan"},{"id":"b-opgaves","letter":"4","titel":"Wat Nederland van dit gebied vraagt","intro":"Nederland stelt doelen; om die te halen komen maatregelen. Wat de ondernemer op zijn land merkt is de maatregel. De vernatting die hoofdstuk 3 als kenmerk noemt dient het klimaat: een hogere grondwaterstand remt de veenoxidatie en dus de uitstoot uit de bodem. Een lagere veedichtheid dient de natuur: minder ammoniak op Natura 2000. Minder mest uitrijden dient de waterkwaliteit. Dezelfde hectare van twee kanten: voor de samenleving een doel, voor het bedrijf een ingreep in de bedrijfsvoering. En waar de vormen van druk uit 3.3 samenkomen, stapelen de maatregelen.","html":"\n<h2>4 — Wat Nederland van dit gebied vraagt</h2>\n\n<h3>4.1 Wat er moet, en waar het het zwaarst is</h3>\n\n<p>Nederland stelt doelen; om die te halen komen maatregelen. Wat de ondernemer op zijn land merkt is de maatregel. De vernatting die hoofdstuk 3 als kenmerk noemt dient het klimaat: een hogere grondwaterstand remt de veenoxidatie en dus de uitstoot uit de bodem. Een lagere veedichtheid dient de natuur: minder ammoniak op Natura 2000. Minder mest uitrijden dient de waterkwaliteit. Dezelfde hectare van twee kanten: voor de samenleving een doel, voor het bedrijf een ingreep in de bedrijfsvoering. En waar de vormen van druk uit 3.3 samenkomen, stapelen de maatregelen.</p>\n\n<p>Nederland vraagt zeven dingen van dit veenweidegebied: klimaat, water, natuur, voedselzekerheid, cultuur en landschap, grondstoffen en kringloop, en wonen. Bij de eerste drie valt de opgave in twee dimensies uiteen — het klimaat vraagt iets van de bodem en iets van het bedrijf, water gaat over kwaliteit en over kwantiteit, natuur over beschermde gebieden en over de basiskwaliteit van het boerenland — en zo zijn het er tien. Alle zeven zijn reëel en legitiem, en een nationale hiërarchie is er niet: één maatregel kan de ene opgave dienen en de andere schaden, dus optellen gaat niet.</p>\n\n<p>Van die tien is een deel hard. Om de druk op natuur, klimaat en water te verminderen heeft Nederland drie dimensies in normen vastgelegd en handhaaft het die. De ondernemer krijgt daarvan geen verlichting: hij krijgt de eisen.</p>\n\n<div style=\"overflow-x:auto\">\n  <table class=\"layer-table\">\n    <thead>\n      <tr>\n        <th style=\"width:22%\">Opgave</th>\n        <th style=\"width:41%\">Wat Nederland vraagt</th>\n        <th style=\"width:37%\">Waar de vraag het zwaarst is</th>\n      </tr>\n    </thead>\n    <tbody>\n      <tr>\n        <td><strong>Klimaat &amp; bodemdaling</strong></td>\n        <td>Veenoxidatie remmen, de broeikasgasemissies uit de bodem verlagen, bodemdaling tegengaan</td>\n        <td>In veengebieden zonder kleidek. Een kleidek remt de oxidatie, waardoor bodemdaling en emissies er beduidend lager zijn</td>\n      </tr>\n      <tr>\n        <td><strong>Water — kwaliteit</strong></td>\n        <td>De nutriëntenbelasting omlaag, tot de doelen van de Kaderrichtlijn Water. Op veen gaat het om het oppervlaktewater; nitraat in het grondwater is een vraagstuk van de zandgronden</td>\n        <td>In zuivere veengebieden, en nog zwaarder waar die aan natuurgebieden grenzen: uitspoeling van nutriënten heeft daar direct effect op beschermde habitats</td>\n      </tr>\n      <tr>\n        <td><strong>Natuur — gebieden</strong></td>\n        <td>Natura 2000: de staat van de beschermde habitats, en de stikstofdepositie daarop</td>\n        <td>In gebieden met hoge stikstofdepositie, doorgaans nabij intensieve emissiebronnen</td>\n      </tr>\n    </tbody>\n  </table>\n</div>\n\n<p>Dit zijn eisen zonder prijs. Ze moeten gehaald worden, het bedrijf verdient er niets aan, en het maakt er kosten voor.</p>\n\n<h3>4.2 Welk dossier nu het hardst duwt</h3>\n\n<p>Van deze drie bepaalt er één op dit moment de aandacht: de stikstofdepositie op Natura 2000. Daar staan nu het geld en de aandacht, en het is ook het dossier dat hoofdstuk 3 doorslaggevend noemt voor een bedrijf, omdat vee, voer en stal zich niet per perceel laten aanpassen zoals de grondwaterstand dat wel doet. In deze reeks is stikstof daarom geen achtste opgave maar de scherpe kant van de natuuropgave. Een lagere veedichtheid verlaagt de ammoniakuitstoot structureel, en dat is een gevolg van die stap zelf en niet een aparte maatregel die er bovenop komt.</p>\n\n<p><strong>Klimaat en bodemdaling duwt op dit moment minder hard, en niet omdat de opgave kleiner werd.</strong> Het doel staat: de veenweiden moeten in 2030 een megaton CO₂-equivalent minder uitstoten. Maar de Klimaat- en Energienota 2025 rekent voor dat het sectordoel voor landgebruik ook met aanvullend beleid buiten bereik blijft, en zolang dat gat groeit valt er geen vergunning stil.</p>\n\n<p><strong>Wat eraan komt is de waterkwaliteit, en die heeft een datum.</strong> De laatste planperiode van de Kaderrichtlijn Water eindigt in 2027, en verlenging is daarna niet meer mogelijk. In 2025 voldeed geen van de 745 Nederlandse oppervlaktewateren aan alle eisen.<span class=\"fiche-wrap\"><button class=\"fiche-btn\" type=\"button\" aria-label=\"Bron tonen\">ⓘ</button><span class=\"fiche-popup\"><span class=\"fiche-label\">Bron</span><span class=\"fiche-source\">Kaderrichtlijn Water, stand 2025-2026. De derde en laatste planperiode eindigt in december 2027; na die datum is verlenging van de termijn niet meer mogelijk. Nederland haalt ongeveer 80 procent van de afzonderlijke doelen en zal niet op 100 procent uitkomen; in 2025 voldeed geen van de 745 oppervlaktewaterlichamen aan álle eisen. Nutriënten uit de landbouw en chemische stoffen zijn de twee resterende hoofdoorzaken. De Europese Commissie is een inbreukprocedure tegen Nederland begonnen over de vergunningverlening voor het onttrekken van en lozen op water. Het achtste Actieprogramma Nitraatrichtlijn geldt vanaf 2026; Rijk en sector zoeken daarin gebieds- en bedrijfsspecifiek maatwerk in plaats van generieke aanscherping.</span><span class=\"fiche-note\">Bronnen: Ministerie van Infrastructuur en Waterstaat via Binnenlands Bestuur en NOS Nieuwsuur; Klimaat- en Energienota 2025 voor het landgebruiksdoel.</span></span></span></p>\n\n<p>Wat een dossier hard laat duwen is dus niet de omvang van de opgave, maar of er een juridisch slot op zit. Stikstof had er een, water krijgt er een, klimaat heeft er geen. Alle drie blijven even reëel; wat wisselt is welke op een gegeven moment de aandacht en het geld krijgt. Een bedrijf dat alleen op het dossier van vandaag is ingericht, staat bij de volgende ronde opnieuw voor de vraag.</p>\n\n<h3>4.3 Wat er ook gevraagd wordt, zonder dat het moet</h3>\n\n<p>Dat het beleid zijn geld en aandacht zet op wat nu het hardst nodig is, is logisch; met een tekort aan allebei kan het niet anders. Maar wat daarmee even blijft liggen, verdwijnt niet. De waterkwaliteit laat zien hoe snel iets van deze lijst naar de vorige verhuist.</p>\n\n<p>De andere zeven dimensies worden even goed gevraagd. Alleen staat er vooralsnog geen norm en geen handhaving achter. Bij het bedrijf en het klimaat is dat het scherpst te zien: voor methaan is er een sectordoel en geen norm per bedrijf. Wat de stal wél hard bindt is de ammoniakuitstoot, en die hoort bij de natuuropgave hierboven.</p>\n\n<div style=\"overflow-x:auto\">\n  <table class=\"layer-table\">\n    <thead>\n      <tr>\n        <th style=\"width:22%\">Opgave</th>\n        <th style=\"width:41%\">Wat Nederland vraagt</th>\n        <th style=\"width:37%\">Waar de vraag het zwaarst is</th>\n      </tr>\n    </thead>\n    <tbody>\n      <tr>\n        <td><strong>Klimaat — bedrijf</strong></td>\n        <td>De uitstoot van methaan en koolstof uit vee, stal en machines verlagen</td>\n        <td>Overal vergelijkbaar: de maatregelen en de druk zijn in elk veenweidegebied gelijk</td>\n      </tr>\n      <tr>\n        <td><strong>Water — kwantiteit</strong></td>\n        <td>Waterberging, piekopvang van regenwater, droogtebestrijding, en de zoetwaterbeschikbaarheid zelf: bij vernatting stijgt de eigen watervraag van dit gebied, en daarmee wordt op termijn bepalend hoeveel zoet water er is (hoofdstuk 5)</td>\n        <td>Vernatting is in alle veenweidegebieden de richting. Extra acuut in natuurgebieden met wegzijging en in landbouwgebieden met beperkte aanvoer vanuit rivieren</td>\n      </tr>\n      <tr>\n        <td><strong>Natuur — basiskwaliteit</strong></td>\n        <td>Slootkanten, weidevogels, beschermde soorten, biodiversiteit in het boerenland</td>\n        <td>Relevant in alle veenweidegebieden; er zijn geen gebieden waar dit niet speelt</td>\n      </tr>\n      <tr>\n        <td><strong>Voedselzekerheid</strong></td>\n        <td>Directe voedselproductie, inputs voor voedselproductie elders in Nederland, minder importafhankelijkheid</td>\n        <td>Speelt in alle veenweidegebieden, in wisselende vormen</td>\n      </tr>\n      <tr>\n        <td><strong>Cultuur &amp; landschap</strong></td>\n        <td>Landschapsidentiteit, veenweide-erfgoed, beleving</td>\n        <td>Nabij steden, waar de vraag naar landschapsbeleving en recreatie het hoogst is</td>\n      </tr>\n      <tr>\n        <td><strong>Grondstoffen &amp; kringloop</strong></td>\n        <td>Hernieuwbare grondstoffen, minder import, gesloten kringlopen</td>\n        <td>Breed, maar de koppeling is het sterkst naast bedrijvigheid en akkerbouwbedrijven die organische stromen kunnen afnemen</td>\n      </tr>\n      <tr>\n        <td><strong>Wonen</strong></td>\n        <td>Woningbouw, recreatiewoningen, tiny houses, functiemenging, zorgfunctie</td>\n        <td>Langs stadsranden, waar de druk op de ruimte het hoogst is en extra diensten zoals zorgfuncties een plek zoeken</td>\n      </tr>\n    </tbody>\n  </table>\n</div>\n\n<p>Al deze opgaven landen op hetzelfde land, en in de bedrijfsvoering van hetzelfde bedrijf: het bedrijf dat in hoofdstuk 3 klem komt te zitten.</p>\n","werkstand":{"nummer":"4","ronde":"2","stand":"**herzien (20-8): drie secties, geordend naar dwang** — 4.1 wat er moet · 4.2 welk dossier nu het hardst duwt · 4.3 wat er ook gevraagd wordt zonder dat het moet. **Herzien 20-8.** De tien dimensies staan **drie hard en zeven zacht** (klimaat-bedrijf is 20-8 zacht geworden: geen norm per bedrijf voor methaan); de weidevogel is naar hoofdstuk 5 verhuisd. 820 woorden tegen 832; het budget van 650 haalt het niet omdat 316 woorden tabelcel van de auteurs zijn en die alleen verhuizen. Geen markering open"},"skelet":[{"nummer":"4","titel":"Wat Nederland van dit gebied vraagt (B — De opgaven)","bron":"b-opgaves","stand":"ronde 2 · in herziening","deel":"Deel II — Wat er aan de hand is en wat er kan","kern":"Nederland vraagt zeven dingen tegelijk van dit gebied, en niet alle zeven even hard. Dit hoofdstuk zet die vraag op tafel in de orde van dwang: wat er moet en gehandhaafd wordt, welk dossier vandaag het hardst duwt, en wat er óók gevraagd wordt zonder dat het moet. Wie die vraag kan leveren, komt daarna.","secties":[{"kop":"4.1 Wat er moet, en waar het het zwaarst is · **gehaald: 371 woorden** (was 538; drie harde dimensies, waarvan 115 woorden tabelcel van de auteurs)","elementen":[{"t":"**de openingsalinea legt de koppeling met het slot van 3.3 en zegt daarna wat er van die vraag hard is.** Eerst: wat voor het bedrijf een vorm van druk is, is voor Nederland een opgave — dezelfde vernatting die 3.3 als kenmerk noemt is hier de wateropgave, dezelfde snelle veenoxidatie de klimaatopgave, dezelfde ligging in of tegen Natura 2000 de natuuropgave. Eén lijst, van twee kanten bekeken, en waar 3.3 zegt dat het het scherpst is waar de druk samenkomt, ligt de vraag ook het dikst gestapeld. Daarna: **om de druk op natuur, klimaat en water te verminderen** legt Nederland een deel van die vraag vast in normen en handhaaft het — en de ondernemer krijgt daarvan geen verlichting, hij krijgt de eisen","v":"tekst","h":"auteurs + nieuw","n":"**De formulering \"om die druk te verminderen\" is van Tim (20-8) en moet zeggen wélke druk:** na 3.3 wijst \"die druk\" naar het bedrijf, en dan staat er dat het beleid de ondernemer komt helpen. Dat is niet zo, en een beleidslezer concludeert dan dat de klacht van de ondernemer nergens op rust. Hier valt het woord **opgave** voor het eerst, conform `terminologie.md`"},{"t":"de drie harde dimensies, met per stuk wat Nederland vraagt en waar die vraag het zwaarst is: klimaat en bodemdaling · waterkwaliteit · Natura 2000","v":"tabel","h":"auteurs","n":"drie van de tien rijen uit de bestaande tabel, cellen ongewijzigd. De drie correcties van 19-8 blijven staan: de KRW bij waterkwaliteit (toetsregel 24) en \"beschermde soorten\" bij de basiskwaliteit (Simon), die daarmee in 4.3 landt"},{"t":"**de sluitregel is het label, en zij is één zin:** dit zijn eisen zonder prijs — ze moeten gehaald worden en ze leveren het bedrijf niets op","v":"tekst","h":"nieuw","n":"Tim, 20-8. Zonder dit label is 4.3 een tweede lijst in plaats van de andere helft"}]},{"kop":"4.2 Welk dossier nu het hardst duwt · **gehaald: 397 woorden**, waarvan 121 fiche (was 250)","elementen":[{"t":"**nu duwt stikstof het hardst.** Geen achtste opgave maar de scherpe kant van de natuuropgave, en een lagere veedichtheid verlaagt de ammoniakuitstoot als gevolg van die stap zelf","v":"tekst","h":"auteurs","n":"§6, toetsregel 22. **Tweede koppeling met 3.3:** daar is stikstof het dossier dat het bedrijf in één keer raakt"},{"t":"**klimaat en bodemdaling duwt minder hard, en niet omdat de opgave kleiner werd.** Het doel staat — een megaton CO₂-eq minder in 2030 — maar de Klimaat- en Energienota 2025 rekent voor dat het sectordoel voor landgebruik ook met aanvullend beleid buiten bereik blijft, en zolang dat gat groeit valt er geen vergunning stil","v":"tekst","h":"nieuw","n":"Tim, 20-8, online nagetrokken"},{"t":"**wat eraan komt is de waterkwaliteit, en die heeft een datum.** De laatste planperiode van de Kaderrichtlijn Water eindigt in 2027 en verlenging is daarna niet mogelijk; in 2025 voldeed geen van de 745 oppervlaktewateren aan alle eisen","v":"tekst + fiche","h":"nieuw","n":"Tim, 20-8. De cijfers, de inbreukprocedure van de Commissie over de vergunningverlening en het achtste Actieprogramma Nitraatrichtlijn staan in de fiche, niet in de lopende tekst"},{"t":"**de conclusie is het mechanisme, en zij vervangt de oude brugzin:** wat een dossier hard laat duwen is niet de omvang van de opgave maar of er een juridisch slot op zit. Stikstof had er een, water krijgt er een, klimaat heeft er geen. Alle drie blijven even reëel; wat wisselt is welke de aandacht en het geld krijgt. Een bedrijf dat alleen op het dossier van vandaag is ingericht staat bij de volgende ronde opnieuw voor de vraag","v":"tekst","h":"nieuw","n":"Tim, 20-8"}]},{"kop":"4.3 Wat er ook gevraagd wordt, zonder dat het moet · **gehaald: 342 woorden** (nieuw; zeven rijen uit 4.1, de regel over methaan, en de brug van 20-8)","elementen":[{"t":"**de brug van 4.2 naar 4.3, en zij komt vóór de lijst** (Tim, 20-8): dat het beleid zijn geld en aandacht zet op wat nu het hardst nodig is is logisch, met een tekort aan allebei kan het niet anders — maar wat daarmee even blijft liggen verdwijnt niet, en de waterkwaliteit laat zien hoe snel iets van deze lijst naar de vorige verhuist","v":"tekst","h":"nieuw","n":"drie zinnen. **Wat er bewust níet staat: dat hier kansen liggen.** Tim stelde die derde stap voor en ik heb hem afgeraden; het antwoord \"en daar zit een afnemer bij\" is 5.3, en een kans zonder afnemer is een wens met een vrolijker woord. Zeg je het hier al, dan is 5.2 geen bocht meer maar een herhaling. Wat 4.3 wél mag zeggen gaat over tijd en niet over geld, en dat staat al aan het eind van 4.2"},{"t":"één aanloop: naast wat moet, vraagt Nederland meer van dit veenweidegebied — en daarvoor staat er **vooralsnog** geen norm en geen handhaving achter","v":"tekst","h":"nieuw","n":"twee zinnen. **Het woord vooralsnog is van Tim (20-8) en het is niet vrijblijvend:** 4.2 laat net zien dat een dossier hard wordt zodra er een slot op komt, en water is daarvan het voorbeeld met een datum. Zonder dat woord leest de lijst als blijvend zacht. *Let op: \"en geen geld\" stond hier eerst en is fout — voedselzekerheid staat in deze lijst en wordt wél betaald, via de melkprijs, precies zoals de betaalladder in 5.1 zegt*"},{"t":"de zeven zachte dimensies, uit dezelfde tabel: klimaat en het bedrijf · waterkwantiteit · de basiskwaliteit van het boerenland · voedselzekerheid · cultuur en landschap · grondstoffen en kringloop · wonen","v":"tabel","h":"auteurs","n":"uit 4.1, cellen ongewijzigd. **Koolstofvastlegging staat hier niet**, anders dan Tims lijst van 20-8 vraagt: Nederland eist lagere emissies en vraagt geen paludicultuur, dus vastlegging is een productroute en hoort in 5.3, waar zij al staat. Zo blijft de telling zeven opgaven en tien dimensies overeind"},{"t":"**de slotregel van het hoofdstuk, en zij is de brug naar hoofdstuk 5:** al deze opgaven landen op hetzelfde land en in de bedrijfsvoering van hetzelfde bedrijf, en dat is het bedrijf dat in hoofdstuk 3 klem komt te zitten","v":"tekst","h":"auteurs","n":"uit 4.2, ongewijzigd"}]}],"noot":"Hoofdstuk 4 is af op **1.070 woorden tegen 832 in de bestuursversie**, en 949 als je de fiche niet meerekent — die staat in de lezer als open te klikken kader en niet in de leesregel. Het budget van 650 is dus ruim gemist, en dat heeft drie oorzaken die alle drie de moeite waren. **Eén: de tabelrijen verhuizen, zij krimpen niet** — de tien rijen zijn 316 woorden van de auteurs en de splitsing over 4.1 en 4.3 scheelt daarin niets. **Twee: twee feitcorrecties van 20-8** (opgave versus maatregel, en klimaat-bedrijf dat geen harde eis blijkt) kostten woorden omdat de keten uitgeschreven moest worden. **Drie: 4.2 is op Tims verzoek bewust rijker gemaakt**, van één dossier naar een tijdlijn van drie plus het mechanisme dat ze ordent. Dat is 250 woorden erbij en het is het waard: het verklaart waarom een bedrijf meer dan één prestatie moet kunnen dragen, en dat is precies wat hoofdstuk 5 nodig heeft.* Het budget van 650 is niet gehaald, en de oorzaak is de moeite om te onthouden: **de tabelrijen verhuizen, zij krimpen niet.** De tien rijen zijn 316 woorden van de auteurs, en de splitsing over 4.1 en 4.3 scheelt daarin niets; ik had gerekend alsof zij dat wel zou doen. Van de 371 woorden in 4.1 zijn er 115 tabelcel, van de 293 in 4.3 zijn er 241 tabelcel. **Het proza is wél gedaald**, van 481 naar 464 woorden, terwijl er een sectiekop, een label, een brug en een aanloop bij kwamen, de weidevogel-alinea van 90 woorden eruit ging en de feitcorrectie van 20-8 de hele keten doel-maatregel-druk moest uitschrijven. Die alinea is 20-8 op Tims aanwijzing nog een keer strak gezet: van 155 naar 92 woorden, met de drie ketens als parallelle drieslag en zonder de negatie van mijn eigen fout. Verder snijden kan alleen door de tabelcellen van de auteurs te herschrijven, en dat is geen redactiekwestie. **Het woordtotaal van 20-8 is daarmee vervallen.** De belofte was 2.210 voor hoofdstuk 4 en 5 samen tegen 2.857; realistisch wordt het ongeveer 2.510 aan leesregel, dus ruim 340 korter in plaats van 640. De 554 woorden uit hoofdstuk 5 blijven wel staan: dat is proza dat het hoofdstuk verlaat en geen tabel die verschuift."}],"deel":"Deel II — Wat er aan de hand is en wat er kan"},{"id":"c-omslag","letter":"5","titel":"Wat dit gebied kan dragen","intro":"Dat is veel om op één bedrijf te laten landen, en er gebeurt op dat veen dan ook al veel. Aan de drie eisen uit 4.1 wordt het hardst gewerkt: de emissies uit de bodem omlaag, de waterkwaliteit op orde, de depositie op Natura 2000 omlaag. Dat werk levert het bedrijf niets op — het kost het geld.","html":"\n<h2>5 — Wat dit gebied kan dragen</h2>\n\n<h3>5.1 Wat hier al gebeurt, en wie het betaalt</h3>\n\n<p>Dat is veel om op één bedrijf te laten landen, en er gebeurt op dat veen dan ook al veel. Aan de drie eisen uit 4.1 wordt het hardst gewerkt: de emissies uit de bodem omlaag, de waterkwaliteit op orde, de depositie op Natura 2000 omlaag. Dat werk levert het bedrijf niets op — het kost het geld.</p>\n\n<p>Daarnaast gebeurt er op dat land al meer dan melk produceren. Het landschap wordt onderhouden, de slootkant en de oever bijgehouden. Er is zorg voor elkaar, en in een gebied waar de bedrijven ver uit elkaar liggen houden dezelfde mensen de sociale samenhang overeind. Dat alles bij elkaar is rentmeesterschap: zorg voor iets wat je hebt overgenomen en weer doorgeeft.</p>\n\n<p>Van dit alles wordt één ding afgerekend, en dat is de melk. Voor weidevogel- en landschapsbeheer bestaat een vergoeding, en die dekt de kosten en de gederfde inkomsten — een vergoeding dus, en geen verdienste. Dat is wel de enige prestatie waarvoor het apparaat om te leveren al staat: de pakketten liggen er en de collectieven voeren ze uit. Al het andere staat in geen enkel contract, en gratis is het niet — het komt uit de marge van een melkveebedrijf, en de samenleving heeft het decennialang op die manier meegekregen.</p>\n\n<h3>5.2 De kans zit waar de klem het strakst is</h3>\n\n<p>Zet de klem uit hoofdstuk 3 naast de vraag uit hoofdstuk 4, en er verschijnt iets anders dan een probleem. Juist waar de maatregelen het dikst stapelen moet de veedichtheid omlaag, en dan daalt de opbrengst uit melk terwijl grond, gebouwen en financiering hetzelfde blijven kosten (3.2). Op diezelfde hectare komt ruimte vrij voor precies de prestaties die hoofdstuk 4 vraagt. De kans ligt dus niet naast de klem: hij ligt op dezelfde plek, en hij is het grootst waar de klem het strakst zit.</p>\n\n<p>Daarmee staat er één vraag open, en het is de goede: betaalt iemand daarvoor?</p>\n\n<h3>5.3 Waar deze opgaven een product kunnen worden</h3>\n\n<p>Drie prestaties kunnen wél een product worden: koolstof, biodiversiteit en water. Wat ze onderscheidt is de afnemer — een partij buiten het gebied met een eigen belang en een eigen begroting. Alle drie zijn richtingen die in JUMP verkend worden en die nog niet zijn uitgekristalliseerd.</p>\n\n<p><strong>CO₂-compensatie voor de akkerbouw.</strong> Akkerbouwgebieden produceren voedsel met aanzienlijke CO₂-uitstoot en zoeken compensatieroutes om aan klimaatdoelen te voldoen. In plaats van het planten van bos op een polder of het inrichten van compensatieprojecten elders, kan een aanzienlijk deel van die compensatie in het veenweidegebied plaatsvinden. De CO₂-voorraad in het veen is enorm. Twee dingen moeten daarbij uit elkaar blijven, want voor wie ervoor betaalt zijn het twee producten: het remmen van veenoxidatie is <em>vermeden uitstoot</em>, en <em>vastlegging</em> komt van paludicultuur en actieve veenaanmaak.</p>\n\n<p><strong>Biodiversiteit verbouwen.</strong> Nederland heeft een natuuropgave die grotendeels buiten dit gebied wordt vastgesteld, en die groeit: de Europese natuurherstelverordening vraagt herstelmaatregelen op een oplopend deel van het agrarische veenareaal. Uitgevoerd moet zij worden op de grond, en die grond is hier in beheer bij iemand die er woont. Het gaat om verbouwen en niet om ontzien: biodiversiteit is dan het doel en niet het gevolg, gestuurd met agrarische middelen, met begrazing en maaien als instrument en het vee als middel in plaats van als product. Wat er te leveren valt, komt in drie soorten met drie verschillende afnemers. Losse functionele bouwstenen voor wie elders een tekort heeft, in bestuiving, waterkwaliteit, bodemleven of groen in de stad. Natuurtypen en doelsoorten die de overheid moet halen, van nat schraalland en trilveen tot grutto en tureluur. En landschap dat een private partij uit eigen overweging wil betalen. Eén voorwaarde is daarbij hard: de grond houdt de status landbouw. Krijgt zij de status natuur, dan lopen de omliggende bedrijven vast in dezelfde regelgeving, en werkt het concept zijn eigen omgeving tegen.<span class=\"fiche-wrap\"><button class=\"fiche-btn\" type=\"button\" aria-label=\"Bron tonen\">ⓘ</button><span class=\"fiche-popup\"><span class=\"fiche-label\">Bron</span><span class=\"fiche-source\">VIC-conceptdossier 4a, Biodivers Veen (VIA, versie 12 juli 2026). Doorgerekend op 70 tot 80 hectare nat veen, met monitoring in lucht, water en bodem en corridors naar omliggende natte percelen: wat voor de buurman een te natte reststrook is, is hier de kern van het systeem. De Europese natuurherstelverordening, van kracht sinds augustus 2024, vraagt herstelmaatregelen op 30 procent van het agrarische veenareaal in 2030, 40 procent in 2040 en 50 procent in 2050.</span><span class=\"fiche-note\">Het concept staat nog vroeg in zijn ontwikkeling. Drie dingen zijn open: een betrouwbare meting van biodiversiteit, de juridische erkenning van biodiversiteitscredits, en de betalingsbereidheid van de drie afnemers.</span></span></span></p>\n\n<p><strong>Water: piekberging nu, opslag in verkenning.</strong> Twee dingen worden hier vaak door elkaar gehaald, en ze vragen een andere inrichting van het land. <em>Piekberging</em> houdt bij een hoosbui water vast op eigen land, zodat het niet elders schade doet, op akkerland of aan infrastructuur. Dat is met sloten, greppels en peilbeheer te doen, en het kan vandaag. <em>Waterbuffering</em> is het andere: water bewaren voor een droge periode, in de meest vergaande vorm in de zandlagen onder het veen. Wat daar kan is nog niet bekend.</p>\n\n<p>Het mechanisme is daarbij niet levering maar het opheffen van een claim.<span class=\"fiche-wrap\"><button class=\"fiche-btn\" type=\"button\" aria-label=\"Bron tonen\">ⓘ</button><span class=\"fiche-popup\"><span class=\"fiche-label\">Bron</span><span class=\"fiche-source\">Niel de Jong, Unie van Waterschappen, commentaar op deze visie, 18 juni 2026. Om water van betekenis te kunnen leveren zou een groot deel van het gebied onder water moeten staan. Bij -40 cm neemt de eigen watervraag van het gebied in een droge zomer toe met een factor anderhalf tot drie; om water van betekenis te kunnen leveren zou al snel een derde van het gebied ongeveer een meter onder water moeten staan. De bron specificeert bij die -40 cm niet of het om het slootwaterpeil of de grondwaterstand gaat.</span></span></span> In een droge zomer wordt er nú water náár dit gebied aangevoerd om de veenbodem te sparen; een gebied dat zichzelf voorziet heeft die aanvoer niet nodig, en dat water komt vrij voor gebruik elders. Waarom die claim zwaar weegt staat in de verdringingsreeks in bijlage 16: bij watertekort gaat klink en zetting in veen vóór op drinkwater, terwijl water voor het gras onderaan staat. Die hoge prioriteit geldt dus de bodem en niet het bedrijf, en daarmee is dit geen boerenbelang in een ander jasje. En er is een partij met een doel: I&amp;W stuurt sinds 2026 op waterzelfvoorzienendheid van veenweidegebieden. Hoeveel water dat vrijmaakt is niet bekend.</p>\n\n<p><strong>En één prestatie zit er tussenin.</strong> Weidevogelbeheer heeft een harde vraag uit Europa en een uitvoering die al staat. Wat ontbreekt is een afnemer die inkoopt: de vergoeding dekt kosten en gederfde inkomsten. Dat is nog geen product. Het is wel de prestatie die als eerste als opdracht verleend zou kunnen worden.</p>\n\n<p>Dat dit alles kán, betekent niet dat het er is. Of het werkt is een vraag aan de praktijk, en dat is wat in JUMP wordt onderzocht. Of het mag is een vraag aan het recht, want een overheid die een dienst inkoopt bij een ondernemer loopt aan tegen aanbesteding en staatssteun (hoofdstuk 11). En of het gewild wordt is de grootste van de drie: het lastigst te beprijzen is wat altijd gratis kwam (hoofdstuk 14).</p>\n\n<h3>5.4 En daarom een ondernemende boer</h3>\n\n<p><strong>Maar koolstof vasthouden en water bergen kunnen niet uit de marge van het bedrijf komen.</strong> Een oever die netjes blijft en een slootkant die gespaard wordt, liepen tot nu toe mee met het werk dat er toch al was. Water werkelijk vasthouden vraagt een andere inrichting van het land, en de koolstof in de bodem houden vraagt een hogere grondwaterstand, op de zwaarste plekken met minder koeien per hectare. Dat gebeurt niet naast het bedrijf: het grijpt in de bedrijfsvoering in en het kost productie. Zulk werk verkleint precies de marge waaruit het kleine beheer tot nu toe betaald werd.</p>\n\n<p>Dit is dus geen liefhebberij erbij. Het zijn activiteiten die investeringen, grond en jaren vragen, en daar hoort een prijs tegenover te staan. Niet omdat deze boeren het moeilijk hebben, maar omdat zij een publieke dienst leveren: schoon water, vastgehouden koolstof, weidevogels en landschapskwaliteit zijn diensten waar de samenleving dagelijks gebruik van maakt. Dat is geen steun. Het is een zakelijke transactie. En het is ook geen koerswijziging, want landbouw is beleidsmatig altijd al deels nutsfunctie geweest: de samenleving voorzien van betaalbaar, gezond en veilig voedsel. Nieuw is alleen dat die nutsfunctie breder wordt.</p>\n\n<p><strong>En daarvoor is een ondernemende boer nodig.</strong> Dit werk valt samen met werk dat toch al gebeurt: de uren, de machines en de kennis van elk perceel zitten al in een lopend bedrijf, en wie 's ochtends langs de sloot rijdt ziet dat de oever inzakt. Wie hetzelfde werk als losse opdracht uitvoert, begroot elk uur apart en moet elk jaar opnieuw uitleggen waarom het nodig is. Een vrijwilliger of een beheerder op afstand kan het landschap onderhouden, maar niet zo fijnmazig en niet zo goedkoop, en zonder het vakmanschap en de gehechtheid van iemand die er woont en er het brood verdient. Daar komt bij dat een investering die zich over jaren terugverdient een ondernemer vraagt en geen uitvoerder.</p>\n\n<p>Waarom déze boeren en niet andere in Nederland: het verschil zit niet in exclusiviteit, want water bergen kan op klei ook en koolstof vastleggen in bos op zand ook. Het zit in het alternatief. Op het grootste deel van de Nederlandse landbouwgrond is het alternatief voor het huidige bedrijf: anders boeren. Op de plekken waar de vormen van fysieke druk zich stapelen, is het alternatief geen boeren. De reële opties zijn daar natuur, uitkoop, of beheer op afstand door een partij die doet wat er in het contract staat. Dat zijn verdedigbare routes en ze worden ook gelopen. Onze analyse is dat er in datzelfde gebied een route bij komt, waarin het beheer een verdienmodel houdt en de ondernemer blijft.</p>\n\n<p>Waterkwaliteit, biodiversiteit en broeikasgasreductie worden dus pas bereikbaar als de ondernemende boer er een verdienmodel in ziet, en dat betekent hier méér dan geld: werken aan de opgaven moet de overlevingskans van het bedrijf vergroten in plaats van bedreigen. Dat veel jonge boeren het vandaag als bedreiging ervaren, is precies de omkering die deze visie wil maken. Niet ondanks ondernemerschap, maar dankzij. Ondernemende boeren zijn de motor van deze visie, mits de overheid de juiste condities schept.</p>\n","werkstand":{"nummer":"5","ronde":"1","stand":"**herzien (20-8): vier secties** — 5.1 wat hier al gebeurt en wie het betaalt · **5.2 de kans zit waar de klem het strakst is** (nieuw scharnier) · 5.3 waar deze opgaven een product kunnen worden, met het weidevogelbeheer als grensgeval en de drie horden ingekort · **5.4 en daarom een ondernemende boer**, met de marge-omkering vooraan. 1.695 woorden totaal en 1.504 leesregel tegen 2.025; nul tabellen, de tabel in 5.1 is 20-8 vervallen. Nog toe te voegen: twee bronnen en één getal, de lijst staat in `correctielijst.md`"},"skelet":[{"nummer":"5","titel":"Wat dit gebied kan dragen","bron":"c-omslag","stand":"ronde 1 · in herziening","deel":"Deel II — Wat er aan de hand is en wat er kan","kern":"Op dezelfde hectare komt meer dan melk: landschap en weidevogels, koolstof in de bodem, vastgehouden water. Daarvan wordt er één afgerekend en de rest komt uit de marge van het bedrijf. Dit hoofdstuk zegt waar die klem omslaat in een kans — juist daar waar hij het strakst zit — welke prestaties een afnemer hebben, en waarom daar een ondernemende boer voor nodig is.","secties":[{"kop":"5.1 Wat hier al gebeurt, en wie het betaalt · **gehaald: 219 woorden** (was 133, en de tabel is eruit)","elementen":[{"t":"**wat moet staat vooraan, want daar wordt het hardst aan gewerkt:** de emissies uit de bodem omlaag, de waterkwaliteit op orde, de depositie op Natura 2000 omlaag — en dat werk levert het bedrijf niets op, het kost het geld","v":"tekst","h":"nieuw","n":"Tim, 20-8: \"nu lijkt het of die verplichte zaken er niet bij staan, maar die moeten natuurlijk als eerste.\" Zonder deze alinea leest 5.1 alsof die hectare alleen de vrijwillige dingen doet, en dat ziet een beleidslezer meteen"},{"t":"**wat er daarnaast al gebeurt, en het is meer dan ecosysteemdiensten:** het landschap onderhouden, de slootkant en de oever bijhouden, zorg voor elkaar, en de sociale samenhang in een gebied waar de bedrijven ver uit elkaar liggen. Eén woord vat het: rentmeesterschap, zorg voor iets wat je hebt overgenomen en weer doorgeeft","v":"tekst","h":"nieuw","n":"Tim, 20-8. **Let op de precisering die hij aanbracht:** dit is *zorg voor elkaar* en niet zorg als betaalde activiteit op het bedrijf. Dat laatste is een inkomstenstroom in hoofdstuk 9 en 10 en hoort hier niet; mijn eerste lezing was fout. Daarmee raakt dit ook niet aan het open definitiepunt over zorg en ecosysteemdiensten in `terminologie.md`"},{"t":"**de constatering: één ding wordt afgerekend, en dat is de melk.** Voor weidevogel- en landschapsbeheer bestaat een vergoeding die kosten en gederfde inkomsten dekt — een vergoeding dus, en geen verdienste (Tims formulering, en helderder dan \"dat is geen prijs\"). Dat is wel de enige prestatie waarvoor het apparaat om te leveren al staat: de pakketten liggen er en de collectieven voeren ze uit. Al het andere staat in geen contract en komt uit de marge","v":"tekst","h":"verhuisd + nieuw","n":"uit de oude 5.5 en uit 4.2"}]},{"kop":"5.2 De kans zit waar de klem het strakst is · **gehaald: 110 woorden** (nieuw, budget 150)","elementen":[{"t":"**de omslag, en het is een rekensom en geen hoop:** juist waar minder koeien per hectare nodig zijn, daalt het inkomen uit melk terwijl grond, gebouwen en financiering hetzelfde blijven kosten (3.2) — en juist daar komt op dezelfde hectare ruimte vrij voor de prestaties die hoofdstuk 4 vraagt","v":"tekst","h":"nieuw","n":"Tim, 20-8"},{"t":"**daarmee kantelt de reeks van hoofdstuk 3:** dezelfde stapeling die het bedrijf klem zet, maakt de meeste ruimte voor iets anders","v":"tekst","h":"nieuw","n":"één zin"},{"t":"**en de vraag die de lezer dan stelt, staat hier expliciet open:** betaalt iemand daarvoor? Het antwoord is niet \"ja\" maar \"voor drie ervan is er een afnemer\", en dat is 5.3","v":"tekst","h":"nieuw","n":"één zin, en zij is er om te voorkomen dat de kans op behoefte alleen rust"}]},{"kop":"5.3 Waar deze opgaven een product kunnen worden · **gehaald: 838 woorden, 647 leesregel** (was 789, budget 700)","elementen":[{"t":"**de opening zegt wat een opgave tot product maakt, in twee zinnen:** van wat hoofdstuk 4 vraagt hebben drie een afnemer buiten het gebied, met een eigen belang en een eigen begroting","v":"tekst","h":"auteurs","n":"ingekort, want 4.3 heeft de lijst net genoemd en de huidige opening doet haar over"},{"t":"één keer vooraf: dit zijn richtingen die in JUMP verkend worden en die nog niet zijn uitgekristalliseerd","v":"tekst","h":"auteurs","n":""},{"t":"de drie routes, elk even lang: CO₂-compensatie voor de akkerbouw, met vermeden uitstoot en vastlegging apart · biodiversiteit **verbouwen**, met drie soorten afnemers en de landbouwstatus als harde voorwaarde · water, met piekberging vandaag en buffering in verkenning, en het opheffen van een claim als mechanisme","v":"tekst + fiche","h":"auteurs","n":"**Twee dingen eruit:** de vergelijking met bosaanplant op zandgrond, die 19-8 al als geschrapt is afgevinkt maar er nog staat (geen bron, toetsregel 8 en 11a), en het stippenblokje bij piekberging, dat zegt wat de twee alinea's eronder ook al zeggen"},{"t":"**het grensgeval, en het is er één:** weidevogelbeheer heeft een harde vraag (de Europese natuurherstelverordening), een bestaande uitvoering, en geen afnemer die inkoopt, want de betaling vergoedt kosten. Dat is geen product maar de eerste prestatie die als **opdracht** verleend zou kunnen worden","v":"tekst","h":"nieuw","n":"Tim, 20-8: \"we moeten opletten dat we hem niet te snel als product plaatsen, want dat is het nog niet\""},{"t":"**de drie horden, in drie zinnen met hun adres:** of het kan (JUMP), of het mag (hoofdstuk 11), en of het gewild wordt (hoofdstuk 14) — en die laatste is de grootste, want het lastigst te beprijzen is wat altijd gratis kwam","v":"tekst","h":"ingekort","n":"uit de oude 5.4, van 185 naar ongeveer 60 woorden"}]},{"kop":"5.4 En daarom een ondernemende boer · **gehaald: 521 woorden** (was 373 plus ±150 verhuisd, budget 450)","elementen":[{"t":"**dit kan niet uit de marge komen, en dat staat vooraan:** water vasthouden en de koolstof in de bodem houden grijpen in de bedrijfsvoering in en kosten productie, en zij verkleinen precies de marge waaruit het kleine beheer tot nu toe betaald werd","v":"tekst","h":"verhuisd","n":"uit de oude 5.5. **De omzetting is het besluit van 20-8:** in de oude orde kwam deze \"maar\" ná de conclusie, en dat kon zolang alle drie de alinea's in één sectie stonden. Nu de marge-observatie in 5.1 staat, arriveert de ondernemende boer zonder deze zin vóór de reden dat hij betaald moet worden — en dan is het weer een pleidooi voor gratis werk"},{"t":"**dus geen liefhebberij erbij, en dus een prijs:** dit zijn activiteiten die investeringen, grond en jaren vragen. Betalen niet omdat zij het moeilijk hebben maar omdat zij een publieke dienst leveren, en dat is geen koerswijziging want de nutsfunctie van de landbouw wordt alleen breder","v":"tekst","h":"verhuisd","n":"uit het slot van de oude 5.5 en uit de oude 5.3"},{"t":"**en daarom een ondernemende boer, en juist déze:** het werk zit al in een lopend bedrijf, dus fijnmaziger en goedkoper dan een vrijwilliger of een beheerder op afstand — en het verschil met andere boeren zit niet in exclusiviteit maar in het alternatief, dat hier geen landbouw is","v":"tekst","h":"verhuisd","n":"uit de oude 5.5 en de oude 5.3. **De combinatie doet hier het werk** (Tim, 20-8): \"boer\" levert de aanwezigheid en de fijnmazigheid, \"ondernemend\" de bereidheid om een investering te dragen tegen een opbrengst. Kaal \"een ondernemer\" laat de uitweg open dat een beheerorganisatie ook een ondernemer is, en dat is precies de route die dit argument wil uitsluiten"},{"t":"**de slotzin van de analyse:** werken aan de opgaven moet de overlevingskans van het bedrijf vergroten in plaats van bedreigen — niet ondanks ondernemerschap maar dankzij, mits de overheid de condities schept. **Ondernemende boeren zijn de motor van deze visie**","v":"tekst","h":"auteurs + nieuw","n":"Tims zin, 20-8. Dit is de laatste zin van de analyse en de opstap naar de aktes, die precies dit testen"}]}],"noot":"Hoofdstuk 5 is af op **1.695 woorden totaal en 1.504 aan leesregel**, tegen 2.025 in de bestuursversie. Het budget van 1.560 is dus gehaald op de leesregel. Waar de winst zit: de tegenwerping \"maak er dan helemaal natuur van\" en de ruimtedruk uit de Ontwerp-Nota Ruimte zijn het hoofdstuk uit (samen ±280 woorden, geparkeerd in `correctielijst.md` onder `h-risicos` en `scope`), de drie horden zijn van 185 naar 70 woorden gegaan, en de opening van 5.3 en het stippenblokje bij piekberging zijn eruit. **5.4 staat 70 woorden over zijn budget** en dat laat ik zo: de sectie draagt vier bewegingen en de laatste zin van de hele analyse. **Hoofdstuk 4 en 5 samen: 2.814 woorden totaal tegen 2.857, en 2.502 aan leesregel** — dus ruim 300 korter op de regel die de lezer volgt, en gelijk als je de fiches meetelt."}],"deel":"Deel II — Wat er aan de hand is en wat er kan"},{"id":"e-aktes","letter":"E","titel":"Het verhaal: drie aktes","intro":"Drie aktes voor het veenweidegebied. Niet drie gelijkwaardige scenario's, maar drie keuzes die elkaar opvolgen in het beleidsdebat. Akte I: status quo. Akte II: hard ingrijpen zonder pijlers. Akte III: systeemcondities aanpassen.","html":"\n<h2>E — Het verhaal: drie aktes</h2>\n\n<p>Drie aktes voor het veenweidegebied. Niet drie gelijkwaardige scenario's, maar drie keuzes die elkaar opvolgen in het beleidsdebat. Akte I: status quo. Akte II: hard ingrijpen zonder pijlers. Akte III: systeemcondities aanpassen.</p>\n\n<div class=\"akte akte-1\" id=\"akte1\">\n    <div class=\"akte-number\">Akte I</div>\n    <h3>Over vijf jaar: doorgeïntensiveerd</h3>\n    <p style=\"font-size:14px;font-weight:500;color:var(--red);line-height:1.5;margin-bottom:1rem;border-bottom:1px solid rgba(0,0,0,.06);padding-bottom:1rem\">Het systeem draait door. Schaalvergroting wint, familieondernemers verdwijnen, en geen enkele maatschappelijke opgave wordt gehaald. De motor draait, maar op de verkeerde brandstof. De verborgen kosten lopen op, maar niemand zet ze op de begroting.</p>\n    <p>Het startbeeld. Een boerderij in het veenweidegebied, van boven gezien, maar dan vijf jaar verder op het huidige pad. Strakker, efficiënter, verder geoptimaliseerd. Het landschap als productiemachine. Het resultaat van een systeem waarin grondschaarste, een op volume gerichte keten en afwezigheid van structurele steun samen logisch gedrag produceren: schaalvergroting.</p>\n    <p>De overheid heeft wel degelijk een aantal belangrijke maatregelen genomen, grondgebondenheid voorop. Maar voor natuurbeheer stuurt ze vooral op vrijwilligheid. En vrijwilligheid in een systeem dat draait op schaal en efficiëntie levert precies op wat je verwacht: weinig.</p>\n    <h4>Het beeld</h4>\n    <p>Egaal groen grasland, strakker dan ooit: geen onkruid, geen variatie, robotmatig gemaaid en bemest. Brede, kaarsrechte sloten zonder enige begroeiing. De percelen zijn groter geworden: sloten gedempt, kavels samengevoegd. Het land oogt leeg, opvallend weinig koeien buiten.</p>\n    <p>De koeien staan grotendeels op stal. Alleen als ze wél buiten staan, staan ze in grote koppels dicht bij elkaar op één perceel, een massale groep op een klein stuk land, de rest van de weiden leeg en onbenut. De stal is uitgebreid: groter, moderner, met mestopslag en voersilo's.</p>\n    <p>De CO₂-uitstoot is hoog en dubbel. Enerzijds de bodememissies: midden in de percelen blijft het droog, de boeren zijn niet genegen het waterpeil te verhogen, en dat diepe, droge veen oxideert continu. Anderzijds de bedrijfsemissies: veel vee betekent veel methaan, op stal of in de wei. Geen van beide bronnen daalt — de klimaatdoelen raken buiten bereik. Alleen voor ammoniak biedt de stal aanknopingspunten, en die maatregelen nemen boeren dan ook.</p>\n    <p>Het rentmeesterschap is verdwenen. Deze boeren hebben vooral veel hectares nodig. De liefde voor het land — het zorgvuldig beheren van slootkanten, het onderhouden van oevers, het kennen van elk perceel — is vervangen door efficiëntie. Natuur en biodiversiteit verdwijnen niet door kwade wil, maar doordat er simpelweg geen ruimte en aandacht meer voor is.</p>\n    <p>De boer verdient nog steeds, maar de marges worden dunner. De schaal compenseert wat de prijs per liter niet meer doet. Margedruk vernietigt het rentmeesterschap. En het tast de overdraagbaarheid aan: wie neemt zo’n bedrijf nog over? Boerenfamilies dreigen achter te blijven met kapitaalintensieve, onverkoopbare bedrijven.</p>\n    <div class=\"dim-list\">\n      <div class=\"dim-item\"><span class=\"dot red\"></span><span class=\"name\">Klimaat &amp; bodemdaling</span><span class=\"desc\">Diepe ontwatering, hoge veenoxidatie, bodememissies blijven onverminderd hoog</span></div>\n      <div class=\"dim-item\"><span class=\"dot red\"></span><span class=\"name\">Klimaat (bedrijf)</span><span class=\"desc\">Veel vee, hoge methaanuitstoot — geen daling van de bedrijfsemissies</span></div>\n      <div class=\"dim-item\"><span class=\"dot red\"></span><span class=\"name\">Water (kwaliteit)</span><span class=\"desc\">Verwaarloosd slootbeheer, hoge nutriëntenbelasting</span></div>\n      <div class=\"dim-item\"><span class=\"dot red\"></span><span class=\"name\">Water (kwantiteit)</span><span class=\"desc\">Geen berging, droogtegevoelig, geen actief peilbeheer</span></div>\n      <div class=\"dim-item\"><span class=\"dot red\"></span><span class=\"name\">Natuur (gebieden)</span><span class=\"desc\">Stikstofdepositie te hoog, Natura 2000-doelen buiten bereik</span></div>\n      <div class=\"dim-item\"><span class=\"dot red\"></span><span class=\"name\">Natuur (basiskwaliteit)</span><span class=\"desc\">Rentmeesterschap verdwijnt, slootkanten verwaarloosd, weidevogels weg</span></div>\n      <div class=\"dim-item\"><span class=\"dot red\"></span><span class=\"name\">Voedselzekerheid</span><span class=\"desc\">Hoog volume bulkmelk, maar afhankelijk van geïmporteerde soja en kunstmest, mest is afvoerprobleem — schijnzekerheid</span></div>\n      <div class=\"dim-item\"><span class=\"dot red\"></span><span class=\"name\">Cultuur &amp; landschap</span><span class=\"desc\">Industrieel grasland, geen veenweide-identiteit, geen beleving</span></div>\n      <div class=\"dim-item\"><span class=\"dot red\"></span><span class=\"name\">Grondstoffen &amp; kringloop</span><span class=\"desc\">Hoge import van veevoer en kunstmest, geen gesloten kringloop</span></div>\n      <div class=\"dim-item\"><span class=\"dot red\"></span><span class=\"name\">Wonen &amp; recreatie</span><span class=\"desc\">Bodemdaling en stikstof blokkeren woningbouw en recreatie, alles op slot</span></div>\n    </div>\n    <div style=\"background:rgba(0,0,0,.03);border-radius:var(--radius);padding:.875rem 1rem;margin:1rem 0;font-size:13px;line-height:1.6;border-left:3px solid var(--text3)\">\n      <strong style=\"display:block;margin-bottom:3px;color:var(--text)\">De motor, hoe werkt ondernemerschap hier?</strong>\n      De motor draait, maar op de verkeerde brandstof. Grote bedrijven draaien op bulkmelk en schaalvoordeel, familieondernemers verdwijnen al. De ondernemers die overblijven richten zich volledig op individuele economische waarde: zoveel mogelijk liters, zo laag mogelijke kosten. Maatschappelijke opgaves zijn geen drijfveer maar een kostenpost, iets om te minimaliseren, of net binnen de regels te houden. De motor is er, maar hij werkt de opgaves actief tegen.\n    </div>\n    <p><strong>De boodschap:</strong> Dit is niet houdbaar. Vrijwel alle opgaves staan op rood of oranje, maar dat is niet eens het diepste probleem. Het diepste probleem is de motor. De ondernemers die overblijven hebben geen enkele prikkel om de opgaves te halen. Ze zoeken de ruimte om te produceren <em>ondanks</em> de maatschappelijke doelen, niet dankzij. Ze doen wat het systeem beloont: schaal, liters, efficiëntie. Zolang dat zo is, worden de opgaves nooit gehaald, niet omdat boeren kwaadwillend zijn, maar omdat het systeem ze nooit vraagt of beloont om iets anders te doen. De verborgen kosten lopen intussen op: KRW-boetes, stikstofboetes, woningbouw op slot, infrastructuurschade door bodemdaling. Niemand zet ze op de begroting, maar de samenleving betaalt ze wel.</p>\n  </div>\n\n<div class=\"akte akte-2\" id=\"akte2\">\n    <div class=\"akte-number\">Akte II</div>\n    <h3>Ingrijpen zonder pijlers</h3>\n    <p style=\"font-size:14px;font-weight:500;color:var(--amber);line-height:1.5;margin-bottom:1rem;border-bottom:1px solid rgba(0,0,0,.06);padding-bottom:1rem\">De overheid grijpt in met harde maatregelen, maar verandert de systeemcondities niet. Precies de boeren die je nodig hebt voor de oplossing worden het gebied uitgeduwd. De opgaves lijken even te verbeteren, maar de verbetering keert doordat de rentmeesters verdwijnen.</p>\n    <p>De overheid ziet de rode dimensies uit akte I en grijpt in. Harde maatregelen, verplicht. Grondwaterstanden omhoog naar minimaal -40 cm in het veld. Strenge normering op waterkwaliteit. Stikstofbeperkingen op meerdere vlakken. Natuurverplichtingen. De aanpak: doelsturing, individueel of op gebiedsniveau. De boer moet de doelen halen.</p>\n    <p>Over compensatie wordt veel gesproken. Opkoopregelingen, bergboerenregelingen, uitbreiding van subsidies, discussies over langjarige contracten, het klinkt veelbelovend. Maar wat er in de praktijk komt is het juridisch minimum: privaatrechtelijke schadevergoeding bij onrechtmatig handelen, vrijwillige uitkoop. Er bestaat geen automatisch recht op nadeelcompensatie bij generieke maatregelen — daarvoor zou een individuele boer onevenredig zwaarder getroffen moeten worden dan andere veenweideboeren in vergelijkbare positie, en bij generieke peilfixatie is iedereen gelijk getroffen. Het verschil met akte III is fundamenteel: daar wordt de boer betaald als leverancier van publieke waarde. Hier wordt de boer gecompenseerd als slachtoffer van beleid, voor zover er überhaupt iets te krijgen valt. De kosten voor de overheid lopen fors op — handhaving, monitoring, subsidieapparaat, uitkoop — maar zonder rendement: er ontstaat geen nieuw verdienmodel. De overheid legt de opgave bij de boer en laat het ondernemerschap verder volledig voor eigen rekening en risico.</p>\n\n    <div style=\"background:var(--amber-light);border-left:3px solid var(--amber);border-radius:var(--radius);padding:1.25rem 1.5rem;margin:1.25rem 0;font-size:13.5px;line-height:1.65\">\n      <strong style=\"display:block;margin-bottom:6px;font-size:14px\">Driesporenbeleid, spoor 2 is akte II in beleidsvorm</strong>\n      <p style=\"margin:0\">Spoor 2 van het Rijksbeleid — peilfixatie op 90.000 ha met flankerend beleid via GLB-hectarepremie — is in instrumentele logica precies akte II. Het drukt het peil omhoog en compenseert grond, zonder de condities te scheppen waarin de boer een verdienmodel kan opbouwen. De aanname van het beleid is dat 25 jaar geleidelijkheid<span class=\"fiche-wrap\"><button class=\"fiche-btn\" type=\"button\" aria-label=\"Bron tonen\">ⓘ</button><span class=\"fiche-popup\"><span class=\"fiche-label\">Bron</span><span class=\"fiche-source\">Douwe Jonkers (LVVN), ambtelijke voorbespreking conceptbrief gebiedsspecifieke aanpak veenweide.</span><span class=\"fiche-note\">Nog niet publiek; bronaanduiding wordt aangevuld zodra de kamerbrief is verzonden.</span></span></span> (8 mm/jaar bodemdaling<span class=\"fiche-wrap\"><button class=\"fiche-btn\" type=\"button\" aria-label=\"Bron tonen\">ⓘ</button><span class=\"fiche-popup\"><span class=\"fiche-label\">Bron</span><span class=\"fiche-source\">Douwe Jonkers (LVVN), ambtelijke voorbespreking conceptbrief gebiedsspecifieke aanpak veenweide.</span><span class=\"fiche-note\">Nog niet publiek; bronaanduiding wordt aangevuld zodra de kamerbrief is verzonden.</span></span></span>) ondernemers de tijd geeft zich aan te passen. Maar geleidelijkheid in het peil is geen geleidelijkheid in het bedrijfsmodel. De ondernemer heeft die 25 jaar niet: zijn marge valt nu weg, zijn investeringshorizon is 5-10 jaar, zijn pacht is jaarlijks. Zonder verdienroute is geleidelijkheid een uitgesmeerde uitval.</p>\n    </div>\n\n    <div style=\"margin:1.5rem 0 1rem\">\n      <div style=\"font-size:11px;text-transform:uppercase;letter-spacing:.08em;color:var(--text3);font-weight:600;margin-bottom:.5rem\">De 90.000 ha is niet de scope van dit document</div>\n      <p style=\"font-size:13.5px;line-height:1.6;color:var(--text2);margin:0 0 .75rem\">De 90.000 ha van spoor 2 en de 20-30% waar dit document over gaat zijn niet hetzelfde gebied. De scope is een deelverzameling binnen de 90.000 ha. Dat onderscheid maakt de kritiek scherper:</p>\n\n      <div style=\"display:grid;grid-template-columns:1fr 1fr;gap:12px\">\n\n        <div style=\"background:var(--bg3);border:1px solid rgba(0,0,0,.06);border-radius:var(--radius);padding:1rem 1.25rem;font-size:13px;line-height:1.55\">\n          <strong style=\"display:block;margin-bottom:4px;font-size:13.5px;color:var(--text)\">Grootste deel van de 90.000 ha</strong>\n          <div style=\"color:var(--text2)\">Reguliere melkveehouderij blijft mogelijk. Vernatting werkt hier met waterinfiltratiesystemen (WIS) als instrument en aangepast graslandbeheer. Geen andere typologie nodig. De veenweideboeren-aanpak is daar niet voor bedoeld. <strong>Het probleem is hier instrumenteel:</strong> hectarepremie compenseert grond in plaats van diensten te belonen, en generieke peilfixatie pakt de boer die al weinig uitstoot (zie hieronder).</div>\n        </div>\n\n        <div style=\"background:var(--bg3);border:1px solid rgba(0,0,0,.06);border-radius:var(--radius);padding:1rem 1.25rem;font-size:13px;line-height:1.55\">\n          <strong style=\"display:block;margin-bottom:4px;font-size:13.5px;color:var(--text)\">De 20-30% scope binnen die 90.000 ha</strong>\n          <div style=\"color:var(--text2)\">Hier loopt zelfs reguliere melkveehouderij met WIS dood — door zeer lage ligging, sterke kwel, dunne veenpakketten of Natura 2000-druk. <strong>Het probleem is hier fundamenteel:</strong> vernatten zonder andere ondernemerstypologie loopt vast. Niet \"aangepast regulier\", maar de veenweideboer.</div>\n        </div>\n\n      </div>\n    </div>\n\n    <div style=\"background:var(--amber-light);border-left:3px solid var(--amber);border-radius:var(--radius);padding:1.25rem 1.5rem;margin:1.25rem 0;font-size:13.5px;line-height:1.65\">\n      <strong style=\"display:block;margin-bottom:6px;font-size:14px\">Generieke peilfixatie pakt de boer die al weinig uitstoot</strong>\n      <p style=\"margin:0 0 .75rem\">Niet elk veen emitteert evenveel. Percelen die al laag liggen zijn doorgaans natter en stoten minder broeikasgassen uit dan hoog gelegen percelen. Generieke peilfixatie binnen een peilvak raakt boeren met overwegend laaggelegen percelen — die nu al weinig uitstoten — harder dan boeren met hoge percelen die veel meer uitstoten. De boer die al weinig uitstoot, betaalt. Zonder kartering en differentiatie binnen peilvakken is dat moeilijk verdedigbaar.</p>\n      <p style=\"margin:0\"><strong>Water naar boven, rust op de rest.</strong> Hoog gelegen percelen stoten het meest uit en lijden het meest onder droogteschade — daar zit de winst van actief watermanagement. Lage natte percelen kunnen vaak met rust gelaten worden. Differentiatie binnen peilvakken benut die kennis; generieke peilfixatie negeert haar.</p>\n    </div>\n    <h4>Wat er verandert</h4>\n    <p>De trend uit akte I versnelt. De boeren die nog overgebleven waren — de kleinere, de lokale, de rentmeesters — kunnen nu definitief hun hoofd niet meer boven water houden. De kosten zijn toegenomen door de verplichtingen, de inkomstenderving wordt niet gecompenseerd. Ze stoppen.</p>\n    <p>Even lijkt het beter: waterstand stijgt, CO₂-uitstoot neemt af, sloten worden iets groener. De harde maatregelen doen op papier wat ze moeten doen.</p>\n    <div class=\"dim-list\">\n      <div class=\"dim-item\"><span class=\"dot amber\"></span><span class=\"name\">Klimaat &amp; bodemdaling</span><span class=\"desc\">Verbetert aanvankelijk door hoger peil, maar verbetering vlakt af als actief beheer (greppelinfiltratie, slootbeheer) verdwijnt met de rentmeesters</span></div>\n      <div class=\"dim-item\"><span class=\"dot amber\"></span><span class=\"name\">Klimaat (bedrijf)</span><span class=\"desc\">Onduidelijk, productie verplaatst zich naar elders, geen netto winst</span></div>\n      <div class=\"dim-item\"><span class=\"dot amber\"></span><span class=\"name\">Water (kwaliteit)</span><span class=\"desc\">Normering lijkt te werken, maar na-ijleffecten en gebrek aan slootbeheer zorgen dat verbetering uitblijft</span></div>\n      <div class=\"dim-item\"><span class=\"dot red\"></span><span class=\"name\">Water (kwantiteit)</span><span class=\"desc\">Vernatting vreet water op, geen actief beheer, geen buffering, waterbeschikbaarheid neemt af</span></div>\n      <div class=\"dim-item\"><span class=\"dot amber\"></span><span class=\"name\">Natuur (gebieden)</span><span class=\"desc\">Stikstofdepositie daalt door minder vee, Natura 2000-druk neemt iets af</span></div>\n      <div class=\"dim-item\"><span class=\"dot red\"></span><span class=\"name\">Natuur (basiskwaliteit)</span><span class=\"desc\">Sloten op de oude manier geschoond, basiskwaliteit wordt niet beter, eerder slechter</span></div>\n      <div class=\"dim-item\"><span class=\"dot red\"></span><span class=\"name\">Voedselzekerheid</span><span class=\"desc\">Verlies op alle drie de pijlers: minder productie, geen mest- of waterdienst ontwikkeld, kringloop niet gesloten</span></div>\n      <div class=\"dim-item\"><span class=\"dot red\"></span><span class=\"name\">Cultuur &amp; landschap</span><span class=\"desc\">De mensen die het landschap kenden zijn weg, identiteit en beleving verdwijnen</span></div>\n      <div class=\"dim-item\"><span class=\"dot red\"></span><span class=\"name\">Grondstoffen &amp; kringloop</span><span class=\"desc\">Geen verandering, bulksysteem blijft, kringloop blijft open</span></div>\n      <div class=\"dim-item\"><span class=\"dot red\"></span><span class=\"name\">Wonen &amp; recreatie</span><span class=\"desc\">Problemen lopen door, stikstof en het slepende overgangsproces blokkeren woningbouw en recreatie</span></div>\n    </div>\n    <div style=\"background:rgba(0,0,0,.03);border-radius:var(--radius);padding:.875rem 1rem;margin:1rem 0;font-size:13px;line-height:1.6;border-left:3px solid var(--text3)\">\n      <strong style=\"display:block;margin-bottom:3px;color:var(--text)\">De motor, wat gebeurt er met ondernemerschap?</strong>\n      De motor slaat af. Familieondernemers, biologisch én gangbaar — precies de mensen die de opgaves al serieus namen — kunnen de kostenstijging en inkomstenderving niet opvangen en stoppen. De grote bedrijven die overblijven hebben geen binding met het gebied. Hun motor draait op efficiëntie en afstand, niet op rentmeesterschap. En de overheid heeft de motor van het nieuwe type ondernemer nooit gevoed, alleen de verplichtingen opgelegd.\n    </div>\n    <h4>Wat er dan gebeurt</h4>\n    <p>De lokale rentmeesters verdwijnen. Hun land wordt ingenomen door grote boeren die misschien niet eens in het gebied zitten, bedrijven vanuit de kleigebieden met een enorme grondhonger. De schaalvergroting in combinatie met de grondgebondenheidsregel maakt dat ze vele hectares nodig hebben, en het vrijkomende veenweideland is goedkoop. Of het land gaat naar grondspeculanten en institutionele investeerders die wachten op betere tijden.</p>\n    <p>En dan keert de beweging. De grote boeren op afstand hebben geen binding met het land. Geen liefde voor het veenweidelandschap, geen zorg voor de slootkanten, geen oog voor de weidevogels. Ze beheren op efficiëntie, niet op rentmeesterschap. De verbeteringen die de harde maatregelen even opleverden — klimaat, water, natuur — worden weer teruggedraaid doordat de zorg voor het landschap verdwijnt met de mensen die het kenden.</p>\n    <p>De doelsturing werkt op papier. In de praktijk stuurt het de rentmeesters het gebied uit en vervangt het ze door beheerders op afstand.\n    </p><div style=\"background:var(--blue-light);border-left:3px solid var(--blue);border-radius:var(--radius);padding:.875rem 1rem;margin:1rem 0;font-size:13px;line-height:1.6\">\n      <strong style=\"display:block;margin-bottom:3px\">Let op: ook koploper-familieondernemers worden geraakt</strong>\n      Grove maatregelen zonder maatwerk treffen niet alleen de schaaloptimaliseerders. Familieondernemers die al verder zijn in de transitie — biologisch of anderszins, precies de mensen die de maatschappij wil behouden — vallen onder dezelfde normering. Het risico is reëel dat je met akte II precies degenen wegdrukt die je nodig hebt voor akte III.\n    </div><p></p>\n\n    <div style=\"background:var(--amber-light);border-left:3px solid var(--amber);border-radius:var(--radius);padding:1.25rem 1.5rem;margin:1rem 0;font-size:13.5px;line-height:1.65\">\n      <strong style=\"display:block;margin-bottom:6px;font-size:14px\">Driesporenbeleid, hectarepremie GLB versus zakelijke transactie</strong>\n      <p style=\"margin:0\">De kern van spoor 2 is een hectarepremie via het GLB. Dat is de subsidie-logica waar deze veenweideboeren-aanpak tegen waarschuwt: een hectarepremie compenseert grond, niet diensten. Hij vloeit weg in pachtprijzen, vergroot het kapitalisatierisico, en stuurt niet op resultaat. Hetzelfde geld kan anders worden besteed, als gebiedsspecifieke basisvergoeding voor wie in een vernattingsregime opereert, of als prestatievergoeding voor de levering van maatschappelijke diensten. Zelfde uitgave, ander instrument, fundamenteel ander effect.</p>\n    </div>\n    <p><strong>De boodschap:</strong> De overheid stelt de juiste doelen maar geeft de ondernemer niet de middelen om ze te halen. De maatregelen versnellen precies de trend die ze moesten stoppen: de lokale boer verdwijnt, het rentmeesterschap verdwijnt, en daarmee het fundament onder alle dimensies. En de relatie verhardt: de grote bedrijven die overblijven hebben de omzet en de juridische adviseurs om beleid bij de rechter te bestrijden — niet meer met trekkers naar het Binnenhof, maar met advocaten naar de Raad van State. Werken aan de opgaves komt dan op steeds meer terreinen in een juridisch moeras terecht.</p>\n  </div>\n","werkstand":{"nummer":"6, 7","ronde":"2","stand":"nog de bestuursversie; akte III is 19-8 eruit gehaald naar `akte-3.md`"},"skelet":[{"nummer":"6","titel":"Wat er gebeurt als er niets verandert (akte I)","bron":"e-aktes","stand":"ronde 2","deel":"Deel III — Hoe het kan lopen","kern":"Er verandert niets. Dat lijkt de veilige route en is het niet: bij de volgende schok in melkprijs, voer, klimaat of regelgeving valt een monocultuur om, en de opvolging is dan al onbetaalbaar geworden. Dit hoofdstuk beschrijft een toestand, geen keuze van iemand.","secties":[{"kop":"6.1 Een toestand die stabiel lijkt","elementen":[{"t":"de drie aktes in drie regels: er verandert niets · de maatregelen komen zonder verdienmodel eronder · dezelfde maatregelen mét verdienmodel eronder","v":"kader","h":"nieuw","n":"— de ene introductie die toetsregel 13 vraagt, hier omdat de lezer haar hier nodig heeft en nergens eerder"},{"t":"akte I lijkt te werken omdat er nog niets is gebeurd","v":"tekst","h":"verhuisd","n":"uit hoofdstuk 5"},{"t":"**geen verwijt aan wie niets doet:** dit is de beschrijving van een toestand die van buiten stabiel lijkt, niet van een keuze van iemand","v":"tekst","h":"nieuw","n":"toetsregel 12b"},{"t":"het is geen stabiele toestand maar een kwetsbaarheidspositie: een monocultuur die bij de volgende schok omvalt","v":"tekst","h":"nieuw","n":"besluit 17-8"},{"t":"bedrijfsopvolging wordt onbetaalbaar door het kapitalisatierisico","v":"tekst","h":"nieuw","n":"één zin, besluit 17-8"}]},{"kop":"6.2 Wat dat betekent per opgave","elementen":[{"t":"de tien dimensies bij akte I, met waterkwantiteit oranje in plaats van groen","v":"lijst","h":"auteurs","n":"correctie Niel"}]},{"kop":"6.3 De motor","elementen":[{"t":"hoe het ondernemerschap er in akte I uitziet","v":"tekst","h":"auteurs","n":"— vaste kop, elke akte heeft deze alinea"}]}],"noot":""},{"nummer":"7","titel":"Wat er gebeurt zonder verdienmodel eronder (akte II)","bron":"e-aktes","stand":"ronde 2","deel":"Deel III — Hoe het kan lopen","kern":"De maatregelen komen, en er ligt geen verdienmodel onder. De doelen zijn legitiem en de beperkingen zijn nodig; wat ontbreekt is de bodem waarop een bedrijf ze kan dragen. Dan landen de kosten bij de ondernemer, verdwijnt hij, en blijft de opgave over zonder iemand die haar uitvoert.","secties":[{"kop":"7.1 De maatregelen kloppen, er ligt alleen niets onder","elementen":[{"t":"**eerst de erkenning:** de doelen zijn legitiem en de beperkingen zijn nodig; wat ontbreekt is niet de wil of de inzet maar het verdienmodel eronder","v":"tekst","h":"nieuw","n":"toetsregel 2, en dit is de plek waar die regel moet landen"},{"t":"**akte II is niemands beleid.** Het is een categorie: wat er gebeurt bij elke ronde maatregelen zonder bedrijfsmodel eronder. Geen enkel voorbeeld uit het beleid van vandaag","v":"tekst","h":"nieuw","n":"besluit §8 en toetsregel 12b"},{"t":"de uitkoopregelingen van 2008 tot 2020 als eerdere ronde van hetzelfde mechanisme, zonder oordeel","v":"fiche","h":"nieuw","n":"besluit 17-8"},{"t":"de ondernemer valt om op kosten en omzet, niet op motivatie of vakmanschap","v":"tekst","h":"auteurs","n":"toetsregel 5"}]},{"kop":"7.2 Wat dat betekent per opgave","elementen":[{"t":"de dimensies bij akte II: waterkwantiteit rood, en waterkwaliteit verslechtert eerst door fosfaatmobilisatie","v":"lijst","h":"auteurs","n":"correcties Niel"}]},{"kop":"7.3 De motor","elementen":[{"t":"ook koploper-familieondernemers worden geraakt, en generieke peilfixatie raakt wie al weinig uitstoot","v":"fiche","h":"auteurs","n":"— de strekking hoort in de lopende tekst te landen"}]}],"noot":""}],"deel":"Deel III — Hoe het kan lopen"},{"id":"akte-3","letter":"8","titel":"Wat er gebeurt met een verdienmodel eronder","intro":"Dezelfde maatregelen als in akte II, en dezelfde doelsturing. Wat erbij komt is een verdienmodel eronder. Daarmee verschuift de kernvraag: niet meer hoe de ondernemer gecompenseerd wordt voor wat hij inlevert, maar hoe hij betaald wordt voor wat hij levert. Dat is de omkering waar dit document op rust, en zij staat als aanname 1 in hoofdstuk 2: dat maatschappelijke diensten een verdienmodel kunnen dragen achten wij aannemelijk, en bewezen is het niet.","html":"\n<h2>8 — Wat er gebeurt met een verdienmodel eronder</h2>\n\n<h3>8.1 De omslag: van vergoeding naar betaling</h3>\n\n<p>Dezelfde maatregelen als in akte II, en dezelfde doelsturing. Wat erbij komt is een verdienmodel eronder. Daarmee verschuift de kernvraag: niet meer hoe de ondernemer gecompenseerd wordt voor wat hij inlevert, maar hoe hij betaald wordt voor wat hij levert. Dat is de omkering waar dit document op rust, en zij staat als aanname 1 in hoofdstuk 2: dat maatschappelijke diensten een verdienmodel kunnen dragen achten wij aannemelijk, en bewezen is het niet.</p>\n\n<p>Wat de overheid daarbij doet valt in twee delen die uit elkaar gehouden moeten worden. Zij koopt diensten in, en dat is een opdracht met een prijs en een prestatie. En zij regelt een aantal zaken zonder er iets voor terug te krijgen, en dat is steun. Naarmate de prestatiecontracten gaan lopen groeit het eerste deel en krimpt het tweede; hoe dat kader eruitziet staat in hoofdstuk 11.</p>\n\n<p>Wat er eerst gebeurt is het grondbeleid. Dat stopt de grondhonger uit akte II: een grondbank vangt de waardedaling door vernatting op, zodat familiebedrijven niet gedwongen zijn te verkopen. Transitiesteun overbrugt de kwetsbare eerste jaren tot de contracten lopen, en de bergboerenregeling, de Europese regeling die bedrijven in gebieden met een natuurlijke handicap een structurele basisvergoeding geeft, biedt daarbij basiszekerheid.</p>\n\n<p>Het begint moeizaam. De ondernemer maakt de lastige overstap: minder koeien, ander landgebruik, nieuwe vaardigheden. De eerste jaren zijn kwetsbaar — daarvoor staat de transitie-infrastructuur klaar. Het bedrijfsmodel staat na zeven tot tien jaar volwaardig.<span class=\"fiche-wrap\"><button class=\"fiche-btn\" type=\"button\" aria-label=\"Toelichting tonen\">ⓘ</button><span class=\"fiche-popup\"><span class=\"fiche-label\">Drie tempo's, één transitie</span><span class=\"fiche-source\">Er zijn drie tempo's tegelijk in beweging, en zij lopen niet gelijk. Politieke tijd loopt in jaren tot decennia — wetgeving, EU-richtlijnen, instrumentontwikkeling. Ondernemerstijd loopt in maanden tot jaren — marge, pacht, investeringshorizon. Systeemtijd loopt in fasen — agroketens 2-3 jaar, banken 3-5, marktpartijen voor maatschappelijke diensten 7-15. Akte II synchroniseert deze tempo's niet; daarom valt de ondernemer weg voordat het beleid uitontwikkeld is. Akte III versnelt politieke tijd niet en vertraagt ondernemerstijd niet — het koppelt ze. Transitiesteun overbrugt ondernemerstijd zolang politieke tijd loopt. Prestatiecontracten van 10-20 jaar synchroniseren ondernemerstijd met systeemtijd. Hoofdstuk 12 mobiliseert systeemtijd binnen de termijn die ondernemerstijd vraagt. De tempo's worden in elkaar geschoven.</span><span class=\"fiche-note\">De vraag \"wanneer zijn alle beperkingen opgeheven?\"is daarmee verkeerd gesteld: vernatting, KRW-normen en stikstofeisen zijn de permanente nieuwe ordening, niet tijdelijke maatregelen. Tijdelijk zijn de transitie-instrumenten zelf. Het bedrijfsmodel staat in de orde van 7-10 jaar volwaardig.</span></span></span> Maar anders dan in akte II blijft de boer op het land. En daarmee het rentmeesterschap: de liefde voor het land, de kennis van elk perceel, de zorg voor de slootkanten.</p>\n\n<h3>8.2 Twee geldstromen, niet één</h3>\n\n<p>Er komt in akte III niet één geldstroom bij maar twee. De overheid koopt diensten in waar zij zelf een doel heeft te halen. Daarnaast zijn er private partijen met een eigen belang en een eigen begroting: een drinkwaterbedrijf dat zijn bron beschermt, een zuivelketen die op een certificaat stuurt, een bank die een langjarig contract als onderpand ziet. Dat onderscheid doet werk, want zolang alle inkomsten van de overheid komen houdt het weerwoord stand dat dit subsidie is met een ander etiket. Wie de partijen wil zien, vindt ze in hoofdstuk 12.</p>\n\n<p>Water is daarvan het schoonste voorbeeld, want de afnemer is er al. Oasen wint zijn drinkwater als oevergrondwater midden in dit gebied, en Waternet haalt ongeveer een derde van het zijne uit de Bethunepolder. Wat zij vandaag betalen is schade en geen dienst: wettelijk verplichte droogteschade. Daarnaast stuurt I&amp;W sinds 2026 op waterzelfvoorzienendheid van veenweidegebieden, dus ook aan de publieke kant zit een partij met een doel en zonder instrument. De bronnen bij die partijen staan bij aanname 2 in hoofdstuk 2.</p>\n\n<p>Bij stikstof ligt een vergelijkbare denkrichting, en die is verder van de praktijk af. <span class=\"fiche-wrap\"><button class=\"fiche-btn\" type=\"button\" aria-label=\"Toelichting tonen\">ⓘ</button><span class=\"fiche-popup\"><span class=\"fiche-label\">Toelichting</span><span class=\"fiche-source\">Stikstofruimte als denkbare dienst. Het kabinet zoekt stikstofruimte, en snel: bouwen, het stroomnet en defensie wachten erop. Uitkoop levert die ruimte één keer, en daarna is het gebied zijn beheerder kwijt. Een lagere veedichtheid levert dezelfde ammoniakreductie, blijvend, en precies waar die het meest telt: tegen Natura 2000 aan. Eén voorwaarde: het wegvallende vee-inkomen wordt aangevuld met betaling voor maatschappelijke diensten, anders is het uitkoop in vertraagde vorm. Doorgedacht kan ammoniakreductie zelf zo'n dienst worden, en die denkrichting vraagt eerst juridische uitwerking: extern salderen en vergunningenrecht.</span></span></span></p>\n\n<h3>8.3 Wat dat betekent per opgave     &lt;p&gt;De bouwstenen worden beschikbaar. Elke ingezette bouwsteen verandert het landschap én verbetert de opgaves. Maar nu werken de veranderingen mét in plaats van tégen de boer.&lt;/p&gt;     &lt;p&gt;De CO₂-uitstoot daalt, beide bronnen. De bodememissies verminderen omdat de boer natte teelt en koolstofopslag als verdienmodel inzet: de grondwaterstand midden in de percelen gaat omhoog omdat het nu loont. De bedrijfsemissies nemen af omdat het bedrijf anders is opgezet: minder maar beter vee, lagere emissies per hectare. Waterkwaliteit verbetert, niet door normering alleen, maar omdat ecologisch slootbeheer weer de moeite waard is. Waterkwantiteit verbetert ook: wateropslag op het bedrijf wordt een bouwsteen, de boer buffert water lokaal en wordt betaald voor wateropslag als dienst. Natuur keert terug, niet als verplichting die hectares inneemt, maar omdat biodiversiteitsdiensten en natuur als dienst het rentmeesterschap weer rendabel maken.&lt;/p&gt;     &lt;p&gt;Het inkomen herstelt naar het niveau van een leefbaar familiebedrijf, niet de pieken van bulkmelk op schaal, wel structureel zekerder dan het marginale inkomen van akte I. Opgebouwd uit meerdere stabiele inkomstenstromen: maatschappelijke diensten, premium voedsel, waterberging, CO₂-credits.&lt;/p&gt;     &lt;div class=\"dim-list\"&gt;       &lt;div class=\"dim-item\"&gt;&lt;span class=\"dot green\"&gt;&lt;/span&gt;&lt;span class=\"name\"&gt;Klimaat &amp; bodemdaling&lt;/span&gt;&lt;span class=\"desc\"&gt;Waterpeil omhoog omdat het loont, koolstofopslag als verdienmodel&lt;/span&gt;&lt;/div&gt;       &lt;div class=\"dim-item\"&gt;&lt;span class=\"dot green\"&gt;&lt;/span&gt;&lt;span class=\"name\"&gt;Klimaat (bedrijf)&lt;/span&gt;&lt;span class=\"desc\"&gt;Lagere veedichtheid: minder vee, lagere emissies per hectare&lt;/span&gt;&lt;/div&gt;       &lt;div class=\"dim-item\"&gt;&lt;span class=\"dot green\"&gt;&lt;/span&gt;&lt;span class=\"name\"&gt;Water (kwaliteit)&lt;/span&gt;&lt;span class=\"desc\"&gt;Ecologisch sloot- en oeverbeheer is nu rendabel, kwaliteit verbetert structureel&lt;/span&gt;&lt;/div&gt;       &lt;div class=\"dim-item\"&gt;&lt;span class=\"dot amber\"&gt;&lt;/span&gt;&lt;span class=\"name\"&gt;Water (kwantiteit)&lt;/span&gt;&lt;span class=\"desc\"&gt;Wateropslag als betaalde dienst helpt, maar de totale watervraag bij vernatting blijft een ruimtelijk vraagstuk&lt;/span&gt;&lt;/div&gt;       &lt;div class=\"dim-item\"&gt;&lt;span class=\"dot green\"&gt;&lt;/span&gt;&lt;span class=\"name\"&gt;Natuur (gebieden)&lt;/span&gt;&lt;span class=\"desc\"&gt;Minder depositie + actief bufferbeheer rond Natura 2000 als betaalde dienst&lt;/span&gt;&lt;/div&gt;       &lt;div class=\"dim-item\"&gt;&lt;span class=\"dot green\"&gt;&lt;/span&gt;&lt;span class=\"name\"&gt;Natuur (basiskwaliteit)&lt;/span&gt;&lt;span class=\"desc\"&gt;Rentmeesterschap terug: weidevogels, slootkanten, biodiversiteit als verdienmodel&lt;/span&gt;&lt;/div&gt;       &lt;div class=\"dim-item\"&gt;&lt;span class=\"dot green\"&gt;&lt;/span&gt;&lt;span class=\"name\"&gt;Voedselzekerheid&lt;/span&gt;&lt;span class=\"desc\"&gt;Drie kanten: duurzamere directe productie, organische stof naar de akkerbouw, en minder afhankelijkheid van soja en kunstmest&lt;/span&gt;&lt;/div&gt;       &lt;div class=\"dim-item\"&gt;&lt;span class=\"dot green\"&gt;&lt;/span&gt;&lt;span class=\"name\"&gt;Cultuur &amp; landschap&lt;/span&gt;&lt;span class=\"desc\"&gt;Landschapsidentiteit terug, weidegang, divers veenweidelandschap&lt;/span&gt;&lt;/div&gt;       &lt;div class=\"dim-item\"&gt;&lt;span class=\"dot green\"&gt;&lt;/span&gt;&lt;span class=\"name\"&gt;Grondstoffen &amp; kringloop&lt;/span&gt;&lt;span class=\"desc\"&gt;Natte teelt levert eigen strooisel en biomassa, kringloop sluit zich op bedrijfsniveau&lt;/span&gt;&lt;/div&gt;       &lt;div class=\"dim-item\"&gt;&lt;span class=\"dot amber\"&gt;&lt;/span&gt;&lt;span class=\"name\"&gt;Wonen &amp; recreatie&lt;/span&gt;&lt;span class=\"desc\"&gt;RO-typologie maakt functiemenging mogelijk: wonen bij de boer, recreatiewoningen, tiny houses&lt;/span&gt;&lt;/div&gt;     &lt;/div&gt; ### 8.4 De motor</h3>\n\n<p>De motor draait op de juiste brandstof. De verbonden ondernemer ziet de opgaves niet als kostenpost maar als verdienmodel: schoon water, vastgehouden koolstof, weidevogels, landschapskwaliteit, dat zijn diensten waarvoor betaald wordt. Niet als compensatie, maar als vergoeding voor geleverde publieke waarde. De motor trekt de opgaves mee, in plaats van er tegenin te werken. &lt;p&gt;Het ondernemerschap in akte III is fundamenteel anders dan in akte I. Daar was de ondernemer een handelsgerichte schaaloptimalisator, gericht op uniformiteit, replicatie en schaalvergroting, met het land als productiemiddel voor de bulkmarkt&lt;span class=\"fiche-wrap\"&gt;&lt;button class=\"fiche-btn\" type=\"button\" aria-label=\"Bron tonen\"&gt;ⓘ&lt;/button&gt;&lt;span class=\"fiche-popup\"&gt;&lt;span class=\"fiche-label\"&gt;Bron&lt;/span&gt;&lt;span class=\"fiche-source\"&gt;ZuivelNL, Blik op Zuivel 2026: ca. 75% van de Nederlandse zuivelafzet blijft binnen de EU (waarvan ca. 40% binnen Nederland); ca. 25% gaat naar o.a. China, de VS en het VK.&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;. Hier wordt dezelfde ondernemer bréder: gebiedsgericht en verbonden, met diversiteit en lokale verbondenheid als verdienprincipe. Intrinsiek gedreven, verbonden met de omgeving, met het land en met de mensen eromheen.&lt;/p&gt; &lt;p&gt;Het doel van akte III is dat het veenweidegebied vol zit met dit soort ondernemers. Niet één pioniersboer die het lukt ondanks het systeem, maar veel verbonden ondernemers die de opgaves helpen halen mét behoud van eigen perspectief. Het ondernemerschap is nog steeds de motor, maar de motor draait nu op een andere brandstof.&lt;/p&gt; &lt;p&gt;In akte II leken klimaat, water en natuur even te verbeteren, maar de beweging keerde doordat de rentmeesters verdwenen. Hier houdt de verbetering stand, omdat de mensen die het land kennen en liefhebben er nog zijn. Ze hebben nu een reden om te blijven, niet alleen de liefde voor het land, maar ook een daadwerkelijk verdienvermogen en perspectief. En daarmee een reden om de opgaves te omarmen in plaats van ertegen te vechten.&lt;/p&gt; &lt;p&gt;&lt;strong&gt;Let op, conflicten worden zichtbaar:&lt;/strong&gt; Niet alle bouwstenen passen bij elkaar. Sommige combinaties bijten. De ondernemer moet kiezen, en dat is precies het punt. De transitie is geen optimalisatieoefening maar een reeks dilemma's. Akte III is in die zin geen morele maar een ontwerpkeuze: een systeem dat van variatie profiteert in plaats van eraan onderdoor te gaan.&lt;/p&gt;</p>\n\n<!-- DIMENSIE-ONTWIKKELING -->\n\n<div id=\"e-dimensies\">\n<div style=\"margin-top:2.5rem\" id=\"dimensie-overzicht\">\n    <h3>Ontwikkeling per dimensie over de drie aktes<span class=\"fiche-wrap\" style=\"margin-left:8px\"><button class=\"fiche-btn\" type=\"button\" aria-label=\"Hoe te lezen\">ⓘ</button><span class=\"fiche-popup\"><span class=\"fiche-label\">Hoe te lezen</span><span class=\"fiche-source\">Deze tabel toont per dimensie hoe de <strong>stand van de opgave</strong> zich ontwikkelt onder de drie scenario's. Het gaat hier niet om gewicht (zoals in sectie B), maar om de feitelijke uitkomst: wordt de opgave structureel behaald of niet?</span><span class=\"fiche-note\">groen = structureel behaald · oranje = gemengd, deels verbetering maar onhoudbaar · rood = niet behaald, druk blijft of verergert · \"oranje → rood\" = lijkt eerst te verbeteren, maar slaat om.</span></span></span></h3>\n    <table class=\"bouwsteen-table\" style=\"margin-top:1rem\">\n      <thead>\n        <tr>\n          <th style=\"min-width:100px\">Dimensie</th>\n          <th>Akte I — Over vijf jaar</th>\n          <th>Akte II — Ingrijpen zonder pijlers</th>\n          <th>Akte III — Mét pijlers</th>\n        </tr>\n      </thead>\n      <tbody>\n        <tr>\n          <td><strong>Klimaat &amp; bodemdaling</strong></td>\n          <td><span class=\"tag-conflict\">rood</span> Diepe ontwatering, veenoxidatie onverminderd hoog</td>\n          <td><span style=\"display:inline-block;font-size:10px;background:var(--amber-light);color:var(--amber);padding:1px 6px;border-radius:3px;font-weight:500\">oranje → rood</span> Verbetert eerst door hoger peil, vlakt af als actief beheer verdwijnt</td>\n          <td><span class=\"tag-up\">groen</span> Waterpeil omhoog omdat het loont, structureel</td>\n        </tr>\n        <tr>\n          <td><strong>Klimaat (bedrijf)</strong></td>\n          <td><span class=\"tag-conflict\">rood</span> Veel vee, emissies onverminderd hoog</td>\n          <td><span style=\"display:inline-block;font-size:10px;background:var(--amber-light);color:var(--amber);padding:1px 6px;border-radius:3px;font-weight:500\">oranje</span> Productie verplaatst zich — geen netto winst</td>\n          <td><span class=\"tag-up\">groen</span> Lagere veedichtheid — minder emissies per hectare</td>\n        </tr>\n        <tr>\n          <td><strong>Water (kwaliteit)</strong></td>\n          <td><span class=\"tag-conflict\">rood</span> Verwaarloosd slootbeheer, hoge nutriëntenbelasting</td>\n          <td><span style=\"display:inline-block;font-size:10px;background:var(--amber-light);color:var(--amber);padding:1px 6px;border-radius:3px;font-weight:500\">oranje → rood</span> Normering lijkt te werken, na-ijleffecten ondermijnen resultaat</td>\n          <td><span class=\"tag-up\">groen</span> Slootbeheer rendabel — structurele verbetering</td>\n        </tr>\n        <tr>\n          <td><strong>Water (kwantiteit)</strong></td>\n          <td><span class=\"tag-conflict\">rood</span> Geen berging, droogtegevoelig</td>\n          <td><span class=\"tag-conflict\">rood</span> Vernatting vreet water, geen buffering, beschikbaarheid neemt af</td>\n          <td><span style=\"display:inline-block;font-size:10px;background:var(--amber-light);color:var(--amber);padding:1px 6px;border-radius:3px;font-weight:500\">oranje</span> Wateropslag helpt, maar watervraag bij vernatting blijft ruimtelijk vraagstuk</td>\n        </tr>\n        <tr>\n          <td><strong>Natuur (gebieden)</strong></td>\n          <td><span class=\"tag-conflict\">rood</span> Stikstofdepositie te hoog, Natura 2000-doelen buiten bereik</td>\n          <td><span style=\"display:inline-block;font-size:10px;background:var(--amber-light);color:var(--amber);padding:1px 6px;border-radius:3px;font-weight:500\">oranje</span> Minder vee, minder depositie, druk op natuurgebieden neemt iets af</td>\n          <td><span class=\"tag-up\">groen</span> Minder depositie + actief bufferbeheer als betaalde dienst</td>\n        </tr>\n        <tr>\n          <td><strong>Natuur (basiskwaliteit)</strong></td>\n          <td><span class=\"tag-conflict\">rood</span> Rentmeesterschap verdwijnt: slootkanten, weidevogels, biodiversiteit in het boerenland holt achteruit</td>\n          <td><span class=\"tag-conflict\">rood</span> Sloten op de oude manier geschoond, basiskwaliteit wordt niet beter ondanks maatregelen</td>\n          <td><span class=\"tag-up\">groen</span> Rentmeesterschap terug, weidevogels, slootkanten en biodiversiteit als verdienmodel</td>\n        </tr>\n        <tr>\n          <td><strong>Voedselzekerheid</strong></td>\n          <td><span class=\"tag-conflict\">rood</span> Hoog volume, maar mede afhankelijk van geïmporteerd krachtvoer en kunstmest; mest is een afvoerprobleem in plaats van een dienst aan de akkerbouw; geen waterdienst — schijnzekerheid</td>\n          <td><span class=\"tag-conflict\">rood</span> Verlies op alle drie de pijlers: minder productie, geen mest- of waterdienst ontwikkeld, kringloop niet gesloten</td>\n          <td><span class=\"tag-up\">groen</span> Drie pijlers tegelijk: kleinere maar duurzamere directe productie + organische mest en waterbuffer voor akkerbouw + minder afhankelijkheid van soja en kunstmest</td>\n        </tr>\n        <tr>\n          <td><strong>Cultuur &amp; landschap</strong></td>\n          <td><span class=\"tag-conflict\">rood</span> Industrieel grasland, geen veenweide-identiteit</td>\n          <td><span class=\"tag-conflict\">rood</span> De mensen die het landschap kenden zijn weg</td>\n          <td><span class=\"tag-up\">groen</span> Landschapsidentiteit terug + zichtbaar dierenwelzijn</td>\n        </tr>\n        <tr>\n          <td><strong>Grondstoffen &amp; kringloop</strong></td>\n          <td><span class=\"tag-conflict\">rood</span> Import van krachtvoer en kunstmest blijft — kringloop blijft open</td>\n          <td><span class=\"tag-conflict\">rood</span> Geen verandering — bulksysteem blijft</td>\n          <td><span class=\"tag-up\">groen</span> Natte teelt sluit kringloop — eigen strooisel en biomassa</td>\n        </tr>\n        <tr>\n          <td><strong>Wonen &amp; recreatie</strong></td>\n          <td><span class=\"tag-conflict\">rood</span> Stikstof en bodemdaling blokkeren woningbouw en recreatie</td>\n          <td><span class=\"tag-conflict\">rood</span> Problemen lopen door, woningbouw en recreatie geblokkeerd</td>\n          <td><span style=\"display:inline-block;font-size:10px;background:var(--amber-light);color:var(--amber);padding:1px 6px;border-radius:3px;font-weight:500\">oranje</span> RO-typologie maakt functiemenging mogelijk: wonen, recreatie, tiny houses</td>\n        </tr>\n        <tr style=\"background:rgba(0,0,0,.025);border-top:2px solid rgba(0,0,0,.08)\">\n          <td><strong style=\"color:var(--text3)\">Ondernemerschap (motor)</strong></td>\n          <td><span style=\"display:inline-block;font-size:10px;background:var(--amber-light);color:var(--amber);padding:1px 6px;border-radius:3px;font-weight:500\">draait verkeerd</span> Motor op individuele waarde — opgaves zijn kostenpost</td>\n          <td><span class=\"tag-conflict\">slaat af</span> Motor stopt, familieondernemers en koplopers verdwijnen</td>\n          <td><span class=\"tag-up\">draait mee</span> Motor op publieke waarde, ondernemer levert en wordt betaald</td>\n        </tr>\n      </tbody>\n    </table>\n    <div style=\"display:flex;gap:16px;align-items:center;margin-top:14px;flex-wrap:wrap;font-size:11px\">\n      <div style=\"color:var(--text3);font-weight:600;text-transform:uppercase;letter-spacing:.06em\">Staat van de opgave:</div>\n      <div style=\"display:flex;gap:14px;flex-wrap:wrap;color:var(--text2);align-items:center\">\n        <span><span style=\"display:inline-block;font-size:10px;background:var(--accent-light);color:var(--accent2);padding:1px 6px;border-radius:3px;font-weight:500;margin-right:4px\">groen</span>structureel behaald</span>\n        <span><span style=\"display:inline-block;font-size:10px;background:var(--amber-light);color:var(--amber);padding:1px 6px;border-radius:3px;font-weight:500;margin-right:4px\">oranje</span>gemengd, deels verbetering</span>\n        <span><span style=\"display:inline-block;font-size:10px;background:var(--red-light);color:var(--red);padding:1px 6px;border-radius:3px;font-weight:500;margin-right:4px\">rood</span>niet behaald, druk blijft</span>\n        <span><span style=\"display:inline-block;font-size:10px;background:var(--amber-light);color:var(--amber);padding:1px 6px;border-radius:3px;font-weight:500;margin-right:4px\">oranje → rood</span>verbetert eerst, slaat om</span>\n      </div>\n    </div>\n    <p style=\"font-size:13px;color:var(--text2);margin-top:.75rem\">In akte II verbeteren klimaat, water en natuur aanvankelijk door de harde maatregelen, maar de verbetering keert doordat de rentmeesters verdwijnen en beheerders op afstand het overnemen. Alleen in akte III houden de verbeteringen stand.</p>\n\n    <!-- KOSTENVERSCHUIVING VISUAL -->\n\n\n\n  </div>\n\n<h3 style=\"margin-top:2.5rem\" id=\"kosten\">Kostenverschuiving per akte</h3>\n    <p style=\"font-size:13.5px;color:var(--text2);margin-bottom:1rem\">De kosten verdwijnen niet: ze verschuiven van plek, van type, en van labeling. Het geld dat je als overheid zou besteden aan compensatie, zou je ook kunnen inzetten om ondernemers een deel van je problemen te laten oplossen. Dat is de kern.</p>\n\n    <!-- SVG KOSTEN/OPBRENGSTEN DIAGRAM -->\n    <div style=\"background:var(--bg3);border:1px solid rgba(0,0,0,.06);border-radius:var(--radius-lg);padding:1.5rem;margin:1rem 0 1.5rem;overflow-x:auto\">\n      <svg viewBox=\"0 0 780 420\" style=\"width:100%;display:block\" xmlns=\"http://www.w3.org/2000/svg\">\n        <defs>\n          <marker id=\"arUp\" markerWidth=\"7\" markerHeight=\"5\" refX=\"3.5\" refY=\"0\" orient=\"auto\"><path d=\"M0,5 L3.5,0 L7,5\" fill=\"#5C5A54\"></path></marker>\n          <marker id=\"arDn\" markerWidth=\"7\" markerHeight=\"5\" refX=\"3.5\" refY=\"5\" orient=\"auto\"><path d=\"M0,0 L3.5,5 L7,0\" fill=\"#5C5A54\"></path></marker>\n          <!-- Rood gearceerd: verborgen kosten -->\n          <pattern id=\"diagRed\" width=\"6\" height=\"6\" patternUnits=\"userSpaceOnUse\" patternTransform=\"rotate(45)\"><rect width=\"2\" height=\"6\" fill=\"rgba(181,68,46,.2)\"></rect></pattern>\n          <!-- Groen gearceerd: nieuwe waarden -->\n          <pattern id=\"diagGreen\" width=\"6\" height=\"6\" patternUnits=\"userSpaceOnUse\" patternTransform=\"rotate(45)\"><rect width=\"2\" height=\"6\" fill=\"rgba(59,122,87,.25)\"></rect></pattern>\n        </defs>\n\n        <!-- Baseline labels -->\n        <text x=\"16\" y=\"255\" font-family=\"var(--font-body)\" font-size=\"8\" fill=\"#8A877F\">ondernemer ↑</text>\n        <text x=\"16\" y=\"268\" font-family=\"var(--font-body)\" font-size=\"8\" fill=\"#8A877F\">overheid ↓</text>\n\n        <!-- ═══════════ AKTE 1 ═══════════ -->\n        <text x=\"130\" y=\"18\" text-anchor=\"middle\" font-family=\"var(--font-display)\" font-size=\"14\" font-weight=\"700\" fill=\"#B5442E\">Akte I</text>\n\n        <!-- Poppetjes -->\n        <text x=\"70\" y=\"50\" font-family=\"var(--font-body)\" font-size=\"9\" fill=\"#8A877F\" font-weight=\"500\"># ondernemers</text>\n        <text x=\"70\" y=\"68\" font-size=\"16\">👤</text>\n        <text x=\"90\" y=\"68\" font-size=\"16\">👤</text>\n        <text x=\"110\" y=\"68\" font-size=\"16\">👤</text>\n        <text x=\"130\" y=\"68\" font-size=\"16\" opacity=\"0.3\">👤</text>\n        <line x1=\"133\" y1=\"55\" x2=\"143\" y2=\"72\" stroke=\"#B5442E\" stroke-width=\"2\"></line>\n        <text x=\"150\" y=\"68\" font-size=\"16\" opacity=\"0.3\">👤</text>\n        <line x1=\"153\" y1=\"55\" x2=\"163\" y2=\"72\" stroke=\"#B5442E\" stroke-width=\"2\"></line>\n\n        <!-- Kostenkolom -->\n        <rect x=\"65\" y=\"90\" width=\"52\" height=\"170\" rx=\"2\" fill=\"#B5442E\" opacity=\"0.1\" stroke=\"#B5442E\" stroke-width=\"1.5\"></rect>\n        <text x=\"91\" y=\"185\" text-anchor=\"middle\" font-family=\"var(--font-body)\" font-size=\"11\" fill=\"#B5442E\" font-weight=\"600\" transform=\"rotate(-90,91,185)\">KOSTEN</text>\n\n        <!-- Opbrengstkolom (melk) -->\n        <rect x=\"127\" y=\"80\" width=\"52\" height=\"180\" rx=\"2\" fill=\"#C49A1E\" opacity=\"0.12\" stroke=\"#C49A1E\" stroke-width=\"1.5\"></rect>\n        <text x=\"153\" y=\"180\" text-anchor=\"middle\" font-family=\"var(--font-body)\" font-size=\"11\" fill=\"#C49A1E\" font-weight=\"600\" transform=\"rotate(-90,153,180)\">MELK</text>\n\n        <!-- Winst -->\n        <rect x=\"127\" y=\"80\" width=\"52\" height=\"10\" rx=\"2\" fill=\"#C49A1E\" opacity=\"0.06\"></rect>\n        <line x1=\"63\" y1=\"90\" x2=\"181\" y2=\"90\" stroke=\"rgba(0,0,0,.12)\" stroke-width=\"1\" stroke-dasharray=\"3 2\"></line>\n        <text x=\"185\" y=\"88\" font-family=\"var(--font-body)\" font-size=\"10\" fill=\"#C49A1E\" font-weight=\"600\">winst</text>\n        <text x=\"185\" y=\"100\" font-family=\"var(--font-body)\" font-size=\"8\" fill=\"#8A877F\" font-style=\"italic\">(dun)</text>\n\n        <!-- Labels -->\n        <text x=\"187\" y=\"175\" font-family=\"var(--font-body)\" font-size=\"8\" fill=\"#8A877F\" transform=\"rotate(90,187,175)\">OPBRENGSTEN</text>\n\n        <!-- Baseline -->\n        <line x1=\"55\" y1=\"260\" x2=\"200\" y2=\"260\" stroke=\"rgba(0,0,0,.2)\" stroke-width=\"1.5\"></line>\n\n        <!-- Verborgen kosten: ROOD gearceerd, alleen onder kostenkolom, GROOT -->\n        <rect x=\"65\" y=\"265\" width=\"52\" height=\"55\" rx=\"2\" fill=\"url(#diagRed)\" stroke=\"#B5442E\" stroke-width=\"1\" opacity=\"0.8\"></rect>\n        <text x=\"91\" y=\"290\" text-anchor=\"middle\" font-family=\"var(--font-body)\" font-size=\"8\" fill=\"#B5442E\" font-weight=\"500\">verborgen</text>\n        <text x=\"91\" y=\"300\" text-anchor=\"middle\" font-family=\"var(--font-body)\" font-size=\"8\" fill=\"#B5442E\">kosten</text>\n        <text x=\"91\" y=\"313\" text-anchor=\"middle\" font-family=\"var(--font-body)\" font-size=\"8\" fill=\"#B5442E\" font-weight=\"600\">(groot)</text>\n\n        <!-- Scheidslijn -->\n        <line x1=\"250\" y1=\"40\" x2=\"250\" y2=\"380\" stroke=\"rgba(0,0,0,.06)\" stroke-width=\"1\" stroke-dasharray=\"4 4\"></line>\n\n\n        <!-- ═══════════ AKTE 2 ═══════════ -->\n        <text x=\"390\" y=\"18\" text-anchor=\"middle\" font-family=\"var(--font-display)\" font-size=\"14\" font-weight=\"700\" fill=\"#C49A1E\">Akte II</text>\n\n        <!-- Poppetjes -->\n        <text x=\"330\" y=\"50\" font-family=\"var(--font-body)\" font-size=\"9\" fill=\"#8A877F\" font-weight=\"500\"># ondernemers</text>\n        <text x=\"330\" y=\"68\" font-size=\"16\">👤</text>\n        <text x=\"350\" y=\"68\" font-size=\"16\">👤</text>\n        <text x=\"370\" y=\"68\" font-size=\"16\" opacity=\"0.3\">👤</text>\n        <line x1=\"373\" y1=\"55\" x2=\"383\" y2=\"72\" stroke=\"#B5442E\" stroke-width=\"2\"></line>\n        <text x=\"390\" y=\"68\" font-size=\"16\" opacity=\"0.3\">👤</text>\n        <line x1=\"393\" y1=\"55\" x2=\"403\" y2=\"72\" stroke=\"#B5442E\" stroke-width=\"2\"></line>\n        <text x=\"410\" y=\"68\" font-size=\"16\" opacity=\"0.3\">👤</text>\n        <line x1=\"413\" y1=\"55\" x2=\"423\" y2=\"72\" stroke=\"#B5442E\" stroke-width=\"2\"></line>\n\n        <!-- Kostenkolom — stijgt -->\n        <rect x=\"325\" y=\"75\" width=\"52\" height=\"185\" rx=\"2\" fill=\"#B5442E\" opacity=\"0.12\" stroke=\"#B5442E\" stroke-width=\"1.5\"></rect>\n        <text x=\"351\" y=\"175\" text-anchor=\"middle\" font-family=\"var(--font-body)\" font-size=\"11\" fill=\"#B5442E\" font-weight=\"600\" transform=\"rotate(-90,351,175)\">KOSTEN</text>\n        <line x1=\"351\" y1=\"73\" x2=\"351\" y2=\"83\" stroke=\"#5C5A54\" stroke-width=\"1.5\" marker-start=\"url(#arUp)\"></line>\n\n        <!-- Opbrengstkolom (melk) — krimpt -->\n        <rect x=\"387\" y=\"115\" width=\"52\" height=\"145\" rx=\"2\" fill=\"#C49A1E\" opacity=\"0.1\" stroke=\"#C49A1E\" stroke-width=\"1.5\" stroke-dasharray=\"4 2\"></rect>\n        <text x=\"413\" y=\"195\" text-anchor=\"middle\" font-family=\"var(--font-body)\" font-size=\"11\" fill=\"#C49A1E\" font-weight=\"500\" transform=\"rotate(-90,413,195)\">MELK ↓</text>\n        <line x1=\"413\" y1=\"112\" x2=\"413\" y2=\"122\" stroke=\"#5C5A54\" stroke-width=\"1.5\" marker-end=\"url(#arDn)\"></line>\n\n        <!-- Geen winst -->\n        <line x1=\"325\" y1=\"115\" x2=\"441\" y2=\"115\" stroke=\"rgba(0,0,0,.15)\" stroke-width=\"1\" stroke-dasharray=\"3 3\"></line>\n        <text x=\"448\" y=\"113\" font-family=\"var(--font-body)\" font-size=\"9\" fill=\"#B5442E\" font-weight=\"600\">geen winst</text>\n\n        <!-- Baseline -->\n        <line x1=\"315\" y1=\"260\" x2=\"460\" y2=\"260\" stroke=\"rgba(0,0,0,.2)\" stroke-width=\"1.5\"></line>\n\n        <!-- Verborgen kosten: ROOD gearceerd, alleen onder kostenkolom, KLEINER -->\n        <rect x=\"325\" y=\"265\" width=\"52\" height=\"35\" rx=\"2\" fill=\"url(#diagRed)\" stroke=\"#B5442E\" stroke-width=\"1\" opacity=\"0.8\"></rect>\n        <text x=\"351\" y=\"282\" text-anchor=\"middle\" font-family=\"var(--font-body)\" font-size=\"7\" fill=\"#B5442E\" font-weight=\"500\">verborgen</text>\n        <text x=\"351\" y=\"292\" text-anchor=\"middle\" font-family=\"var(--font-body)\" font-size=\"7\" fill=\"#B5442E\">kosten ↓</text>\n\n        <!-- Scheidslijn -->\n        <line x1=\"510\" y1=\"40\" x2=\"510\" y2=\"380\" stroke=\"rgba(0,0,0,.06)\" stroke-width=\"1\" stroke-dasharray=\"4 4\"></line>\n\n\n        <!-- ═══════════ AKTE 3 ═══════════ -->\n        <text x=\"645\" y=\"18\" text-anchor=\"middle\" font-family=\"var(--font-display)\" font-size=\"14\" font-weight=\"700\" fill=\"#3ea635\">Akte III</text>\n\n        <!-- Poppetjes: allemaal overeind -->\n        <text x=\"585\" y=\"50\" font-family=\"var(--font-body)\" font-size=\"9\" fill=\"#8A877F\" font-weight=\"500\"># ondernemers</text>\n        <text x=\"600\" y=\"68\" font-size=\"16\">👤</text>\n        <text x=\"625\" y=\"68\" font-size=\"16\">👤</text>\n        <text x=\"650\" y=\"68\" font-size=\"16\">👤</text>\n\n        <!-- Kostenkolom — lager door low-input -->\n        <rect x=\"575\" y=\"110\" width=\"52\" height=\"150\" rx=\"2\" fill=\"#3ea635\" opacity=\"0.08\" stroke=\"#3ea635\" stroke-width=\"1.5\"></rect>\n        <text x=\"601\" y=\"195\" text-anchor=\"middle\" font-family=\"var(--font-body)\" font-size=\"11\" fill=\"#3ea635\" font-weight=\"600\" transform=\"rotate(-90,601,195)\">KOSTEN</text>\n        <!-- Stippellijn waar kosten in akte I waren -->\n        <line x1=\"573\" y1=\"90\" x2=\"629\" y2=\"90\" stroke=\"rgba(0,0,0,.1)\" stroke-width=\"1\" stroke-dasharray=\"3 3\"></line>\n        <text x=\"555\" y=\"100\" font-family=\"var(--font-body)\" font-size=\"8\" fill=\"#3ea635\" text-anchor=\"end\">low input:</text>\n        <text x=\"555\" y=\"110\" font-family=\"var(--font-body)\" font-size=\"8\" fill=\"#3ea635\" text-anchor=\"end\">kosten ↓</text>\n\n        <!-- Opbrengstkolom GESTAPELD -->\n        <!-- Melk (kleiner) -->\n        <rect x=\"637\" y=\"155\" width=\"52\" height=\"105\" rx=\"0 0 2 2\" fill=\"#C49A1E\" opacity=\"0.12\" stroke=\"#C49A1E\" stroke-width=\"1.5\"></rect>\n        <text x=\"663\" y=\"215\" text-anchor=\"middle\" font-family=\"var(--font-body)\" font-size=\"10\" fill=\"#C49A1E\" font-weight=\"500\" transform=\"rotate(-90,663,215)\">melk</text>\n\n        <!-- Maatschappelijke diensten (bovenop) -->\n        <rect x=\"637\" y=\"55\" width=\"52\" height=\"100\" rx=\"2 2 0 0\" fill=\"#3ea635\" opacity=\"0.15\" stroke=\"#3ea635\" stroke-width=\"1.5\"></rect>\n        <text x=\"663\" y=\"105\" text-anchor=\"middle\" font-family=\"var(--font-body)\" font-size=\"10\" fill=\"#3ea635\" font-weight=\"600\" transform=\"rotate(-90,663,105)\">maatschappelijke diensten</text>\n\n        <!-- Scheidslijn melk/diensten -->\n        <line x1=\"637\" y1=\"155\" x2=\"689\" y2=\"155\" stroke=\"#3ea635\" stroke-width=\"1\" stroke-dasharray=\"2 2\"></line>\n\n        <!-- Winst terug -->\n        <line x1=\"573\" y1=\"110\" x2=\"691\" y2=\"110\" stroke=\"rgba(0,0,0,.12)\" stroke-width=\"1\" stroke-dasharray=\"3 2\"></line>\n        <rect x=\"637\" y=\"55\" width=\"52\" height=\"55\" rx=\"2 2 0 0\" fill=\"#3ea635\" opacity=\"0.05\"></rect>\n        <text x=\"698\" y=\"63\" font-family=\"var(--font-body)\" font-size=\"10\" fill=\"#3ea635\" font-weight=\"600\">winst terug</text>\n        <text x=\"698\" y=\"76\" font-family=\"var(--font-body)\" font-size=\"8\" fill=\"#3ea635\">uit diensten +</text>\n        <text x=\"698\" y=\"87\" font-family=\"var(--font-body)\" font-size=\"8\" fill=\"#3ea635\">lagere kosten</text>\n\n        <!-- Baseline -->\n        <line x1=\"565\" y1=\"260\" x2=\"705\" y2=\"260\" stroke=\"rgba(0,0,0,.2)\" stroke-width=\"1.5\"></line>\n\n        <!-- Verborgen kosten: ROOD gearceerd, alleen onder kostenkolom, HEEL DUN -->\n        <rect x=\"575\" y=\"265\" width=\"52\" height=\"10\" rx=\"2\" fill=\"url(#diagRed)\" stroke=\"#B5442E\" stroke-width=\"0.5\" opacity=\"0.5\"></rect>\n        <text x=\"601\" y=\"288\" text-anchor=\"middle\" font-family=\"var(--font-body)\" font-size=\"7\" fill=\"#B5442E\">≈ 0</text>\n\n        <!-- Nieuwe waarden: GROEN gearceerd, onder opbrengstenkolom -->\n        <rect x=\"637\" y=\"265\" width=\"52\" height=\"40\" rx=\"2\" fill=\"url(#diagGreen)\" stroke=\"#3ea635\" stroke-width=\"1.5\"></rect>\n        <text x=\"663\" y=\"282\" text-anchor=\"middle\" font-family=\"var(--font-body)\" font-size=\"8\" fill=\"#3ea635\" font-weight=\"500\">nieuwe</text>\n        <text x=\"663\" y=\"292\" text-anchor=\"middle\" font-family=\"var(--font-body)\" font-size=\"8\" fill=\"#3ea635\" font-weight=\"500\">waarden</text>\n        <text x=\"698\" y=\"278\" font-family=\"var(--font-body)\" font-size=\"7\" fill=\"#3ea635\">overheid investeert</text>\n        <text x=\"698\" y=\"288\" font-family=\"var(--font-body)\" font-size=\"7\" fill=\"#3ea635\">mét rendement</text>\n\n        <!-- Ondertitels -->\n        <text x=\"130\" y=\"345\" text-anchor=\"middle\" font-family=\"var(--font-body)\" font-size=\"9\" fill=\"#B5442E\" font-weight=\"500\">Dunne marge, grote verborgen kosten,</text>\n        <text x=\"130\" y=\"357\" text-anchor=\"middle\" font-family=\"var(--font-body)\" font-size=\"9\" fill=\"#B5442E\">ondernemers vallen af</text>\n\n        <text x=\"390\" y=\"345\" text-anchor=\"middle\" font-family=\"var(--font-body)\" font-size=\"9\" fill=\"#C49A1E\" font-weight=\"500\">Geen marge, kosten stijgen,</text>\n        <text x=\"390\" y=\"357\" text-anchor=\"middle\" font-family=\"var(--font-body)\" font-size=\"9\" fill=\"#C49A1E\">verborgen kosten krimpen</text>\n\n        <text x=\"645\" y=\"345\" text-anchor=\"middle\" font-family=\"var(--font-body)\" font-size=\"9\" fill=\"#3ea635\" font-weight=\"500\">Lagere kosten, winst uit diensten,</text>\n        <text x=\"645\" y=\"357\" text-anchor=\"middle\" font-family=\"var(--font-body)\" font-size=\"9\" fill=\"#3ea635\">verborgen kosten → nieuwe waarden</text>\n\n        <!-- Legenda -->\n        <rect x=\"55\" y=\"385\" width=\"12\" height=\"8\" rx=\"1\" fill=\"url(#diagRed)\" stroke=\"#B5442E\" stroke-width=\"0.5\"></rect>\n        <text x=\"72\" y=\"393\" font-family=\"var(--font-body)\" font-size=\"8\" fill=\"#8A877F\">verborgen kosten (overheid)</text>\n        <rect x=\"250\" y=\"385\" width=\"12\" height=\"8\" rx=\"1\" fill=\"url(#diagGreen)\" stroke=\"#3ea635\" stroke-width=\"0.5\"></rect>\n        <text x=\"267\" y=\"393\" font-family=\"var(--font-body)\" font-size=\"8\" fill=\"#8A877F\">nieuwe waarden (bewuste investering)</text>\n\n      </svg>\n      <p style=\"font-size:11px;color:var(--text3);margin-top:8px;text-align:center\">Per akte: kosten (links) naast opbrengsten (rechts). Boven de lijn: de ondernemer. Onder de lijn: de overheid. Rood gearceerd = verborgen kosten (krimpen per akte). Groen gearceerd = nieuwe waarden (bewuste investering mét rendement).</p>\n    </div>\n\n    <!-- INSTAPDREMPEL -->\n    <div style=\"background:var(--bg3);border:1px solid rgba(0,0,0,.06);border-radius:var(--radius-lg);padding:1.25rem;border-top:3px solid var(--blue);margin-top:12px\">\n      <div style=\"font-size:11px;text-transform:uppercase;letter-spacing:.06em;color:var(--text3);margin-bottom:10px;font-weight:500\">Instapdrempel, wie kan er eigenlijk meedoen?</div>\n      <div style=\"display:grid;grid-template-columns:repeat(3,1fr);gap:12px;font-size:12px;text-align:center\">\n        <div>\n          <div style=\"font-size:22px;color:var(--red);font-weight:700;line-height:1\">↑↑</div>\n          <div style=\"color:var(--text2);margin-top:4px;font-weight:500\">Akte I</div>\n          <div style=\"color:var(--text3);font-size:11px\">Grond duur, schaal vereist, alleen grote bedrijven overleven</div>\n        </div>\n        <div>\n          <div style=\"font-size:22px;color:var(--amber);font-weight:700;line-height:1\">↑↑</div>\n          <div style=\"color:var(--text2);margin-top:4px;font-weight:500\">Akte II</div>\n          <div style=\"color:var(--text3);font-size:11px\">Grond blijft duur, grondhonger van buiten het gebied drijft prijzen verder op.</div>\n        </div>\n        <div>\n          <div style=\"font-size:22px;color:var(--accent);font-weight:700;line-height:1\">↓✓</div>\n          <div style=\"color:var(--text2);margin-top:4px;font-weight:500\">Akte III</div>\n          <div style=\"color:var(--text3);font-size:11px\">Doelgebonden pacht + transitiesteun maken instap reëel</div>\n        </div>\n      </div>\n    </div>\n\n    <!-- BESCHRIJVENDE TEKST -->\n    <div style=\"margin-top:1.5rem\">\n      <h4>Hoe de kosten verschuiven</h4>\n\n      <p><strong>Het boereninkomen</strong> verschuift van karakter. In akte I is het puur marktinkomen, veel melk, dunne marge, en een deel van de bedrijven heeft eigenlijk al geen marge meer (ze redden het alleen omdat ze de grond in eigendom hebben). In akte II dalen de opbrengsten (minder koeien per hectare) terwijl de kosten stijgen (maatregelen, mestafvoer). De boer zoekt het in kostenbeperking: al die \"extraatjes\" — slootkantenbeheer, weidevogelbeheer — waar je een vergoeding voor krijgt maar die je feitelijk meer kosten dan ze opleveren, worden uitgeschraapt. In akte III worden precies die extraatjes vergoed als opgave-diensten. Het inkomen is kleiner uit melk, maar groter uit diensten, en de boer moet er winst op kunnen maken, geen gederfde-inkomstenvergoeding à 80%. Belangrijk: de kosten in akte III hoeven niet per se hoger te zijn. Een low-input bedrijfsvoering — minder kunstmest, minder krachtvoer, minder zware machines — kan juist lagere kosten opleveren. Biologische boeren bewijzen dat al. De toolbox verlaagt kosten én verhoogt opbrengsten.</p>\n\n      <p><strong>De overheidsinvestering</strong> verandert van labeling. In akte I is die klein: ANLb, vrijwillige pakketten. In akte II gaat er wél geld naar het gebied, maar het is \"klein bier\" (ANLb verhogingen, waterinfiltratiesubsidies) naast de echte post: uitkoopregelingen. Die kosten miljarden maar leveren geen rendement: de grond gaat naar grondbezitters van buiten het gebied, de opgaves worden niet gehaald. In akte III is het overheidsgeld serieus, maar het is investering, niet compensatie. De overheid betaalt voor geleverde diensten. En wat je bespaart op verborgen kosten (EU-boetes voor het niet halen van natuur- en waterrichtlijnen, infrastructuurschade door bodemdaling) financiert een deel van de investering.</p>\n\n      <p><strong>De verborgen kosten</strong> — rood gearceerd in het diagram hierboven; kosten die niet in marktprijzen zitten en door samenleving en toekomstige generaties worden gedragen — zijn in akte I en II groot en onzichtbaar: bodemdaling die wegen en funderingen beschadigt, stijgende waterschapslasten, EU-boetes, droogteschade. Niemand telt ze bij elkaar op. In akte II verschuiven ze deels (minder stikstof, minder CO₂) maar komen er andere bij (landschapsverlies, basiskwaliteit natuur achteruit). Pas in akte III nemen ze structureel af.</p>\n\n      <p><strong>De maatschappelijke verborgen waarden</strong> staan spiegelend naast de verborgen kosten — net zo onzichtbaar in de standaard rekensom, maar in tegenovergestelde richting. Dit zijn de prestaties die de familieondernemer levert die niet in het verdienmodel zitten en niet in een overheidsbegroting staan, maar die wegvallen zodra de ondernemer zelf wegvalt: het onderhoud van sloten en hekken, het beheren van perceelranden, het bewaken van vee, vroegtijdige signalering bij overstroming of dierziekte, en de bredere sociale aanwezigheid op het platteland — dorpsleven, vakkennis, sociaal netwerk, gemeenschappelijke noodbereidheid. Deze prestaties zijn niet <em>gratis</em>; ze zijn <strong>onbeprijsd</strong>. Het verschil is fundamenteel. Onbeprijsd betekent dat ze gaan ontbreken zodra het eigenaarschap verschuift naar partijen die niet de motivatie hebben om ze te leveren — beleggers, grote ondernemers die op afstand grond bezitten, partijen die alleen doen wat in het contract staat. Wat de familieondernemer leverde uit eigenaarschap is dan verdwenen, ofwel helemaal (verloedering), ofwel het moet worden ingekocht tegen marktprijs (vele malen duurder). Het is geen sentimenteel argument, het is een keiharde rekenkundige redenering: een familieondernemer die rond kan komen uit melk plus maatschappelijke diensten levert als bijproduct miljoenen uren onbetaald landbeheer per jaar in Nederland. Vervang de familieondernemer door een belegger en die uren moeten ergens vandaan komen — uit publiek geld of helemaal niet.</p>\n\n      <p>De rekening van het huidige systeem is daarmee dubbel scheef. Aan de kostenkant: onzichtbaar duur (verborgen kosten van bodemdaling, EU-boetes, infrastructuurschade). Aan de waardenkant: onzichtbaar productief (verborgen waarden van eigenaarschap, beheer, sociale infrastructuur). Het overheidsgeld dat in akte III als investering wordt uitgegeven, koopt niet alleen prestaties in — het houdt ook de drager overeind die deze tweede stroom van onbeprijsde prestaties blijft leveren. Dat is wat er verloren gaat zodra de drager wegvalt.</p>\n\n      <p><strong>De kern:</strong> het totale maatschappelijke kostenplaatje verandert niet dramatisch, maar de samenstelling wel. Het geld dat je als overheid nu uitgeeft aan uitkoop zonder rendement en het niet-halen van doelen, kun je ook besteden aan een zakelijke transactie met ondernemers die die doelen wél halen. Niet het geld is anders, de labeling is anders.</p>\n    </div>\n  </div>\n","werkstand":{"nummer":"8","ronde":"1","stand":"herzien; open punt in de correctielijst: tweede pijl voor de markt in het kernbeeld, beeldwerk"},"skelet":[{"nummer":"8","titel":"Wat er gebeurt met een verdienmodel eronder (akte III — het antwoord)","bron":"akte-3","stand":"ronde 1 · nu aan de beurt","deel":"Deel III — Hoe het kan lopen","kern":"Dezelfde doelen, maar de dienst wordt betaald in plaats van het verlies vergoed. Er komen twee geldstromen: de overheid die een dienst inkoopt en de markt die er zelf belang bij heeft. Dit is het antwoord van het document, en het is de enige akte waarin het vermogen uit hoofdstuk 5 overeind blijft.","secties":[{"kop":"8.1 De omslag: van vergoeding naar betaling","elementen":[{"t":"wat er eerst gebeurt: het grondbeleid stopt de grondhonger uit akte II","v":"tekst","h":"auteurs","n":""},{"t":"de omkering: betaald worden voor een geleverde dienst in plaats van gecompenseerd voor een verlies","v":"tekst","h":"auteurs","n":""},{"t":"het begint moeizaam: de eerste jaren zijn kwetsbaar, en na zeven tot tien jaar staat het bedrijfsmodel","v":"tekst","h":"auteurs","n":""},{"t":"drie tempo's, één transitie","v":"fiche","h":"auteurs","n":""}]},{"kop":"8.2 Twee geldstromen, niet één","elementen":[{"t":"de overheid als opdrachtgever én de markt als afnemer, in het kernbeeld zelf","v":"beeld + tekst","h":"nieuw","n":"toetsregel 26"},{"t":"water is het voorbeeld waar een afnemer met een eigen belang en een eigen begroting zit","v":"tekst","h":"nieuw","n":"besluit 18-8"},{"t":"ammoniakreductie als denkbare dienst","v":"fiche","h":"verhuisd","n":"uit de wachtkamer"}]},{"kop":"8.3 Wat dat betekent per opgave","elementen":[{"t":"wat je dan ziet veranderen: de uitstoot daalt aan beide kanten, en het inkomen herstelt naar een leefbaar familiebedrijf uit meerdere stromen","v":"tekst","h":"auteurs","n":""},{"t":"de dimensies bij akte III, en de ontwikkeling over de drie aktes","v":"beeld","h":"auteurs","n":""},{"t":"waarom de verbetering standhoudt: in akte II keerde de beweging omdat de rentmeesters verdwenen, hier blijven zij","v":"tekst","h":"auteurs","n":""}]},{"kop":"8.4 De motor","elementen":[{"t":"de motor draait op de juiste brandstof: de opgaven zijn geen kostenpost maar het product","v":"tekst","h":"auteurs","n":"vaste kop, elke akte heeft deze alinea"},{"t":"de ondernemer wordt bréder ondernemer, geen andere ondernemer","v":"tekst","h":"auteurs","n":"correctie Henk"},{"t":"het doel is een gebied vol met dit soort ondernemers, niet één pionier die het lukt ondanks het systeem","v":"tekst","h":"auteurs","n":""},{"t":"conflicten worden zichtbaar: niet alle bouwstenen passen bij elkaar, en kiezen is het werk van de ondernemer","v":"tekst","h":"auteurs","n":""},{"t":"akte III is geen morele maar een ontwerpkeuze: een systeem dat van variatie profiteert in plaats van eraan onderdoor te gaan","v":"tekst","h":"verhuisd","n":"uit hoofdstuk 5, geparkeerd 19-8"}]}],"noot":""}],"deel":"Deel III — Hoe het kan lopen"},{"id":"d-concept","letter":"D","titel":"De veenweideboer","intro":"De veenweideboer is een nieuwe typologie: niet een reguliere melkveehouder met beperkingen, maar een ander type ondernemer met een ander kader én andere mogelijkheden. Het is niet strenger én slechter, het is anders én beter.","html":"\n<h2>D — De veenweideboer</h2>\n\n<p>De veenweideboer is een nieuwe typologie: niet een reguliere melkveehouder met beperkingen, maar een ander type ondernemer met een ander kader én andere mogelijkheden. Het is niet strenger én slechter, het is anders én beter.</p>\n\n<div style=\"background:var(--bg2);border-radius:var(--radius);padding:1rem 1.25rem;margin:1rem 0 1.25rem;font-size:13.5px;line-height:1.6;border-left:4px solid var(--accent)\">\n  <strong style=\"display:block;margin-bottom:4px;color:var(--accent2)\">Het sturingsprincipe: hardere uitkomsten, vrijere middelen<span class=\"fiche-wrap\"><button class=\"fiche-btn\" type=\"button\" aria-label=\"Toelichting tonen\">ⓘ</button><span class=\"fiche-popup\"><span class=\"fiche-label\">Toelichting</span><span class=\"fiche-source\">Sturingsinstrumenten moeten samen in elk geval aan drie uitgangspunten voldoen (Boersema &amp; Reijnders, 2009): geen afwenteling naar later en elders; de voordelen van wenselijk gedrag zijn voor het individu groter dan de nadelen; en die voordelen komen niet terecht bij wie niets doet.</span></span></span></strong>\n  Het overheidskader hieronder draait op één principe: <em>de overheid is strakker op wat geleverd moet worden, ruimer op hoe dat gebeurt.</em> Dat is precies de spiegel van het huidige beleid, dat vaak het omgekeerde doet — vrije uitkomsten (\"opgaves halen, ergens, ooit\") en strikte middelen (welke teelten, welke gebouwen, welke functies wel of niet mogen). Doelsturing op uitkomst, ondernemersvrijheid op middelen: dat is wat de zes lagen hieronder samen vormgeven.\n</div>\n\n<div style=\"display:grid;grid-template-columns:1fr 1fr;gap:16px;margin:1.25rem 0\">\n\n    <!-- LINKERKOLOM: WAT DE OVERHEID DOET -->\n    <div style=\"background:var(--bg3);border:1px solid rgba(0,0,0,.06);border-radius:var(--radius-lg);padding:1.5rem;border-top:3px solid var(--blue)\">\n      <div style=\"font-size:11px;text-transform:uppercase;letter-spacing:.08em;color:var(--blue);font-weight:600;margin-bottom:14px\">Het kader en de ruimte — wat de overheid doet</div>\n\n      <div style=\"margin-bottom:14px\">\n        <div style=\"font-weight:600;color:var(--text);font-size:13px;margin-bottom:3px\">① Doelen — een ladder, geen keuze</div>\n        <div style=\"color:var(--text2);font-size:12.5px;line-height:1.5\">Per context en per bedrijf, in opgaande ladder. Eerst op bedrijfsniveau — een vieze sloot mag bestaan zolang het water het erf én de percelen schoon verlaat (nitraat, fosfaat); percelen met meer uitstoot mogen bestaan zolang elders genoeg koolstof wordt vastgehouden. Daarna op polderniveau — wat de ene boer niet haalt, kan een ander binnen hetzelfde peilvak compenseren tegen vergoeding. Daarna op collectiefniveau, waar de totale opgave wordt afgerekend. Bedrijfsniveau alleen werkt niet: ongelijke percelen en veendiktes maken individuele afrekening met één generieke norm onuitvoerbaar en onevenredig hard.</div>\n      </div>\n\n      <div style=\"margin-bottom:14px\">\n        <div style=\"font-weight:600;color:var(--text);font-size:13px;margin-bottom:3px\">② Maatregelen</div>\n        <div style=\"color:var(--text2);font-size:12.5px;line-height:1.5\">Vernatting tot 30 cm onder het maaiveld in het midden van het perceel. Verplicht en niet-onderhandelbaar, dezelfde als in akte II — maar het peil is het middel, niet het doel: gedifferentieerd per peilvak, met het hoogste peil in de meest afbraakgevoelige gebieden en rust waar het al nat ligt.</div>\n      </div>\n\n      <div style=\"margin-bottom:14px\">\n        <div style=\"font-weight:600;color:var(--text);font-size:13px;margin-bottom:3px\">③ Juridische ruimte</div>\n        <div style=\"color:var(--text2);font-size:12.5px;line-height:1.5\">Natte teelt op landbouwgrond. Wilgen planten. Paludicultuur. Wonen en recreatie bij de boer. Wateropslag als bedrijfsactiviteit — zaken die nu nog omslachtig vergunningplichtig zijn omdat een veenweidecategorie in het omgevingsplan ontbreekt.</div>\n      </div>\n\n      <div style=\"margin-bottom:14px\">\n        <div style=\"font-weight:600;color:var(--text);font-size:13px;margin-bottom:3px\">④ Maatschappelijke opdrachten</div>\n        <div style=\"color:var(--text2);font-size:12.5px;line-height:1.5\">De overheid schrijft diensten uit als opdracht: schoon water, wateropslag, vastgehouden koolstof, koolstofopslag, weidevogels, biodiversiteit, landschapskwaliteit. Langjarige prestatiecontracten. De boer is leverancier van publieke waarde, betaald door de overheid. Geen subsidie maar een zakelijke transactie. Hier begint het verdienmodel.</div>\n      </div>\n\n      <div style=\"margin-bottom:14px\">\n        <div style=\"font-weight:600;color:var(--text);font-size:13px;margin-bottom:3px\">⑤ Coördinatie</div>\n        <div style=\"color:var(--text2);font-size:12.5px;line-height:1.5\">Op twee niveaus. Gebiedsregie via gebiedsorganisaties: boer-boer coördinatie op polderniveau: waterpeilen afstemmen, mozaïekbeheer plannen, monitoring organiseren. Eén boer kan niet alleen het waterpeil veranderen. En overheidscoördinatie: rijk, provincie, waterschap en gemeente op één lijn, met één gebiedscontract in plaats van vier losse beleidsdossiers. Meer dan faciliteren, minder dan regie, maar wel degelijk sturen op kaders en samenhang.</div>\n      </div>\n\n      <div>\n        <div style=\"font-weight:600;color:var(--text);font-size:13px;margin-bottom:3px\">⑥ Vangnet</div>\n        <div style=\"color:var(--text2);font-size:12.5px;line-height:1.5\">Het vangnet. Gebiedsspecifieke basisvergoeding (bergboerenlogica). Actief grondbeleid en landafwaardering. Markttoegang via veenweidezuivelketen en koolstof-/biodiversiteitsmarkt. Transitiesteun als overbrugging. In akte II zijn pijlers onmisbaar omdat er voor de boer geen automatisch recht op vergoeding bestaat — alleen privaatrechtelijke schadevergoeding bij onrechtmatig handelen, of vrijwillige uitkoop. In akte III worden ze steeds minder nodig naarmate de maatschappelijke opdrachten en prestatiecontracten structureel lopen.</div>\n      </div>\n    </div>\n\n    <!-- RECHTERKOLOM: WAT DE ONDERNEMER DOET -->\n    <div style=\"background:var(--bg3);border:1px solid rgba(0,0,0,.06);border-radius:var(--radius-lg);padding:1.5rem;border-top:3px solid var(--accent)\">\n      <div style=\"font-size:11px;text-transform:uppercase;letter-spacing:.08em;color:var(--accent2);font-weight:600;margin-bottom:14px\">De vrijheid — wat de ondernemer doet</div>\n\n      <div style=\"margin-bottom:14px\">\n        <div style=\"font-weight:600;color:var(--text);font-size:13px;margin-bottom:3px\">Vee houden</div>\n        <div style=\"color:var(--text2);font-size:12.5px;line-height:1.5\">Wel degelijk nog koeien: lagere veedichtheid, met weidegang. De melk kan gewoon naar Campina. Sterker: voorheen dreigde de zuivelsector veenweidemelk af te stoten vanwege de hoge CO₂-voetafdruk. Maar bij de veenweideboer kantelt de bódembalans van bron naar opslag: vermeden veenoxidatie en — via actieve veenaanmaak — koolstofvastlegging worden betaalde diensten, via maatschappelijke opdrachten (prestatiecontract overheid) of de koolstofmarkt (CO₂-credits). Het bedrijf als geheel wordt daarmee fors klimaatlichter — vee blijft methaan geven, maar de voetafdruk daalt aantoonbaar. Daarmee wordt deze melk juist gewild: van risicoproduct naar koploper. De vergoeding voor diensten is geen premium op de melkprijs, maar een directe betaling van de opdrachtgever aan de boer voor geleverde maatschappelijke diensten.</div>\n      </div>\n\n      <div style=\"margin-bottom:14px\">\n        <div style=\"font-weight:600;color:var(--text);font-size:13px;margin-bottom:3px\">Bedrijf optimaliseren</div>\n        <div style=\"color:var(--text2);font-size:12.5px;line-height:1.5\">Een toolbox specifiek voor veenweideboeren: slootmaaibeheer, greppelinfiltratie, dynamisch peilbeheer, kruidenrijk grasland, koe-kalf-kudde, weidevogelbeheer, natuurvriendelijke oevers — geen nieuw inkomen, wel lagere kosten en bijdrage aan de doelen.</div>\n      </div>\n\n      <div>\n        <div style=\"font-weight:600;color:var(--text);font-size:13px;margin-bottom:3px\">Nieuwe inkomstenstromen openen</div>\n        <div style=\"color:var(--text2);font-size:12.5px;line-height:1.5\">Nieuwe inkomstenstromen openen: koolstofopslag, wateropslag als betaalde dienst, biodiversiteitsdiensten, natuur als dienst, paludicultuur, zorgboerderij, premium voedsel. De vergoeding loopt via overheidsopdrachten, marktopdrachten of de creditmarkt. Dit is het verdienmodel dat het verschil maakt met akte II.</div>\n      </div>\n\n      <div style=\"background:var(--accent-light);border-radius:var(--radius);padding:.75rem 1rem;margin-top:14px;font-size:12px;line-height:1.5;color:var(--accent2)\">\n        <strong>De toolbox is de vrijheid.</strong> De overheid bepaalt welke maatschappelijke opgaves geleverd moeten worden. De boer bepaalt wat, hoe en hoeveel: welke combinatie van producten en diensten, met welke middelen, in welke verhouding. Elke boer combineert anders, afhankelijk van context, grond, talent en smaak.\n      </div>\n    </div>\n  </div>\n\n<h3>Veenweideboer is een schaal, geen categorie</h3>\n\n<p>Iedereen die op veen boert is veenweideboer. Dat is geen concessie maar het uitgangspunt: dit document maakt van de term geen keurmerk waar je in of buiten valt, maar een schaal waarop de ondernemer zelf een plek kiest. En die schaal begint niet bij nul. Vrijwel elk bedrijf op veen levert nu al beheer waarvoor niemand betaalt: sloten schoonhouden, het landschap onderhouden, een perceel dat later gemaaid wordt voor de vogels. Het verschil tussen de posities is dus niet óf er iets geleverd wordt, maar hoeveel, en of er een prijs op staat.</p>\n\n<div style=\"display:grid;grid-template-columns:repeat(4,1fr);gap:12px;margin:1.25rem 0 .5rem\">\n    <div class=\"decision-card\"><div class=\"label\">waar vrijwel elk bedrijf staat</div><div class=\"title\">Melk, met onbeprijsd beheer</div><div class=\"why\">Het bedrijf leeft van melk. Het beheer dat erbij hoort levert niets op, of niet meer dan een vergoeding van de kosten.</div></div>\n    <div class=\"decision-card\"><div class=\"label\">een eerste stap</div><div class=\"title\">Melk, met een betaalde dienst erbij</div><div class=\"why\">Een enkel perceel levert iets waarvoor een contract bestaat: weidevogelbeheer, water bergen op de laagste hoek. Melk blijft de basis.</div></div>\n    <div class=\"decision-card\"><div class=\"label\">het model van dit hoofdstuk</div><div class=\"title\">Melk als één van meerdere producten</div><div class=\"why\">Een lagere veedichtheid, en daarnaast water, koolstof, biodiversiteit of landschap als betaald product.</div></div>\n    <div class=\"decision-card\"><div class=\"label\">het uiterste eind</div><div class=\"title\">Geen koeien, diensten als heel product</div><div class=\"why\">Waar vee niet meer kan, wordt de dienst het bedrijf: natte teelt, natuurbeheer, waterberging. Zie de 10.000 hectare in hoofdstuk 1.</div></div>\n  </div>\n\n<div style=\"display:flex;align-items:center;gap:12px;margin:0 0 1.5rem;font-family:var(--font-sans);font-size:11px;text-transform:uppercase;letter-spacing:.06em;color:var(--text3)\">\n    <span>voedsel</span>\n    <div style=\"flex:1;height:4px;border-radius:2px;background:linear-gradient(90deg,var(--accent),var(--blue))\"></div>\n    <span>maatschappelijke diensten</span>\n  </div>\n\n<p>Waaróm een ondernemer schuift, verschilt. De een ziet een kans en pakt die. De ander heeft geen keuze meer omdat de plek het dicteert, en zet die dwang om in iets dat wél iets oplevert. Dat zijn twee schalen die niet samenvallen: hoe hard de plek drukt, en hoeveel de ondernemer ermee wil. Waar zij samenvallen is er geen keuze meer. Waar zij uiteenlopen ligt een kans zonder dwang, en dat is wat dit document aanbiedt.</p>\n\n<p>Daarom hoeft de grens ook niet op de kaart getrokken te worden. De betaling volgt de dienst en niet de naam: wie levert, wordt betaald, en wie niets levert, hoeft niets.</p>\n\n<h3>Waarom veenweideboeren, en niet veenweidelandbouw?</h3>\n\n<p>De naam is een bewuste keuze, en geen kosmetische. De term bestaat bovendien al — iedereen die op veen boert noemt zich veenweideboer. Dit document laadt hem bewust opnieuw: van geografische aanduiding naar bedrijfsmodel. <em>Veenweidelandbouw</em> suggereert een afgeleide van het bestaande landbouwsysteem, een beetje vergroend, met wat extra beperkingen. Maar zodra je het landbouw noemt, sluit de juridische definitie de helft van de oplossing buiten. Wilgen planten, wateropslag aanbieden, natuur beheren als dienst, recreatieve voorzieningen, wonen bij de boer, zorg op de boerderij: dat valt buiten het GLB-begrip 'landbouw' en buiten de landbouwbestemming in het omgevingsplan. Juist de activiteiten die het meest bijdragen aan de opgaves worden door die definitie buitengesloten. Dat is geen filosofische voorkeur, het is een juridische blokkade.</p>\n\n<p><em>Veenweideboeren</em> is breder. Het gaat over de ondernemer die op veen woont en werkt, en die vanuit die positie een breed palet aan activiteiten kan ontplooien: melk, vlees, natte teelt, waterberging, natuur- en landschapsbeheer, recreatie, zorg. De ondernemer staat centraal, niet de productiemethode.</p>\n\n<p>De kern van het probleem zit in hoe we het veenweidebedrijf definiëren. Zolang het formeel wordt gezien als een regulier melkveebedrijf met extra beperkingen, blijft één maatstaf dominant: <strong>maximale melkproductie per hectare</strong>. Binnen dat kader is de boer automatisch in het defensief. De boer wordt beoordeeld op wat er níét gehaald wordt en gezien als iemand die, ondanks alle noodzakelijke beperkingen, toch probeert te blijven produceren. Daarmee wordt de boer impliciet onderdeel van het probleem.</p>\n\n<p>Maar wordt het uitgangspunt veranderd, dan verandert ook de uitkomst. Als het veenweidebedrijf wordt erkend als een eigen categorie — met een andere economische logica, passende verdienmodellen en bijbehorende randvoorwaarden — verschuift de rol van de boer fundamenteel. Dan draait het niet langer om het maximaliseren van liters, maar om het optimaal beheren van een kwetsbaar landschap, het vastleggen van koolstof, het behouden van biodiversiteit en het slim combineren van functies. In zo'n systeem wordt ondernemerschap geen obstakel, maar juist de motor van verandering: de boer is dan niet iemand die tegen de grenzen aanloopt, maar iemand die binnen nieuwe spelregels waarde creëert, ecologisch én economisch. Niet langer veroorzaker van het probleem, maar cruciale partner in de oplossing.</p>\n\n<h3>Hoe we deze categorie precies bedoelen — twee terminologie-aanscherpingen</h3>\n\n<div style=\"background:var(--bg3);border:1px solid rgba(0,0,0,.06);border-radius:var(--radius-lg);padding:1.25rem 1.5rem;margin:1rem 0 1.5rem\">\n    <div style=\"font-size:11px;text-transform:uppercase;letter-spacing:.08em;color:var(--accent2);font-weight:600;margin-bottom:10px\">Niet extensief, maar meervoudig intensief</div>\n    <p style=\"font-size:13.5px;line-height:1.65;margin:0\">Het Rijksbeleid spreekt van \"extensieve melkveehouderij\". Die term klopt op één dimensie: minder koeien per hectare. Maar op alle andere dimensies is wat dit document beschrijft juist <em>intensief</em>. Dezelfde hectare doet tegelijk veeteelt, waterberging, koolstofopslag, biodiversiteit, recreatie, eventueel wonen en zorg. Dat is meervoudig en gelijktijdig ruimtegebruik. In een land met de ruimteschaarste uit de Nota Ruimte is dat het tegendeel van extensief — het is de meest intensieve manier om met grond om te gaan die er bestaat. Een datacenter doet één ding. Een woonwijk doet één ding. De veenweideboer in akte III doet zes of zeven dingen tegelijk. Daarom: <strong>extensief in veeteelt, intensief in landgebruik</strong>. Of in één begrip: <em>meervoudig intensief ruimtegebruik</em>.</p>\n  </div>\n\n<div style=\"background:var(--bg3);border:1px solid rgba(0,0,0,.06);border-radius:var(--radius-lg);padding:1.25rem 1.5rem;margin:1rem 0 1.5rem\">\n    <div style=\"font-size:11px;text-transform:uppercase;letter-spacing:.08em;color:var(--accent2);font-weight:600;margin-bottom:10px\">Niet \"natuurinclusief\", maar twee verschillende dingen</div>\n    <p style=\"font-size:13.5px;line-height:1.65;margin-bottom:.75rem\">Het Rijksbeleid spreekt van \"natuurinclusieve melkveehouderij\". Die term verbergt twee fundamenteel verschillende fenomenen die in dit verhaal helder uit elkaar moeten worden gehouden.</p>\n    <p style=\"font-size:13.5px;line-height:1.65;margin-bottom:.5rem\"><strong>Basiskwaliteit natuur</strong> — een concept dat onder andere door Naturalis is uitgewerkt — beschrijft een ondergrens voor biodiversiteit en kwaliteit van leven in het hele platteland, niet beperkt tot Natura 2000-gebieden. Het gaat over levende bodem, weidevogels, insecten, ecosystemische gezondheid in het landschap als geheel. Belangrijk: basiskwaliteit natuur betekent <em>niet</em> dat het landschap moet blijven zoals het nu is. Het is geen conservatie-eis. Het beschrijft een functionele ondergrens die ook gehaald kan worden in een veranderend landschap — met wilgen, met bossages, met andere structuren — zolang de basisvoorwaarden voor biodiversiteit en bodemleven overeind blijven.</p>\n    <p style=\"font-size:13.5px;line-height:1.65;margin:0\"><strong>Nature-based landbouw</strong> is iets fundamenteel anders. Hier zijn natuurlijke processen geen doel maar productiemiddel. Een helofytenfilter is geen stukje natuur dat erbij staat; het is een waterzuiveringsinstallatie die toevallig met planten werkt. Bodemleven dat bemesting overneemt is geen ecosysteem-bonus maar een teelttechniek. In deze tak is natuur <em>als-machine</em>: de techniek waarmee de maatschappelijke dienst wordt geleverd. Beide zijn legitiem en beide horen in het verhaal thuis, maar ze vragen verschillend beleidsinstrumentarium — basiskwaliteit natuur vraagt om kaders en monitoring, nature-based landbouw vraagt om markttoegang, contracten en regulering van geleverde diensten. Door beide onder \"natuurinclusief\" te plaatsen, blokkeren ze elkaar in beleidsdiscussies.</p>\n  </div>\n","werkstand":{"nummer":"9","ronde":"3","stand":"bestuursversie, met één nieuwe sectie vooraan: \"veenweideboer is een schaal, geen categorie\" (19-8)"},"skelet":[{"nummer":"9","titel":"Het bedrijfsmodel Veenweideboeren (D — De veenweideboer)","bron":"d-concept","stand":"ronde 3","deel":"Deel IV — Veenweideboeren","kern":"Dit is het bedrijfsmodel Veenweideboeren: een bedrijf dat voedsel blijft leveren én betaald wordt voor water, koolstof, landschap en biodiversiteit, met minder koeien per hectare. Eerst wat de naam betekent: veenweideboer is geen categorie maar een schaal, en iedereen die op veen boert staat erop. Daarna wie de dragende groep is, en waarom de naam over de ondernemer gaat en niet over de landbouwmethode.","secties":[{"kop":"9.1 Wat het bedrijfsmodel is","elementen":[{"t":"geen melkveehouder met beperkingen, maar een bedrijf dat voedsel levert én betaald wordt voor wat het aan de samenleving levert","v":"tekst","h":"auteurs","n":""},{"t":"drie bronnen van inkomen: vee houden met een lagere veedichtheid, het bedrijf optimaliseren, en nieuwe inkomstenstromen openen","v":"tekst","h":"auteurs","n":""}]},{"kop":"9.2 Veenweideboer is een schaal, geen categorie","elementen":[{"t":"**de schaal begint niet bij nul**, en dat is het punt: vrijwel elk bedrijf op veen levert al beheer waarvoor niemand betaalt. De vier posities van melk-met-onbeprijsd-beheer tot diensten-als-heel-product","v":"kaarten","h":"nieuw","n":"decision-card, vier gelijkvormige blokken met een as eronder"},{"t":"**twee schalen die niet samenvallen:** de plek dwingt, de ondernemer kiest. Waar ze samenvallen is er geen keuze meer; waar ze uiteenlopen is er een kans zonder dwang. Gedwongen omstandigheden zijn om te zetten in een kans, en dat is wat dit document aanbiedt","v":"tekst","h":"nieuw","n":""},{"t":"**de betaling volgt de dienst, niet de naam.** Daarom hoeft de grens niet op de kaart getrokken te worden: dat is breed kader, smal geld, toegepast op de identiteit","v":"tekst","h":"nieuw","n":"één regel, en het antwoord op de begrotingsvraag"}]},{"kop":"9.3 Wie de dragende groep is","elementen":[{"t":"het familiebedrijf van 40 tot 80 hectare met 80 tot 130 koeien, de middengroep uit hoofdstuk 3","v":"tabel","h":"auteurs","n":""},{"t":"de ondernemer die op veen woont en werkt, en die dit zelf wil","v":"tekst","h":"auteurs","n":""}]},{"kop":"9.4 Waarom veenweideboeren en niet veenweidelandbouw","elementen":[{"t":"de ondernemer staat centraal, niet de productiemethode","v":"tekst","h":"auteurs","n":""},{"t":"de term bestaat al en wordt hier opnieuw geladen: van geografische aanduiding naar bedrijfsmodel","v":"tekst","h":"auteurs","n":"— staat er al in de bestuursversie en is de opmaat naar 9.2"},{"t":"verander het uitgangspunt en de uitkomst verandert","v":"tekst","h":"auteurs","n":""}]},{"kop":"9.5 Twee aanscherpingen","elementen":[{"t":"niet extensief, maar meervoudig intensief","v":"tekst","h":"auteurs","n":""},{"t":"\"natuurinclusief\" is twee verschillende dingen","v":"tekst","h":"auteurs","n":""}]}],"noot":"De zes lagen verhuizen naar hoofdstuk 11; dit hoofdstuk houdt de typologie."}],"deel":"Deel IV — Veenweideboeren"},{"id":"f-ondernemer","letter":"F1","titel":"Ondernemerskant: de toolbox","intro":"De veenweideboer — de ondernemer van akte III — bepaalt zelf hóe de doelen gehaald worden. Dit zijn de bouwstenen: de toolbox waarmee de boer zijn doelen haalt. Niveau 1 optimaliseert het bestaande bedrijf. Niveau 2 opent nieuwe inkomstenstromen.","html":"\n<h2>F1 — Ondernemerskant: de toolbox</h2>\n\n<p>De veenweideboer — de ondernemer van akte III — bepaalt zelf hóe de doelen gehaald worden. Dit zijn de bouwstenen: de toolbox waarmee de boer zijn doelen haalt. Niveau 1 optimaliseert het bestaande bedrijf. Niveau 2 opent nieuwe inkomstenstromen.</p>\n\n<p>De toolbox past niet bij één type boer, hij geeft juist ruimte aan verschillende typen ondernemers in verschillende contexten.</p>\n\n<div style=\"background:var(--bg3);border:1px solid rgba(0,0,0,.06);border-radius:var(--radius-lg);padding:1.25rem 1.5rem;margin:1.5rem 0\">\n    <h4 style=\"margin:0 0 .75rem\">Wat de veenweideboer nodig heeft</h4>\n    <p style=\"font-size:13px;color:var(--text2);line-height:1.6;margin-bottom:.5rem\">Drie dingen, in deze volgorde:</p>\n    <p style=\"font-size:13px;color:var(--text2);line-height:1.6;margin-bottom:.25rem\"><strong>Houding</strong>. Houding verandert niet op commando. Niet elke veehouder is een ondernemer — veel boeren houden vooral van het veehouden zelf, en loslaten raakt aan rouw om een vak, een familielijn, een identiteit die generaties teruggaat. Voor wie de stap wél wil zetten: wat de houding kantelt is bewijs dat het bij collega's werkt, peers die eerder zijn, sociale erkenning vanuit gemeenschap en samenleving, een gezin dat meegaat. Die kanteling is voorwaarde voor de transitie, niet het gevolg ervan — en buitenstaanders schrijven haar niet voor, ze scheppen de condities.</p>\n    <p style=\"font-size:13px;color:var(--text2);line-height:1.6;margin-bottom:.25rem\"><strong>Kennis</strong>: handleidingen, expertise, rekenmodellen. De toolbox hieronder levert dit: per bouwsteen een concrete beschrijving van wat het is en hoe je het doet.</p>\n    <p style=\"font-size:13px;color:var(--text2);line-height:1.6;margin:0\"><strong>Vaardigheden</strong>: micro-watermanagement, ecologisch slootbeheer, natte teelt beheersen. Niet uit een boekje te leren, maar boer-boer, in de praktijk, via collectieven en studiegroepen.</p>\n  </div>\n\n<h3>Niveau 1 — Interne optimalisatie</h3>\n\n<p>Bouwstenen die binnen het bestaande bedrijf passen. Geen nieuw inkomen, wel lagere kosten, betere bedrijfsvoering en bijdrage aan de opgaves. De indeling volgt het werkdocument &lt;em&gt;VIC's Veenweideboeren toolbox&lt;/em&gt;: 35 bouwstenen in tien categorieën. Elke bouwsteen hieronder linkt naar de volledige uitwerking daar — wat het is, wat we weten, wanneer het toepasbaar is, met bronnen.</p>\n\n<h4>Waterbeheer op het bedrijf</h4>\n\n<div style=\"background:var(--bg2);border-left:3px solid var(--accent);border-radius:var(--radius);padding:1rem 1.25rem;margin:.75rem 0 1rem;font-size:13px;line-height:1.6\">\n    <strong style=\"display:block;margin-bottom:4px;font-size:13.5px\">Eerst de randvoorwaarde: zonder WIS werkt peilbeleid niet</strong>\n    De indringingsweerstand van veen is groot. Een grondwaterstand van -20 of -40 cm bereiken op een perceel zonder waterinfiltratiesysteem (WIS) is in praktijk onmogelijk. WIS is daarmee geen gewone bouwsteen tussen andere, maar een kritische randvoorwaarde: zonder WIS is doelsturing op grondwaterstand een papieren norm. De overheid die peilbeleid wil voeren, zal eerst WIS-aanleg moeten faciliteren en financieren. Daarbij hoort een contra-intuïtief inzicht dat het hele bedrijfsmodel pas mogelijk maakt: bij hoge grondwaterstand verslempt klei en glijdt, maar veen mét grasmat blijft koeien dragen. En omdat de grasproductie op deze gronden structureel lager ligt dan op conventionele landbouwgrond, zijn extra inkomstenstromen uit maatschappelijke diensten geen optie maar voorwaarde.\n  </div>\n\n<table class=\"bouwsteen-table\">\n    <thead><tr><th>Bouwsteen</th><th>Wat het doet</th></tr></thead>\n    <tbody>\n      <tr><td><strong><a href=\"VIC's%20Veenweideboeren%20toolbox.html#greppelinfiltratie\" style=\"color:var(--accent2);text-decoration:none\">Greppelinfiltratie</a></strong></td><td>Greppels in de zomer permanent watervoerend houden, zodat water het perceel intrekt</td></tr>\n      <tr><td><strong><a href=\"VIC's%20Veenweideboeren%20toolbox.html#dynamisch-peilbeheer\" style=\"color:var(--accent2);text-decoration:none\">Dynamisch peilbeheer</a></strong></td><td>Slootpeil actief sturen binnen boven- en ondergrens, op grondwaterstand, bodemvocht en weersverwachting</td></tr>\n      <tr><td><strong><a href=\"VIC's%20Veenweideboeren%20toolbox.html#pwis-en-awis\" style=\"color:var(--accent2);text-decoration:none\">PWIS en AWIS</a></strong></td><td>Kritische randvoorwaarde: gecontroleerd water infiltreren via drains — passief (PWIS) of actief gestuurd (AWIS)</td></tr>\n      <tr><td><strong><a href=\"VIC's%20Veenweideboeren%20toolbox.html#druppelinfiltratie-dis\" style=\"color:var(--accent2);text-decoration:none\">Druppelinfiltratie (DIS)</a></strong></td><td>Experimentele vernattingstechniek met druppelslangen; pilots lopen</td></tr>\n      <tr><td><strong><a href=\"VIC's%20Veenweideboeren%20toolbox.html#bevloeiing\" style=\"color:var(--accent2);text-decoration:none\">Bevloeiing</a></strong></td><td>Percelen bevloeien bij droogte; geen structurele bedrijfsmaatregel</td></tr>\n    </tbody>\n  </table>\n\n<h4>Sloot- en oeverbeheer</h4>\n\n<table class=\"bouwsteen-table\">\n    <thead><tr><th>Bouwsteen</th><th>Wat het doet</th></tr></thead>\n    <tbody>\n      <tr><td><strong><a href=\"VIC's%20Veenweideboeren%20toolbox.html#slootmaaibeheer\" style=\"color:var(--accent2);text-decoration:none\">Slootmaaibeheer</a></strong></td><td>Watervegetatie gefaseerd en gedeeltelijk maaien in plaats van alles in één keer</td></tr>\n      <tr><td><strong><a href=\"VIC's%20Veenweideboeren%20toolbox.html#baggerbeheer\" style=\"color:var(--accent2);text-decoration:none\">Baggerbeheer</a></strong></td><td>Slib verwijderen met aandacht voor timing, frequentie en licht materieel</td></tr>\n      <tr><td><strong><a href=\"VIC's%20Veenweideboeren%20toolbox.html#oeverbeheer\" style=\"color:var(--accent2);text-decoration:none\">Oeverbeheer</a></strong></td><td>Talud maaien, oever beschermen tegen vertrapping, inrichting van de overgangszone</td></tr>\n      <tr><td><strong><a href=\"VIC's%20Veenweideboeren%20toolbox.html#natuurvriendelijke-oevers\" style=\"color:var(--accent2);text-decoration:none\">Natuurvriendelijke oevers</a></strong></td><td>Flauwe taluds en oeverbegroeiing; op veen beperkter toepasbaar dan op klei of zand</td></tr>\n      <tr><td><strong><a href=\"VIC's%20Veenweideboeren%20toolbox.html#helofytenfilter\" style=\"color:var(--accent2);text-decoration:none\">Helofytenfilter</a></strong></td><td>Zuivering via rietachtige oeverplanten in een strook of filterbekken</td></tr>\n      <tr><td><strong><a href=\"VIC's%20Veenweideboeren%20toolbox.html#rivierkreeftenbestrijding\" style=\"color:var(--accent2);text-decoration:none\">Rivierkreeftenbestrijding</a></strong></td><td>Invasieve kreeften wegvangen die oevers en waterplanten vernielen</td></tr>\n    </tbody>\n  </table>\n\n<h4>Bodem en veen</h4>\n\n<table class=\"bouwsteen-table\">\n    <thead><tr><th>Bouwsteen</th><th>Wat het doet</th></tr></thead>\n    <tbody>\n      <tr><td><strong><a href=\"VIC's%20Veenweideboeren%20toolbox.html#bodembeheer-en-bewaking\" style=\"color:var(--accent2);text-decoration:none\">Bodembeheer en bewaking</a></strong></td><td>Zes bodemdimensies samenhangend beheren en monitoren, van organische stof tot beworteling</td></tr>\n      <tr><td><strong><a href=\"VIC's%20Veenweideboeren%20toolbox.html#draagkrachtbeheer\" style=\"color:var(--accent2);text-decoration:none\">Draagkrachtbeheer</a></strong></td><td>Sturen op het draagvermogen van natte veenbodem voor vee en machines</td></tr>\n      <tr><td><strong><a href=\"VIC's%20Veenweideboeren%20toolbox.html#bekalken\" style=\"color:var(--accent2);text-decoration:none\">Bekalken</a></strong></td><td>De pH verhogen op van nature verzurend veen</td></tr>\n    </tbody>\n  </table>\n\n<h4>Grasland</h4>\n\n<table class=\"bouwsteen-table\">\n    <thead><tr><th>Bouwsteen</th><th>Wat het doet</th></tr></thead>\n    <tbody>\n      <tr><td><strong><a href=\"VIC's%20Veenweideboeren%20toolbox.html#beweidingssystemen\" style=\"color:var(--accent2);text-decoration:none\">Beweidingssystemen</a></strong></td><td>Omweiden, stripgrazen of kurzrasen, afgestemd op draagkracht en grasaanbod</td></tr>\n      <tr><td><strong><a href=\"VIC's%20Veenweideboeren%20toolbox.html#grasrassen-en-doorzaaien\" style=\"color:var(--accent2);text-decoration:none\">Grasrassen en doorzaaien</a></strong></td><td>De zode versterken zonder scheuren; doorzaaien met passende rassen</td></tr>\n      <tr><td><strong><a href=\"VIC's%20Veenweideboeren%20toolbox.html#kruidenrijk-grasland\" style=\"color:var(--accent2);text-decoration:none\">Kruidenrijk grasland</a></strong></td><td>Klaver en productieve kruiden naast gras: biodiverser voer, minder kunstmest, minder lachgas</td></tr>\n      <tr><td><strong><a href=\"VIC's%20Veenweideboeren%20toolbox.html#maaibeheer\" style=\"color:var(--accent2);text-decoration:none\">Maaibeheer</a></strong></td><td>Timing, frequentie en hoogte van maaien, voor voederwinning én graslandkwaliteit</td></tr>\n      <tr><td><strong><a href=\"VIC's%20Veenweideboeren%20toolbox.html#rijpaden-en-licht-materieel\" style=\"color:var(--accent2);text-decoration:none\">Rijpaden en licht materieel</a></strong></td><td>Vaste rijpaden en lagere bodemdruk tegen verdichting en insporing</td></tr>\n    </tbody>\n  </table>\n\n<h4>Bemesting</h4>\n\n<table class=\"bouwsteen-table\">\n    <thead><tr><th>Bouwsteen</th><th>Wat het doet</th></tr></thead>\n    <tbody>\n      <tr><td><strong><a href=\"VIC's%20Veenweideboeren%20toolbox.html#stikstofbemesting\" style=\"color:var(--accent2);text-decoration:none\">Stikstofbemesting</a></strong></td><td>Bemesten op basis van wat de veenbodem zelf al levert (NLV)</td></tr>\n      <tr><td><strong><a href=\"VIC's%20Veenweideboeren%20toolbox.html#andere-mestsoorten-en-organische-stof\" style=\"color:var(--accent2);text-decoration:none\">(Andere) mestsoorten en organische stof</a></strong></td><td>Mestsoort kiezen op effect op bodemleven, organische stof en weidevogelhabitat</td></tr>\n      <tr><td><strong><a href=\"VIC's%20Veenweideboeren%20toolbox.html#fosfaatbeheer\" style=\"color:var(--accent2);text-decoration:none\">Fosfaatbeheer</a></strong></td><td>Fosfaattoestand per perceel sturen, voor nutriëntenbenutting én waterkwaliteit</td></tr>\n    </tbody>\n  </table>\n\n<h4>Gewas en voer</h4>\n\n<table class=\"bouwsteen-table\">\n    <thead><tr><th>Bouwsteen</th><th>Wat het doet</th></tr></thead>\n    <tbody>\n      <tr><td><strong><a href=\"VIC's%20Veenweideboeren%20toolbox.html#voederwinning-en-conservering\" style=\"color:var(--accent2);text-decoration:none\">Voederwinning en conservering</a></strong></td><td>Maaien, drogen en inkuilen afgestemd op later gemaaid en kruidenrijk gras</td></tr>\n      <tr><td><strong><a href=\"VIC's%20Veenweideboeren%20toolbox.html#eiwit-van-eigen-land\" style=\"color:var(--accent2);text-decoration:none\">Eiwit van eigen land</a></strong></td><td>Het aandeel eigen eiwit in het rantsoen verhogen, minder aangekocht krachtvoer</td></tr>\n      <tr><td><strong><a href=\"VIC's%20Veenweideboeren%20toolbox.html#rantsoen-op-maat\" style=\"color:var(--accent2);text-decoration:none\">Rantsoen op maat</a></strong></td><td>Voersamenstelling afgestemd op de kenmerken van het veenweidebedrijf</td></tr>\n    </tbody>\n  </table>\n\n<h4>Vee en dierenwelzijn</h4>\n\n<table class=\"bouwsteen-table\">\n    <thead><tr><th>Bouwsteen</th><th>Wat het doet</th></tr></thead>\n    <tbody>\n      <tr><td><strong><a href=\"VIC's%20Veenweideboeren%20toolbox.html#koe-kalf-kudde\" style=\"color:var(--accent2);text-decoration:none\">Koe-kalf-kudde</a></strong></td><td>Koe en kalf langer bij elkaar, natuurlijk kuddegedrag, dierenwelzijn</td></tr>\n      <tr><td><strong><a href=\"VIC's%20Veenweideboeren%20toolbox.html#dynamisch-draadloos-weiden\" style=\"color:var(--accent2);text-decoration:none\">Dynamisch draadloos weiden</a></strong></td><td>Koeien virtueel gestuurd zonder fysiek hek (virtual fencing)</td></tr>\n      <tr><td><strong><a href=\"VIC's%20Veenweideboeren%20toolbox.html#passende-koe\" style=\"color:var(--accent2);text-decoration:none\">Passende koe</a></strong></td><td>Raskeuze passend bij nat veen en lagere veedichtheid, in plaats van de standaard-Holstein</td></tr>\n    </tbody>\n  </table>\n\n<h4>Stal en emissies</h4>\n\n<table class=\"bouwsteen-table\">\n    <thead><tr><th>Bouwsteen</th><th>Wat het doet</th></tr></thead>\n    <tbody>\n      <tr><td><strong><a href=\"VIC's%20Veenweideboeren%20toolbox.html#ammoniakemissie\" style=\"color:var(--accent2);text-decoration:none\">Ammoniakemissie</a></strong></td><td>NH₃-uitstoot beperken in stal, mestopslag, toediening en beweiding</td></tr>\n    </tbody>\n  </table>\n\n<h4>Biodiversiteit en landschap</h4>\n\n<table class=\"bouwsteen-table\">\n    <thead><tr><th>Bouwsteen</th><th>Wat het doet</th></tr></thead>\n    <tbody>\n      <tr><td><strong><a href=\"VIC's%20Veenweideboeren%20toolbox.html#weidevogelbeheer\" style=\"color:var(--accent2);text-decoration:none\">Weidevogelbeheer</a></strong></td><td>Nestbescherming, uitgesteld maaien en plas-dras voor grutto, kievit en tureluur</td></tr>\n      <tr><td><strong><a href=\"VIC's%20Veenweideboeren%20toolbox.html#insectenbeheer\" style=\"color:var(--accent2);text-decoration:none\">Insectenbeheer</a></strong></td><td>Bloemrijke randen en habitats voor insecten, als voedselbasis voor weidevogels</td></tr>\n      <tr><td><strong><a href=\"VIC's%20Veenweideboeren%20toolbox.html#mozaïekbeheer\" style=\"color:var(--accent2);text-decoration:none\">Mozaïekbeheer</a></strong></td><td>Beheer per perceel variëren zodat gebiedsbreed een gevarieerd mozaïek ontstaat</td></tr>\n      <tr><td><strong><a href=\"VIC's%20Veenweideboeren%20toolbox.html#landschapselementen-onderhouden\" style=\"color:var(--accent2);text-decoration:none\">Landschapselementen onderhouden</a></strong></td><td>Geriefhoutbosjes, erfbeplanting en natte elementen onderhouden</td></tr>\n    </tbody>\n  </table>\n\n<h4>Mechanisatie en energie</h4>\n\n<table class=\"bouwsteen-table\">\n    <thead><tr><th>Bouwsteen</th><th>Wat het doet</th></tr></thead>\n    <tbody>\n      <tr><td><strong><a href=\"VIC's%20Veenweideboeren%20toolbox.html#elektrificatie\" style=\"color:var(--accent2);text-decoration:none\">Elektrificatie</a></strong></td><td>Diesel- en gasprocessen vervangen door elektrisch aangedreven equivalenten</td></tr>\n      <tr><td><strong><a href=\"VIC's%20Veenweideboeren%20toolbox.html#eigen-energieopwekking\" style=\"color:var(--accent2);text-decoration:none\">Eigen energieopwekking</a></strong></td><td>Zonnepanelen op stal- en erfdaken, eventueel een kleine windturbine</td></tr>\n    </tbody>\n  </table>\n\n<h3>Niveau 2 — Nieuwe inkomstenstromen</h3>\n\n<p>Grote bouwstenen die een nieuw verdienmodel opbouwen. Maatschappelijke diensten als business.</p>\n\n<table class=\"bouwsteen-table\">\n    <thead><tr><th>Bouwsteen</th><th>Inkomstenbron</th><th>Dimensies</th><th>JUMP-concept</th></tr></thead>\n    <tbody>\n      <tr><td><strong>Biodiversiteitsdienst</strong><span class=\"euro\">€</span></td><td>Overheidsopdracht, marktopdracht of biodiversiteitscredits</td><td><span class=\"tag-up\">↑ Natuur</span> <span class=\"tag-up\">↑ Ondernemerschap</span></td><td>4a — Functionele veen-biodiversiteit op maat</td></tr>\n      <tr><td><strong>Koolstofopslag</strong><span class=\"euro\">€</span></td><td>Overheidsopdracht, marktopdracht of CO₂-credits</td><td><span class=\"tag-up\">↑ Klimaat</span> <span class=\"tag-up\">↑ Ondernemerschap</span></td><td>5b — Opname en permanente opslag van CO₂ in en op veen</td></tr>\n      <tr><td><strong>CO₂-emissiebeperking</strong><span class=\"euro\">€</span></td><td>Overheidsopdracht, marktopdracht of CO₂-credits</td><td><span class=\"tag-up\">↑ Klimaat</span> <span class=\"tag-up\">↑ Ondernemerschap</span></td><td>5b — Opname en permanente opslag van CO₂ in en op veen</td></tr>\n      <tr><td><strong>Wateropslag als dienst</strong><span class=\"euro\">€</span></td><td>Betaald door waterschap</td><td><span class=\"tag-up\">↑ Water</span> <span class=\"tag-up\">↑ Voedselzekerheid</span> <span class=\"tag-up\">↑ Ondernemerschap</span></td><td>8a — Waterdiensten van veen</td></tr>\n      <tr><td><strong>Natuur als dienst</strong><span class=\"euro\">€</span></td><td>Overheidsopdracht of marktopdracht</td><td><span class=\"tag-up\">↑ Natuur</span> <span class=\"tag-up\">↑ Cultuur</span> <span class=\"tag-up\">↑ Ondernemerschap</span></td><td>4a + 4b, Functionele biodiversiteit + Natte-natuur experience</td></tr>\n      <tr><td><strong>Wonen bij de boer</strong><span class=\"euro\">€</span></td><td>Huurinkomsten</td><td><span class=\"tag-up\">↑ Ondernemerschap</span></td><td>6b — Bijzonder wonen op agrarisch veen</td></tr>\n      <tr><td><strong>Beter voedsel</strong><span class=\"euro\">€</span></td><td>Premium prijs, korte keten</td><td><span class=\"tag-up\">↑ Voedselzekerheid</span> <span class=\"tag-up\">↑ Ondernemerschap</span> <span class=\"tag-up\">↑ Cultuur</span></td><td>1a — Topvoedsel van koeien binnen natuur-inclusief boeren</td></tr>\n      <tr><td><strong>Paludicultuur (gras, lisdodde, riet, sphagnum)</strong><span class=\"euro\">€</span></td><td>Voer, eiwit, isolatie, biomassa, plantaardige compost; actieve veen-aanmaak via sphagnum keert bodemdaling om</td><td><span class=\"tag-up\">↑ Klimaat</span> <span class=\"tag-up\">↑ Ondernemerschap</span> <span class=\"tag-up\">↑ Cultuur</span></td><td>7a2, Grasbouw als nieuw boerenvakmanschap</td></tr>\n    </tbody>\n  </table>\n\n<p style=\"font-size:13.5px;color:var(--text2);line-height:1.65;margin-top:.5rem\">De drie rijen rond natuur en biodiversiteit hangen samen maar dekken drie verschillende dingen. <strong>Functionele biodiversiteit</strong> op niveau 1 (kruidenrijk grasland, bloemrijke randen) versterkt de bedrijfsvoering en levert stabielere, kwalitatief betere opbrengst; weidevogelbeheer hoort in dezelfde basislaag, maar als beheertaak — niet als opbrengstverhoger. Dat is geen verdienmodel maar een waardevolle bedrijfsbasis. <strong>Natuur als dienst</strong> gaat een stap verder: het inrichten en beheren van natuur met expliciete natuurdoelstellingen en -eigenschappen, verkoopbaar als opdracht aan overheid of marktpartij. <strong>Biodiversiteitsdienst</strong> is een nieuwere benadering waarbij biodiversiteit zelf wordt geproduceerd en verkocht, via overheidsopdracht, marktopdracht of de biodiversiteitscreditmarkt. De drie zijn nauw met elkaar verbonden maar conceptueel onderscheiden; alleen de laatste twee zijn verdienmodellen.</p>\n\n<p><strong>Stikstofruimte als dienst — denkrichting.</strong> Structurele ammoniakreductie door lagere veedichtheid kan op termijn een contracteerbare maatschappelijke dienst worden, analoog aan koolstof en water — juist waardevol nabij Natura 2000. Kanttekening: dit raakt aan extern salderen en het vergunningenrecht, juridisch het gevoeligste terrein dat er is; het hoort in de toolbox als verkenning, niet als belofte.</p>\n\n<h3>Drie typen, drie strategieën</h3>\n\n<p>Niet elke boer in het veenweidegebied is hetzelfde. De transitie levert verschillende typen ondernemers op die elk op hun eigen manier de toolbox inzetten: afhankelijk van context, grond, talent en smaak. Alle drie scoren ze boven de minimumdrempel op alle opgaves, maar met totaal verschillende profielen.</p>\n\n<p style=\"font-size:13px;color:var(--text2);line-height:1.6;margin:.5rem 0 1rem\"><em>De radardiagrammen tonen tien dimensies, niet zeven. Dat is geen andere telling van de opgaves: het zijn dezelfde zeven maatschappelijke opgaves uit sectie B, waarbij drie ervan — klimaat, water en natuur — voor zichtbaarheid in twee subdimensies zijn uitgesplitst. Klimaat in bodem (veenoxidatie) en bedrijf (vee + machines), water in kwaliteit en kwantiteit, natuur in gebieden (Natura 2000) en basiskwaliteit. De andere vier opgaves blijven ongedeeld.</em></p>\n\n<div style=\"display:grid;grid-template-columns:repeat(3,1fr);gap:16px;margin:1.5rem 0\">\n\n    <!-- JOOST -->\n    <div style=\"background:var(--bg3);border:1px solid rgba(0,0,0,.06);border-radius:var(--radius-lg);padding:1.5rem;border-top:3px solid var(--accent)\">\n      <div style=\"font-size:11px;text-transform:uppercase;letter-spacing:.08em;color:var(--accent);margin-bottom:6px;font-weight:500\">Type 1</div>\n      <h4 style=\"margin:0 0 .5rem;font-size:18px;font-family:var(--font-display)\">De verkenner</h4>\n      <p style=\"font-size:13px;color:var(--text2);line-height:1.5;margin-bottom:1rem\">Open, klein, dicht bij natuur. Nieuwsgierig naar paludicultuur, natte teelt, biodiversiteitsdiensten — ziet de transitie als kans. Combineert vaak een kleinere veestapel met meerdere nieuwe inkomstenstromen. De pionier die niet wacht op beleid maar al begonnen is.</p>\n      <svg viewBox=\"0 0 200 200\" style=\"width:100%;margin:0 auto;display:block\">\n        <g transform=\"translate(100,100)\">\n          <polygon points=\"0.0,-17.5 10.3,-14.2 16.6,-5.4 16.6,5.4 10.3,14.2 0.0,17.5 -10.3,14.2 -16.6,5.4 -16.6,-5.4 -10.3,-14.2\" fill=\"none\" stroke=\"var(--red)\" stroke-width=\"0.5\" stroke-dasharray=\"3 2\" opacity=\"0.4\"></polygon>\n          <polygon points=\"0.0,-70.0 41.1,-56.6 66.6,-21.6 66.6,21.6 41.1,56.6 0.0,70.0 -41.1,56.6 -66.6,21.6 -66.6,-21.6 -41.1,-56.6\" fill=\"none\" stroke=\"rgba(0,0,0,.06)\" stroke-width=\"0.5\"></polygon>\n          <polygon points=\"0.0,-52.5 30.9,-42.5 49.9,-16.2 49.9,16.2 30.9,42.5 0.0,52.5 -30.9,42.5 -49.9,16.2 -49.9,-16.2 -30.9,-42.5\" fill=\"none\" stroke=\"rgba(0,0,0,.04)\" stroke-width=\"0.5\"></polygon>\n          <polygon points=\"0.0,-35.0 20.6,-28.3 33.3,-10.8 33.3,10.8 20.6,28.3 0.0,35.0 -20.6,28.3 -33.3,10.8 -33.3,-10.8 -20.6,-28.3\" fill=\"none\" stroke=\"rgba(0,0,0,.04)\" stroke-width=\"0.5\"></polygon>\n          <polygon points=\"0.0,-63.0 32.9,-45.3 56.6,-18.4 53.3,17.3 37.0,51.0 0.0,59.5 -20.6,28.3 -59.9,19.5 -46.6,-15.1 -16.5,-22.7\" fill=\"var(--accent)\" fill-opacity=\"0.15\" stroke=\"var(--accent)\" stroke-width=\"1.5\"></polygon>\n          <text x=\"0\" y=\"-82\" text-anchor=\"middle\" font-size=\"7.5\" font-family=\"var(--font-body)\" fill=\"var(--text3)\" font-weight=\"500\">Kl.bodem</text>\n          <text x=\"48\" y=\"-66\" text-anchor=\"start\" font-size=\"7.5\" font-family=\"var(--font-body)\" fill=\"var(--text3)\" font-weight=\"500\">Kl.bedrijf</text>\n          <text x=\"78\" y=\"-25\" text-anchor=\"start\" font-size=\"7.5\" font-family=\"var(--font-body)\" fill=\"var(--text3)\" font-weight=\"500\">Wa.kwal.</text>\n          <text x=\"78\" y=\"25\" text-anchor=\"start\" font-size=\"7.5\" font-family=\"var(--font-body)\" fill=\"var(--text3)\" font-weight=\"500\">Wa.kwant.</text>\n          <text x=\"48\" y=\"66\" text-anchor=\"start\" font-size=\"7.5\" font-family=\"var(--font-body)\" fill=\"var(--text3)\" font-weight=\"500\">Na.geb.</text>\n          <text x=\"0\" y=\"82\" text-anchor=\"middle\" font-size=\"7.5\" font-family=\"var(--font-body)\" fill=\"var(--text3)\" font-weight=\"500\">Na.basis</text>\n          <text x=\"-48\" y=\"66\" text-anchor=\"end\" font-size=\"7.5\" font-family=\"var(--font-body)\" fill=\"var(--text3)\" font-weight=\"500\">Voedselzek.</text>\n          <text x=\"-78\" y=\"25\" text-anchor=\"end\" font-size=\"7.5\" font-family=\"var(--font-body)\" fill=\"var(--text3)\" font-weight=\"500\">Cultuur</text>\n          <text x=\"-78\" y=\"-25\" text-anchor=\"end\" font-size=\"7.5\" font-family=\"var(--font-body)\" fill=\"var(--text3)\" font-weight=\"500\">Grondst.</text>\n          <text x=\"-48\" y=\"-66\" text-anchor=\"end\" font-size=\"7.5\" font-family=\"var(--font-body)\" fill=\"var(--text3)\" font-weight=\"500\">Wonen</text>\n        </g>\n      </svg>\n      <p style=\"font-size:11px;color:var(--text3);margin-top:8px;text-align:center\">Hoog op natuur, klimaat, water, cultuur. Middel op voedselzekerheid (sterke kringloop, klein volume). Laag op wonen. Overal boven de drempel.</p>\n    </div>\n\n    <!-- BOY -->\n    <div style=\"background:var(--bg3);border:1px solid rgba(0,0,0,.06);border-radius:var(--radius-lg);padding:1.5rem;border-top:3px solid var(--blue)\">\n      <div style=\"font-size:11px;text-transform:uppercase;letter-spacing:.08em;color:var(--blue);margin-bottom:6px;font-weight:500\">Type 2</div>\n      <h4 style=\"margin:0 0 .5rem;font-size:18px;font-family:var(--font-display)\">De bouwer</h4>\n      <p style=\"font-size:13px;color:var(--text2);line-height:1.5;margin-bottom:1rem\">Kritisch, middelgroot, dicht bij stad. Combineert melk met diensten — waterberging, koolstof, korte keten, soms wonen bij de boer. Zoekt schaal in diensten, niet in vee. Open houding met een gezond kritische blik: wil het goed doen, maar vraagt bewijs.</p>\n      <svg viewBox=\"0 0 200 200\" style=\"width:100%;margin:0 auto;display:block\">\n        <g transform=\"translate(100,100)\">\n          <polygon points=\"0.0,-17.5 10.3,-14.2 16.6,-5.4 16.6,5.4 10.3,14.2 0.0,17.5 -10.3,14.2 -16.6,5.4 -16.6,-5.4 -10.3,-14.2\" fill=\"none\" stroke=\"var(--red)\" stroke-width=\"0.5\" stroke-dasharray=\"3 2\" opacity=\"0.4\"></polygon>\n          <polygon points=\"0.0,-70.0 41.1,-56.6 66.6,-21.6 66.6,21.6 41.1,56.6 0.0,70.0 -41.1,56.6 -66.6,21.6 -66.6,-21.6 -41.1,-56.6\" fill=\"none\" stroke=\"rgba(0,0,0,.06)\" stroke-width=\"0.5\"></polygon>\n          <polygon points=\"0.0,-52.5 30.9,-42.5 49.9,-16.2 49.9,16.2 30.9,42.5 0.0,52.5 -30.9,42.5 -49.9,16.2 -49.9,-16.2 -30.9,-42.5\" fill=\"none\" stroke=\"rgba(0,0,0,.04)\" stroke-width=\"0.5\"></polygon>\n          <polygon points=\"0.0,-35.0 20.6,-28.3 33.3,-10.8 33.3,10.8 20.6,28.3 0.0,35.0 -20.6,28.3 -33.3,10.8 -33.3,-10.8 -20.6,-28.3\" fill=\"none\" stroke=\"rgba(0,0,0,.04)\" stroke-width=\"0.5\"></polygon>\n          <polygon points=\"0.0,-38.5 20.6,-28.3 33.3,-10.8 30.0,9.7 18.5,25.5 0.0,35.0 -34.9,48.1 -36.6,11.9 -39.9,-13.0 -16.5,-22.7\" fill=\"var(--blue)\" fill-opacity=\"0.15\" stroke=\"var(--blue)\" stroke-width=\"1.5\"></polygon>\n          <text x=\"0\" y=\"-82\" text-anchor=\"middle\" font-size=\"7.5\" font-family=\"var(--font-body)\" fill=\"var(--text3)\" font-weight=\"500\">Kl.bodem</text>\n          <text x=\"48\" y=\"-66\" text-anchor=\"start\" font-size=\"7.5\" font-family=\"var(--font-body)\" fill=\"var(--text3)\" font-weight=\"500\">Kl.bedrijf</text>\n          <text x=\"78\" y=\"-25\" text-anchor=\"start\" font-size=\"7.5\" font-family=\"var(--font-body)\" fill=\"var(--text3)\" font-weight=\"500\">Wa.kwal.</text>\n          <text x=\"78\" y=\"25\" text-anchor=\"start\" font-size=\"7.5\" font-family=\"var(--font-body)\" fill=\"var(--text3)\" font-weight=\"500\">Wa.kwant.</text>\n          <text x=\"48\" y=\"66\" text-anchor=\"start\" font-size=\"7.5\" font-family=\"var(--font-body)\" fill=\"var(--text3)\" font-weight=\"500\">Na.geb.</text>\n          <text x=\"0\" y=\"82\" text-anchor=\"middle\" font-size=\"7.5\" font-family=\"var(--font-body)\" fill=\"var(--text3)\" font-weight=\"500\">Na.basis</text>\n          <text x=\"-48\" y=\"66\" text-anchor=\"end\" font-size=\"7.5\" font-family=\"var(--font-body)\" fill=\"var(--text3)\" font-weight=\"500\">Voedselzek.</text>\n          <text x=\"-78\" y=\"25\" text-anchor=\"end\" font-size=\"7.5\" font-family=\"var(--font-body)\" fill=\"var(--text3)\" font-weight=\"500\">Cultuur</text>\n          <text x=\"-78\" y=\"-25\" text-anchor=\"end\" font-size=\"7.5\" font-family=\"var(--font-body)\" fill=\"var(--text3)\" font-weight=\"500\">Grondst.</text>\n          <text x=\"-48\" y=\"-66\" text-anchor=\"end\" font-size=\"7.5\" font-family=\"var(--font-body)\" fill=\"var(--text3)\" font-weight=\"500\">Wonen</text>\n        </g>\n      </svg>\n      <p style=\"font-size:11px;color:var(--text3);margin-top:8px;text-align:center\">Gebalanceerd profiel. Hoog op voedselzekerheid (alle drie pijlers samen) en cultuur. Alle dimensies boven de drempel.</p>\n    </div>\n\n    <!-- RENÉ -->\n    <div style=\"background:var(--bg3);border:1px solid rgba(0,0,0,.06);border-radius:var(--radius-lg);padding:1.5rem;border-top:3px solid var(--amber)\">\n      <div style=\"font-size:11px;text-transform:uppercase;letter-spacing:.08em;color:var(--amber);margin-bottom:6px;font-weight:500\">Type 3</div>\n      <h4 style=\"margin:0 0 .5rem;font-size:18px;font-family:var(--font-display)\">De pragmaticus</h4>\n      <p style=\"font-size:13px;color:var(--text2);line-height:1.5;margin-bottom:1rem\">Pragmatisch, de grootste binnen de middengroep. Strakke bedrijfsvoering met aangepast graslandbeheer; doet mee als het instrumenteel klopt. Ziet maatschappelijke diensten als tweede inkomstenstroom, niet als roeping. Het bewijs dat ook de minst enthousiaste boer mee kan in veenweidelandbouw — mits het verdienmodel sluitend is.</p>\n      <svg viewBox=\"0 0 200 200\" style=\"width:100%;margin:0 auto;display:block\">\n        <g transform=\"translate(100,100)\">\n          <polygon points=\"0.0,-17.5 10.3,-14.2 16.6,-5.4 16.6,5.4 10.3,14.2 0.0,17.5 -10.3,14.2 -16.6,5.4 -16.6,-5.4 -10.3,-14.2\" fill=\"none\" stroke=\"var(--red)\" stroke-width=\"0.5\" stroke-dasharray=\"3 2\" opacity=\"0.4\"></polygon>\n          <polygon points=\"0.0,-70.0 41.1,-56.6 66.6,-21.6 66.6,21.6 41.1,56.6 0.0,70.0 -41.1,56.6 -66.6,21.6 -66.6,-21.6 -41.1,-56.6\" fill=\"none\" stroke=\"rgba(0,0,0,.06)\" stroke-width=\"0.5\"></polygon>\n          <polygon points=\"0.0,-52.5 30.9,-42.5 49.9,-16.2 49.9,16.2 30.9,42.5 0.0,52.5 -30.9,42.5 -49.9,16.2 -49.9,-16.2 -30.9,-42.5\" fill=\"none\" stroke=\"rgba(0,0,0,.04)\" stroke-width=\"0.5\"></polygon>\n          <polygon points=\"0.0,-35.0 20.6,-28.3 33.3,-10.8 33.3,10.8 20.6,28.3 0.0,35.0 -20.6,28.3 -33.3,10.8 -33.3,-10.8 -20.6,-28.3\" fill=\"none\" stroke=\"rgba(0,0,0,.04)\" stroke-width=\"0.5\"></polygon>\n          <polygon points=\"0.0,-26.6 14.4,-19.8 20.0,-6.5 23.3,7.6 12.3,17.0 0.0,22.4 -32.1,44.1 -23.3,7.6 -20.0,-6.5 -12.3,-17.0\" fill=\"var(--amber)\" fill-opacity=\"0.15\" stroke=\"var(--amber)\" stroke-width=\"1.5\"></polygon>\n          <text x=\"0\" y=\"-82\" text-anchor=\"middle\" font-size=\"7.5\" font-family=\"var(--font-body)\" fill=\"var(--text3)\" font-weight=\"500\">Kl.bodem</text>\n          <text x=\"48\" y=\"-66\" text-anchor=\"start\" font-size=\"7.5\" font-family=\"var(--font-body)\" fill=\"var(--text3)\" font-weight=\"500\">Kl.bedrijf</text>\n          <text x=\"78\" y=\"-25\" text-anchor=\"start\" font-size=\"7.5\" font-family=\"var(--font-body)\" fill=\"var(--text3)\" font-weight=\"500\">Wa.kwal.</text>\n          <text x=\"78\" y=\"25\" text-anchor=\"start\" font-size=\"7.5\" font-family=\"var(--font-body)\" fill=\"var(--text3)\" font-weight=\"500\">Wa.kwant.</text>\n          <text x=\"48\" y=\"66\" text-anchor=\"start\" font-size=\"7.5\" font-family=\"var(--font-body)\" fill=\"var(--text3)\" font-weight=\"500\">Na.geb.</text>\n          <text x=\"0\" y=\"82\" text-anchor=\"middle\" font-size=\"7.5\" font-family=\"var(--font-body)\" fill=\"var(--text3)\" font-weight=\"500\">Na.basis</text>\n          <text x=\"-48\" y=\"66\" text-anchor=\"end\" font-size=\"7.5\" font-family=\"var(--font-body)\" fill=\"var(--text3)\" font-weight=\"500\">Voedselzek.</text>\n          <text x=\"-78\" y=\"25\" text-anchor=\"end\" font-size=\"7.5\" font-family=\"var(--font-body)\" fill=\"var(--text3)\" font-weight=\"500\">Cultuur</text>\n          <text x=\"-78\" y=\"-25\" text-anchor=\"end\" font-size=\"7.5\" font-family=\"var(--font-body)\" fill=\"var(--text3)\" font-weight=\"500\">Grondst.</text>\n          <text x=\"-48\" y=\"-66\" text-anchor=\"end\" font-size=\"7.5\" font-family=\"var(--font-body)\" fill=\"var(--text3)\" font-weight=\"500\">Wonen</text>\n        </g>\n      </svg>\n      <p style=\"font-size:11px;color:var(--text3);margin-top:8px;text-align:center\">Hoog op voedselzekerheid (volume + mestlevering). Op de meeste andere dimensies net boven de drempel. Doet wat moet.</p>\n    </div>\n\n  </div>\n\n<p style=\"font-size:13px;color:var(--text2)\">De stippellijn in elk diagram is de minimumdrempel op alle tien dimensies. Alle drie de boeren halen die, maar met totaal verschillende profielen. Dat is het punt: veenweidelandbouw heeft geen één-type-boer nodig. Het heeft een systeem nodig waarin verschillende typen ondernemers elk op hun eigen manier de drempels halen. <strong>Let op de assen</strong>: 'Voedselzekerheid' is in dit document drie pijlers tegelijk — directe productie, inputs (mest, water) aan akkerbouw elders in Nederland, en vermindering van importafhankelijkheid (voer, kunstmest). De pragmaticus scoort hoog via volume en mestlevering, de bouwer via alle drie pijlers bewust samen, de verkenner via gesloten kringloop maar met klein volume. Drie verschillende routes naar dezelfde opgave.</p>\n\n<h3>Toepassing per context</h3>\n\n<p>De toolbox verschilt per context. Welke bouwstenen beschikbaar zijn en welke doelen prioriteit hebben, hangt af van waar je zit.</p>\n\n<div class=\"context-grid\">\n    <div class=\"context-card\">\n      <div class=\"icon\">🌿</div>\n      <h4>Natuur</h4>\n      <p style=\"font-size:13px;color:var(--text2);margin-bottom:8px\">Boerderij grenst aan natuurgebied</p>\n      <ul>\n        <li>Biodiversiteitscredits waardevoller</li>\n        <li>Natuurbeheer als betaalde dienst</li>\n        <li>Wateropslag sluit aan op watersysteem</li>\n        <li>Ruimtelijke ordening complex (Natura 2000)</li>\n      </ul>\n    </div>\n    <div class=\"context-card\">\n      <div class=\"icon\">🏘️</div>\n      <h4>Stadsrand</h4>\n      <p style=\"font-size:13px;color:var(--text2);margin-bottom:8px\">Boerderij grenst aan stedelijk gebied</p>\n      <ul>\n        <li>Wonen bij de boer aantrekkelijk</li>\n        <li>Korte keten — directe afzetmarkt</li>\n        <li>Recreatie en zorgboerderij als inkomsten</li>\n        <li>Waterbuffering relevant</li>\n      </ul>\n    </div>\n    <div class=\"context-card\">\n      <div class=\"icon\">🌾</div>\n      <h4>Polder</h4>\n      <p style=\"font-size:13px;color:var(--text2);margin-bottom:8px\">Open veenweidelandschap</p>\n      <ul>\n        <li>Grote schaal wateropslag</li>\n        <li>CO₂-credits op grotere percelen</li>\n        <li>Bergboerenregeling past goed</li>\n        <li>Minder nabijheid van afzetmarkten</li>\n      </ul>\n    </div>\n  </div>\n","werkstand":{"nummer":"10","ronde":"3","stand":"nog de bestuursversie"},"skelet":[{"nummer":"10","titel":"Wat de ondernemer doet","bron":"f-ondernemer","stand":"ronde 3","deel":"Deel IV — Veenweideboeren","kern":"De overheid zegt wat er geleverd moet worden, de ondernemer bepaalt hoe. Dit hoofdstuk is de gereedschapskist: negen categorieën maatregelen binnen het bestaande bedrijf, en daarnaast de routes naar nieuw inkomen. Niet iedereen hoeft hetzelfde te doen, en dat is het punt.","secties":[{"kop":"10.1 De toolbox is de vrijheid","elementen":[{"t":"de overheid zegt wat er geleverd moet worden, de ondernemer bepaalt hoe","v":"tekst","h":"auteurs","n":""},{"t":"de toolbox past bij verschillende typen ondernemers, niet bij één","v":"tekst","h":"auteurs","n":""}]},{"kop":"10.2 Niveau 1 — het bestaande bedrijf beter","elementen":[{"t":"negen categorieën bouwstenen, van waterbeheer tot mechanisatie","v":"tabel","h":"auteurs","n":""},{"t":"eerst de randvoorwaarde: zonder waterinfiltratiesysteem werkt peilbeleid niet","v":"fiche","h":"auteurs","n":""}]},{"kop":"10.3 Niveau 2 — nieuwe inkomstenstromen","elementen":[{"t":"koolstof, water, biodiversiteit, natte teelt, landschap","v":"tabel","h":"auteurs","n":""},{"t":"stikstofruimte als dienst: een denkrichting","v":"fiche","h":"auteurs","n":""}]},{"kop":"10.4 Drie typen, drie strategieën","elementen":[{"t":"de verkenner, de bouwer, de bewaarder","v":"beeld","h":"auteurs","n":""},{"t":"welke bouwstenen beschikbaar zijn verschilt per context","v":"tabel","h":"auteurs","n":""}]}],"noot":""}],"deel":"Deel IV — Veenweideboeren"},{"id":"f-overheid","letter":"F2","titel":"Overheidskant: het kader","intro":"Bovenop de verplichte maatregelen zijn dit de condities die de overheid moet faciliteren om akte III mogelijk te maken. Ze werken alleen als systeem, je moet op zes niveaus tegelijk bewegen: maatregelen, doelen, juridische ruimte, vangnet, opdrachten en coördinatie. Als je er maar één pakt, trekt het oude systeem de verandering weer terug. Twee aantekeningen vooraf: de overheid is hier geen enkelvoudige entiteit — Rijk (LVVN, IenW, BZK), provincie, waterschap en gemeente dragen elk afzonderlijke pijlers of delen daarvan, en welke laag wat doet vergt aparte uitwerking. En dit document raamt geen kosten — de orde-van-grootte vereist eigen werk samen met het ministerie van Financiën; op enkele plekken zijn bestaande referentiepunten zichtbaar (ANLb-groei, koolstofcredit-tarieven).","html":"\n<h2>F2 — Overheidskant: het kader</h2>\n\n<p>Bovenop de verplichte maatregelen zijn dit de condities die de overheid moet faciliteren om akte III mogelijk te maken. Ze werken alleen als systeem, je moet op zes niveaus tegelijk bewegen: maatregelen, doelen, juridische ruimte, vangnet, opdrachten en coördinatie. Als je er maar één pakt, trekt het oude systeem de verandering weer terug. Twee aantekeningen vooraf: de overheid is hier geen enkelvoudige entiteit — Rijk (LVVN, IenW, BZK), provincie, waterschap en gemeente dragen elk afzonderlijke pijlers of delen daarvan, en welke laag wat doet vergt aparte uitwerking. En dit document raamt geen kosten — de orde-van-grootte vereist eigen werk samen met het ministerie van Financiën; op enkele plekken zijn bestaande referentiepunten zichtbaar (ANLb-groei, koolstofcredit-tarieven).</p>\n\n<div style=\"background:var(--amber-light);border-left:3px solid var(--amber);border-radius:var(--radius);padding:1.25rem 1.5rem;margin:1.25rem 0;font-size:13.5px;line-height:1.65\">\n    <strong style=\"display:block;margin-bottom:6px;font-size:14px\">Driesporenbeleid, drie van de vier pijlers ontbreken</strong>\n    <p style=\"margin:0\">Het driesporenbeleid dekt vrijwel uitsluitend cluster 1: inkomen en zekerheid, en dan ook nog in compensatie-logica (hectarepremie, opkoop, afwaardering). De andere drie clusters blijven onderbelicht of afwezig: markttoegang (veenweidezuivelketen, koolstof- en biodiversiteitsmarkt), grond en ruimte (Nationale Grondbank, veenweidecategorie in het omgevingsplan, juridische ruimte voor natte teelt en paludicultuur), en organisatie en financiering (gebiedsregie via collectieven, transitiesteun). Zonder deze drie clusters is spoor 3 een eenzame poot, een ambitie zonder instrumentarium. Het verschil tussen \"akte II voor 90.000 ha + akte III voor 20.000 ha\" en een dragend veenweide-systeem zit precies in deze ontbrekende pijlers.</p>\n  </div>\n\n<div style=\"background:var(--bg3);border:1px solid rgba(0,0,0,.08);border-left:3px solid var(--blue);border-radius:var(--radius);padding:1.25rem 1.5rem;margin:1.25rem 0;font-size:13.5px;line-height:1.65\">\n    <strong style=\"display:block;margin-bottom:8px;font-size:14px\">Het juridische frame moet meekantelen</strong>\n    <p style=\"margin:0 0 .75rem\">De redenering in dit document botst op één punt onvermijdelijk met de huidige juridische kaders rond aanbesteding en staatssteun. Een echt zakelijk dienstverleningscontract tussen overheid en boer voor maatschappelijke diensten valt onder Europese aanbestedingsverplichtingen. Een directe betaling buiten zo'n contract loopt het risico op staatssteun-kwalificatie. De praktische route binnen die kaders is daarom een slim ingerichte subsidieregeling — lange looptijd, afrekenbare prestatievoorwaarden, geen krap plafond. Juristen wijzen daar terecht op.</p>\n    <p style=\"margin:0 0 .75rem\">Toch neemt dit document een andere positie in. De huidige juridische kaders gaan uit van een definitie waarin de boer iemand is die landbouwt en daarnaast incidenteel iets voor de samenleving doet en daarvoor subsidie ontvangt. Dat is precies de definitie die hier ter discussie staat. De veenweideboer in akte III produceert maatschappelijke diensten als kernactiviteit, niet als bijproduct.</p>\n    <p style=\"margin:0\">Als de subsidie-route als startpositie wordt geaccepteerd, blijft impliciet die oude definitie staan — en blijft het hele frame van \"betaling voor geleverde diensten\" steken in subsidie-taal. Daarom hoort het gesprek over de juridische status van maatschappelijke diensten als primair landbouwproduct tot de eerste fase van dit dossier, niet tot de slotfase. Het slim ingerichte subsidie-instrument is daarmee niet plan A maar plan B — voorbereid voor het geval het bredere gesprek onvoldoende meebeweegt.</p>\n  </div>\n\n<div style=\"background:var(--bg3);border:1px solid rgba(0,0,0,.08);border-left:3px solid var(--blue);border-radius:var(--radius);padding:1.25rem 1.5rem;margin:1.25rem 0;font-size:13.5px;line-height:1.65\">\n    <strong style=\"display:block;margin-bottom:8px;font-size:14px\">Zijstap: uitkoop versus management — het borgings-dilemma</strong>\n    <p style=\"margin:0 0 .75rem\">Uitkoop is verreweg de duurste maatregel<span class=\"fiche-wrap\"><button class=\"fiche-btn\" type=\"button\" aria-label=\"Bron tonen\">ⓘ</button><span class=\"fiche-popup\"><span class=\"fiche-label\">Bron</span><span class=\"fiche-source\">CLM Onderzoek &amp; Advies (in opdracht van ABN Amro); vergelijking van veertien stikstofreductiemaatregelen: uitkoop is de duurste, een combinatie van technische en managementmaatregelen is kosteneffectiever.</span></span></span>. Toch komt het keer op keer op tafel — om één reden die in beleidsdebatten zelden expliciet wordt: handhaafbaarheid. Management heeft een reëel borgings­probleem: toezicht over decennia, naleving moeilijk meetbaar. Dat verschil is echt.</p>\n    <p style=\"margin:0 0 .75rem\">Maar uitkoop heeft beperkingen die er zelden naast worden gelegd. Vrijwilligheid: het bereikt wie wil verkopen, niet wie het zwaarst vervuilt. Bestemming: de grond gaat vaak naar beleggers en schaalvergroters buiten het gebied. En er ontstaat geen verdienmodel — alleen een eenmalige transactie zonder nieuwe basis.</p>\n    <p style=\"margin:0\">Akte III borgt anders dan via overheidsbezit. Prestatiecontracten zijn juridisch bindend, betaling alleen bij geleverde prestatie. De boer heeft eigen economisch belang bij voortzetting: stopt de levering, dan stopt het inkomen. Borging zit deels in toezicht, deels in de bedrijfsstructuur zelf. De handhavingskosten blijven hoger dan bij uitkoop — maar de drager van het gebied blijft, gebonden aan prestatie, met eigen belang bij naleving.</p>\n  </div>\n\n<!-- CLUSTER 1 -->\n\n<h3 style=\"margin-top:2rem;font-size:16px\">1 — Inkomen &amp; zekerheid</h3>\n\n<p style=\"font-size:13px;color:var(--text2);margin-bottom:1rem\">De motor financieel voeden. Zonder langjarig, voorspelbaar opdrachtgeverschap van de overheid neemt geen ondernemer het risico om te transiteren.</p>\n\n<div class=\"vangrail-list\">\n    <div class=\"vangrail-item\"><div class=\"vangrail-info\"><div class=\"name\">Gebiedsspecifieke basisvergoeding</div><div class=\"summary\" style=\"font-size:13px;font-weight:500;color:var(--text);margin-bottom:6px;line-height:1.5\">Structurele jaarlijkse vergoeding voor boeren op nat veen, bergboerenlogica. Compenseert de permanente handicap, niet het project.</div><div class=\"desc\">Structurele jaarlijkse vergoeding voor bedrijven die opereren in een vernattingsregime, als compensatie voor de permanente structurele handicap. Gebaseerd op de EU-bergboerenlogica (Areas with Natural Constraints, GLB Pijler 2), aangevuld met nationale middelen. Niet projectgebonden, niet tijdelijk: zolang het veenweidebedrijf in het regime opereert, ontvangt het de vergoeding. De regeling bestaat in principe al maar werd in Nederland gestopt; een hernieuwde veenweidevergoeding is sinds 2024 opnieuw in ontwikkeling bij LVVN.</div></div></div>\n    <div class=\"vangrail-item\"><div class=\"vangrail-info\"><div class=\"name\">Prestatiecontract maatschappelijke opdrachten</div><div class=\"summary\" style=\"font-size:13px;font-weight:500;color:var(--text);margin-bottom:6px;line-height:1.5\">Langjarig contract (10–20 jaar) waarin de boer maatschappelijke diensten levert en de overheid betaalt. Zakelijke transactie, geen subsidie.</div><div class=\"desc\">Langjarig contract (10–20 jaar) tussen overheid en boer voor de meetbare levering van publieke diensten: natuur, waterkwaliteit, waterberging, koolstofbehoud en landschapsbeheer. Drie inkomenslagen: (1) vaste systeemvergoeding voor het bedrijfsregime als geheel, (2) prestatievergoeding voor aantoonbare resultaten per opgave, (3) collectieve gebiedsvergoeding via het collectief voor coördinatie en mozaïekbeheer. De boer is leverancier van publieke waarde, niet ontvanger van subsidie. Uitkomstbestek: overheid beschrijft WAT ze wil, boer bepaalt HOE. De boer moet er winst op kunnen maken, geen gederfde-inkomstenvergoeding à 80%. Vijf ontwerpregels tegen kapitalisatie: betaling gebonden aan de ondernemer (niet aan grondeigendom), voorwaardelijk en tijdelijk (alleen bij naleving regime), deels via collectieven (niet volledig als individuele hectare-opbrengst zichtbaar), gekoppeld aan prestatie (niet generiek per hectare), en niet vrij overdraagbaar zonder herijking. Gebaseerd op het ANLb-model maar zwaarder, langduriger en systeemdragend, het ANLb groeit naar €500 mln/jaar structureel vanaf 2026<span class=\"fiche-wrap\"><button class=\"fiche-btn\" type=\"button\" aria-label=\"Bron tonen\">ⓘ</button><span class=\"fiche-popup\"><span class=\"fiche-label\">Bron</span><span class=\"fiche-source\">Kamerbrief 'Contourenbrief agrarisch natuurbeheer', minister Wiersma (LVVN), november 2024.</span></span></span> met contracten tot 20 jaar<span class=\"fiche-wrap\"><button class=\"fiche-btn\" type=\"button\" aria-label=\"Bron tonen\">ⓘ</button><span class=\"fiche-popup\"><span class=\"fiche-label\">Bron</span><span class=\"fiche-source\">Kamerbrief 'Contourenbrief agrarisch natuurbeheer', minister Wiersma (LVVN), november 2024.</span></span></span>.</div></div></div>\n  </div>\n\n<!-- CLUSTER 2 -->\n\n<h3 style=\"margin-top:2rem;font-size:16px\">2 — Markttoegang</h3>\n\n<p style=\"font-size:13px;color:var(--text2);margin-bottom:1rem\">De motor op nieuwe brandstof zetten. Zolang de markt alleen liters en bulk beloont, blijft de druk op schaalvergroting bestaan.</p>\n\n<div class=\"vangrail-list\">\n    <div class=\"vangrail-item\"><div class=\"vangrail-info\"><div class=\"name\">Veenweidezuivelketen</div><div class=\"summary\" style=\"font-size:13px;font-weight:500;color:var(--text);margin-bottom:6px;line-height:1.5\">De overheid dekt de tafel zodat de zuivelketen zelf beweegt richting een veenweidecertificaat. Geen marktspeler worden, wel voorwaarden scheppen.</div><div class=\"desc\">De overheid kan de zuivelketen niet dwingen, mededingingsrecht en wereldmarktprijzen begrenzen directe interventie. Maar ze kan de tafel dekken: via publiek-private samenwerking (zoals de Duurzame Zuivelketen met LVVN al doet), co-financiering van een veenweidecertificaat (vergelijkbaar met PlanetProof en weidemerk), de Biodiversiteitsmonitor koppelen aan ketenpremies, GLB-ecoregelingen differentiëren naar extensieve veenweideproductie, en overheidsinkoopbeleid inzetten als marktsignaal. Geen marktspeler worden, wel de voorwaarden scheppen waaronder de keten zelf beweegt. De Europese vergelijking laat zien dat nichemarkten de enige structurele tegenkracht zijn tegen schaalvergroting, in Oostenrijk en Noord-Italië houden streekproducten en biologische melkstromen kleinere bedrijven overeind. Zonder ketenbeweging blijft de overheid permanent het gat dichten dat de bulkmarkt laat vallen.</div></div></div>\n    <div class=\"vangrail-item\"><div class=\"vangrail-info\"><div class=\"name\">Koolstof- en biodiversiteitsmarkt</div><div class=\"summary\" style=\"font-size:13px;font-weight:500;color:var(--text);margin-bottom:6px;line-height:1.5\">De overheid bouwt de marktinfrastructuur voor CO₂-credits en biodiversiteitscredits. Regelgever, launching customer en kwaliteitsbewaker.</div><div class=\"desc\">Hier is de overheidsrol het grootst. Het EU Carbon Removal Certification Framework (CRCF, in werking dec 2024)<span class=\"fiche-wrap\"><button class=\"fiche-btn\" type=\"button\" aria-label=\"Bron tonen\">ⓘ</button><span class=\"fiche-popup\"><span class=\"fiche-label\">Bron</span><span class=\"fiche-source\">EU Carbon Removal Certification Framework (CRCF), verordening (EU) 2024/3012, in werking 26 december 2024.</span></span></span> biedt straks een Europees erkend kader voor carbon farming, inclusief specifiek voor veenvernatting (methodologie verwacht zomer 2026)<span class=\"fiche-wrap\"><button class=\"fiche-btn\" type=\"button\" aria-label=\"Bron tonen\">ⓘ</button><span class=\"fiche-popup\"><span class=\"fiche-label\">Bron</span><span class=\"fiche-source\">Europese Commissie; certificeringsmethodologie voor veenvernatting in voorbereiding, verwachte vaststelling zomer 2026.</span></span></span>. De Valuta voor Veen-methodiek is nationaal al gecertificeerd via de Stichting Nationale Koolstofmarkt en kan €400–700/ha opleveren<span class=\"fiche-wrap\"><button class=\"fiche-btn\" type=\"button\" aria-label=\"Bron tonen\">ⓘ</button><span class=\"fiche-popup\"><span class=\"fiche-label\">Bron</span><span class=\"fiche-source\">Natuur en Milieufederaties / Stichting Nationale Koolstofmarkt; methodiek Valuta voor Veen, vastgesteld eind 2019 via Green Deal Nationale Koolstofmarkt.</span></span></span>. Twee preciseringen horen daarbij. De markt betaalt alleen voor prestaties bóven de wettelijke doelen van Europees en Nederlands beleid — wat al verplicht is, is geen verhandelbare prestatie. En de markt onderscheidt vermeden uitstoot (vernatting remt veenoxidatie) van echte verwijdering (opname en permanente koolstofopslag in en op het veen); die laatste categorie is de sterkste claim en het schaarste product. De overheid is hier regelgever (certificeringsstandaarden), launching customer (LVVN koopt al certificaten via het Nationaal Groenfonds), marktinfrastructuur-bouwer (regionale koolstofbanken als platform) en kwaliteitsbewaker (anti-greenwashing via CRCF-toezicht). Biodiversiteitscredits zijn minder ver: de EU werkt aan een natuurkredietsysteem, maar meetmethodiek is complexer dan bij koolstof. Hier moet de overheid vooroplopen in standaardontwikkeling.</div></div></div>\n  </div>\n\n<!-- CLUSTER 3 -->\n\n<h3 style=\"margin-top:2rem;font-size:16px\">3 — Grond &amp; ruimte</h3>\n\n<p style=\"font-size:13px;color:var(--text2);margin-bottom:1rem\">De motor toegang geven. Zonder betaalbare grond en juridische ruimte voor nieuwe activiteiten blijft transitie onhaalbaar.</p>\n\n<div class=\"vangrail-list\">\n    <div class=\"vangrail-item\"><div class=\"vangrail-info\"><div class=\"name\">Actief grondbeleid &amp; landafwaardering</div><div class=\"summary\" style=\"font-size:13px;font-weight:500;color:var(--text);margin-bottom:6px;line-height:1.5\">Grondbank als matchmaker: stoppers kunnen verkopen, starters kunnen instromen. Voorkomt dat publiek geld weglekt in de grondprijs, en vangt de waardedaling door vernatting op, zodat de boer niet gedwongen wordt te verkopen en zijn pensioen niet verdampt.</div><div class=\"desc\">Provincie, waterschap of een nationale grondbank koopt strategisch grond aan in veenweidezones en geeft die uit onder doelgebonden pacht of erfpacht, niet vrij verhandelbaar, alleen beschikbaar voor boeren die het veenweidebedrijfsmodel voeren. Niet als grootschalig opkoopfonds, maar als matchmaker: boer die wil stoppen kan grond verkopen, boer die iets nieuws wil doen kan instromen. Voorkomt dat nieuwe publieke betalingen weglopen in stijgende grondprijzen (kapitalisatierisico), en stopt de grondhonger-dynamiek uit akte II. Helpt ook bij landafwaardering. Vernatting veroorzaakt waardedaling, dat kan voor boeren voelen als pensioenverdamping. De grondbank vangt dat op: ze koopt grond tegen reële waarde aan en geeft het terug in doelgebonden pacht, zodat de boer kan blijven boeren zonder gedwongen verkoop. De afwaardering wordt zo geen verliespost voor de individuele ondernemer, maar een herwaardering die collectief wordt gedragen. Dit is het spiegelbeeld van de afwaardering uit spoor 3: daar wordt waardedaling betaald als eindpunt; hier bouwt de hectare ondertussen nieuwe, stapelbare dienstenwaarde op. De fiscale en boekhoudkundige uitwerking vergt aparte uitwerking in de implementatiefase. Het kabinet werkt sinds 2024 aan een Nationale Grondbank als instrument voor de transitie landelijk gebied. Daarbij hoort een aparte pachtlogica voor veenweidegronden: plafond op pachtverhoging gekoppeld aan publieke vergoedingen, betalingen voor maatschappelijke diensten niet automatisch in de pachtbasis, en langjarig karakter zodat ondernemers durven investeren.</div></div></div>\n    <div class=\"vangrail-item\"><div class=\"vangrail-info\"><div class=\"name\">Veenweidecategorie in omgevingsplan</div><div class=\"summary\" style=\"font-size:13px;font-weight:500;color:var(--text);margin-bottom:6px;line-height:1.5\">Een eigen juridische categorie voor het veenweidebedrijf: niet agrarisch, niet natuur, maar een derde weg met eigen rechten en mogelijkheden.</div><div class=\"desc\">Via de Omgevingswet (in werking vanaf 1 januari 2024, vervangt bestemmingsplan) een aparte functiecategorie voor het veenweidebedrijf: niet agrarisch, niet natuur, maar een derde categorie met eigen rechten en mogelijkheden. Functieverandering is om twee redenen nodig: (1) als sturingsmechanisme voor waterschappen om peilbesluiten te nemen die bij de nieuwe functie passen, en (2) omdat de activiteiten die de veenweideboer doet — wateropslag, biodiversiteitsproductie, paludicultuur — juridisch geen landbouw zijn in de GLB-definitie. Zonder functieverandering passen de nieuwe activiteiten niet in het bestemmingsplan. Maakt ruimte voor natte teelt, paludicultuur, wonen bij de boer en waterberging als bedrijfsactiviteit. De categorie regelt niet alleen wat juridisch mag, maar ook hoe — met ruimtelijke ontwerpvoorwaarden (schaal, hoogteprofielen, doorzichten, materialiteit) zodat elke nieuwe activiteit het veenweide-landschap versterkt in plaats van beschadigt: niet de functie bepaalt de landschapsimpact, maar de ruimtelijke inrichting. Doelsturing op bedrijfsniveau: hoge doelen stellen, meerdere routes toestaan, dat geeft ondernemersruimte en vermindert regeldruk.</div></div></div>\n  </div>\n\n<!-- CLUSTER 4 -->\n\n<h3 style=\"margin-top:2rem;font-size:16px\">4 — Organisatie &amp; financiering</h3>\n\n<p style=\"font-size:13px;color:var(--text2);margin-bottom:1rem\">De motor laten draaien. Zonder gebiedsregie en toegang tot kapitaal kan geen enkele andere pijler structureel effect hebben.</p>\n\n<div class=\"vangrail-list\">\n    <div class=\"vangrail-item\"><div class=\"vangrail-info\"><div class=\"name\">Gebiedsregie via gebiedsorganisaties</div><div class=\"summary\" style=\"font-size:13px;font-weight:500;color:var(--text);margin-bottom:6px;line-height:1.5\">Eén boer kan niet alleen het waterpeil veranderen. Collectieven worden gebiedsregisseur, de coördinatielaag waaronder alle andere instrumenten pas werken.</div><div class=\"desc\">Collectieven en gebiedsorganisaties schuiven op van beheerorganisatie naar gebiedsregisseur: zij stemmen waterpeilen af, plannen weidevogelmozaïeken, organiseren monitoring, coördineren peilafstemming tussen bedrijven en helpen grond- en pachtstructuren inrichten. Één boer kan niet alleen transiteren, waterpeil geldt voor de hele polder. Het ANLb werkt al via collectieven als institutionele basis; voor een dragend veenweidesysteem moeten collectieven zwaarder worden gefaciliteerd en gefinancierd. Spanning met zelfstandig ondernemerschap: collectieven mogen geen beperking worden. Doelsturing op totaal bedrijfsniveau, als een boer op perceel A uitstoot maar op perceel B drie keer zoveel opslaat, moet dat per saldo kunnen tellen. Zonder gebiedsregie werkt geen enkele andere pijler structureel. Waterbeheer en landbouwcontract moeten hierbij één worden: peilregime, flexibiliteit bij extremen, verantwoordelijkheid voor infrastructuur en monitoring horen ín het bedrijfscontract, niet ernaast als los beleidsdossier.</div></div></div>\n    <div class=\"vangrail-item\"><div class=\"vangrail-info\"><div class=\"name\">Transitiesteun</div><div class=\"summary\" style=\"font-size:13px;font-weight:500;color:var(--text);margin-bottom:6px;line-height:1.5\">Overbrugging voor de kwetsbare eerste jaren. De rem is risicobeleving, niet kennis — risicodeling neemt die barrière weg.</div><div class=\"desc\">De dominante rem op transitie is risicobeleving, niet kennisgebrek. Klassieke subsidies compenseren pas achteraf; risicodeling deelt het risico vooraf — overheid en andere stakeholders (waterschap, zuivelketen, financiers) bieden gezamenlijk inkomensgarantie tijdens de transitieperiode. Geen financieringsprobleem maar een inkomstenprobleem — zodra prestatiecontracten en basisvergoeding lopen, komt bankfinanciering vanzelf. Tijdelijke voorziening, geen permanente pijler.</div></div></div>\n  </div>\n\n<div style=\"background:var(--bg3);border:1px solid rgba(0,0,0,.08);border-left:3px solid var(--blue);border-radius:var(--radius);padding:1.25rem 1.5rem;margin:1.5rem 0 0;font-size:13.5px;line-height:1.65\">\n    <strong style=\"display:block;margin-bottom:8px;font-size:14px\">Wortel én stok — handhaving als sluitstuk</strong>\n    <p style=\"margin:0 0 .75rem\">Het pijlersysteem hierboven is de wortel: faciliteren, verdienmodel mogelijk maken, ondernemersruimte scheppen. Maar zonder stok werkt het niet. Vrijblijvende ruimte voor wie niet meebeweegt ondergraaft het systeem en is oneerlijk tegenover wie wel de transitie maakt. Ook vanuit de boerensector zelf klinkt deze vraag: faciliteer ons, maar wees ook hard voor wie meelift zonder bij te dragen.</p>\n    <p style=\"margin:0 0 .5rem\">Drie elementen:</p>\n    <ul style=\"margin:0 0 .75rem;padding-left:1.25rem\">\n      <li style=\"margin-bottom:.4rem\"><strong>Strikte handhaving van de generieke regels</strong>: peilbesluiten, KRW-normen, stikstofeisen gelden voor iedereen — geen ontheffingen die het regime ondergraven, ook niet als \"tijdelijke uitzondering\".</li>\n      <li style=\"margin-bottom:.4rem\"><strong>Voorwaardelijkheid van vergoedingen</strong>: wie van basisvergoeding of prestatiecontract gebruik wil maken, voldoet aan de generieke verplichtingen. Geen vrijblijvende toegang.</li>\n      <li><strong>Deadline voor vrijwilligheid</strong>: vrijwillige stoppersregelingen blijven beschikbaar binnen een afgebakend tijdsvenster, zodat er een prikkel is om tijdig te kiezen.</li>\n    </ul>\n    <p style=\"margin:0\">Dit is geen straf voor wie achterblijft; het is bescherming van wie meedoet. Een transitie zonder handhaving wordt een transitie waarvan alleen de free-riders profiteren.</p>\n  </div>\n","werkstand":{"nummer":"11","ronde":"3","stand":"nog de bestuursversie"},"skelet":[{"nummer":"11","titel":"Wat de overheid doet","bron":"f-overheid","stand":"ronde 3","deel":"Deel IV — Veenweideboeren","kern":"Strakker op wat er geleverd moet worden, ruimer op hoe. Dit hoofdstuk ordent het overheidshandelen in drie: wat moet, wat mag, en wat betaalt — opdrachten waar zij een dienst inkoopt, steun waar zij niets terugkrijgt. En het benoemt de juridische adder: een echt dienstencontract botst op aanbesteding en staatssteun, en wij kiezen er toch voor.","secties":[{"kop":"11.1 Het sturingsprincipe","elementen":[{"t":"hardere uitkomsten, vrijere middelen","v":"tekst","h":"verhuisd","n":"uit hoofdstuk 9"}]},{"kop":"11.2 Wat moet, wat mag, wat betaalt","elementen":[{"t":"de zes lagen herordend naar moeten, mogen en betalen","v":"tabel","h":"verhuisd","n":"§15.2"},{"t":"markttoegang verhuist van het vangnet naar \"wat mag\", want het is infrastructuur en geen geld","v":"tekst","h":"nieuw","n":""},{"t":"opdrachten groeit en steun krimpt naarmate de prestatiecontracten gaan lopen","v":"tekst","h":"nieuw","n":""},{"t":"langjarige contracten van 10 tot 20 jaar zijn ook voor de ondernemer winst","v":"tekst","h":"nieuw","n":"besluit 17-8"}]},{"kop":"11.3 Het juridische frame moet meekantelen","elementen":[{"t":"aanbesteding en staatssteun: de haken en ogen, en waarom wij tóch voor de opdracht kiezen","v":"tekst","h":"auteurs","n":""},{"t":"plan B is een slim ingerichte subsidieregeling, en juristen wijzen daar terecht op","v":"tekst","h":"auteurs","n":""},{"t":"**mogen en willen zijn twee dingen:** ook binnen een kader dat het toestaat moet een opdrachtgever het wíllen, en dat vraagt een andere verhouding dan subsidie","v":"tekst","h":"nieuw","n":"Tim, 19-8"},{"t":"van bijproduct naar productiemiddel: wat nu een niet-productieve investering heet, is dan een investering in productie","v":"tabel","h":"verhuisd","n":"uit hoofdstuk 5, want het gaat over het instrument en niet over wat het gebied kan (Tim, 19-8)"},{"t":"verwijst terug naar aanname 4 en bouwt de redenering niet opnieuw op","v":"—","h":"","n":""}]},{"kop":"11.4 Collectieven en het waterschap","elementen":[{"t":"collectieven organiseren de afstemming, het waterschap neemt het peilbesluit","v":"tekst","h":"nieuw","n":"§10"},{"t":"het collectief is breder dan melkveehouders alleen","v":"tekst","h":"nieuw","n":""},{"t":"derden brengen hun belang in via het peilbesluit, waar bezwaar en beroep al geregeld zijn","v":"tekst","h":"nieuw","n":"één zin, vraag van Simon"}]}],"noot":""}],"deel":"Deel IV — Veenweideboeren"},{"id":"f3-bedrijfsleven","letter":"F3","titel":"Bedrijfslevenkant: wie schuift aan","intro":"Akte III staat of valt met meer dan overheid en boer. Het verdienmodel bestaat alleen als de markt aan de andere kant aansluit: de afnemers van melk, de financiers van de bedrijfsovergang, en — nieuw en cruciaal — de afnemers van de maatschappelijke diensten zelf. Zonder die derde laag blijft akte III een papieren constructie. Het bedrijfsleven is daarin geen passieve toehoorder maar actor: drie groepen schuiven aan, elk met een eigen handelingsperspectief.","html":"\n<h2>F3 — Bedrijfslevenkant: wie schuift aan</h2>\n\n<p>Akte III staat of valt met meer dan overheid en boer. Het verdienmodel bestaat alleen als de markt aan de andere kant aansluit: de afnemers van melk, de financiers van de bedrijfsovergang, en — nieuw en cruciaal — de afnemers van de maatschappelijke diensten zelf. Zonder die derde laag blijft akte III een papieren constructie. Het bedrijfsleven is daarin geen passieve toehoorder maar actor: drie groepen schuiven aan, elk met een eigen handelingsperspectief.</p>\n\n<h3 style=\"margin-top:2rem;font-size:16px\">1 — Bestaande agroketen</h3>\n\n<p style=\"font-size:13px;color:var(--text2);margin-bottom:1rem\">De keten die er al is, beweegt mee.</p>\n\n<p><strong>Zuivelondernemingen</strong> (FrieslandCampina, A-ware, Cono, kleinere coöperaties) — veenweidecertificaat met ketenpremium, mengstromen voor klimaatpositieve melk, koppeling Biodiversiteitsmonitor aan uitbetalingsprijs. Geen verplichting via mededinging, wél bewegingsruimte via co-financiering en publiek-private samenwerking.</p>\n\n<p><strong>Voerleveranciers</strong> (ForFarmers, Agrifirm) — productontwikkeling voor low-input bedrijfsvoering, lokaal eiwit als alternatief voor importsoja.</p>\n\n<p><strong>Levensmiddelen-retailers</strong> (Albert Heijn, Jumbo, Ekoplaza) — inkoopbeleid als marktsignaal, eigen merken met veenweide-claim.</p>\n\n<p><strong>Akkerbouwsector</strong> — afnemer van organische mest uit veenweidegebied, partij bij zoetwater-uitruil tussen veen en klei.</p>\n\n<h3 style=\"margin-top:2rem;font-size:16px\">2 — Financiers</h3>\n\n<p style=\"font-size:13px;color:var(--text2);margin-bottom:1rem\">De partij die de overgang mogelijk maakt.</p>\n\n<p><strong>Banken</strong> (Rabobank, ABN Amro, Triodos) — drie cruciale rollen: (1) financiering van transitie-investeringen (paludicultuur, watersystemen, stalaanpassingen), (2) taxatie van veenweidegrond bij vernatting — vandaag het grootste obstakel, want grond onder vernattingsregime krijgt lagere taxatie en daarmee minder onderpand, (3) erkenning van prestatiecontracten als zekerheid voor kredieten.</p>\n\n<p><strong>Gespecialiseerde fondsen</strong> (Nationaal Groenfonds, BNG Bank, Triodos Groenfonds) — risicokapitaal en transitiekredieten waar reguliere banken nog terughoudend zijn.</p>\n\n<p><strong>Verzekeraars</strong> (Achmea, Interpolis) — bedrijfsrisico-instrumenten voor de transitieperiode, oogstrisico bij paludicultuur.</p>\n\n<h3 style=\"margin-top:2rem;font-size:16px\">3 — Marktpartijen voor maatschappelijke diensten <em style=\"font-weight:400;color:var(--text3);font-size:14px\">(nieuw)</em></h3>\n\n<p style=\"font-size:13px;color:var(--text2);margin-bottom:1rem\">De partijen die de maatschappelijke opdrachten daadwerkelijk afnemen. Hier ontstaan nieuwe markten met nieuwe spelers — het verst van het huidige systeem af.</p>\n\n<p><strong>Drinkwaterbedrijven</strong> (Vitens, Waternet, PWN, Brabant Water, Evides) — afnemers van waterberging, schoonwaterproductie en bescherming van bronnen. Betaling voor \"water als dienst\" past binnen hun zorgplicht; Europese voorbeelden (Vittel in Frankrijk, München in Duitsland) tonen dat dit werkt.</p>\n\n<p><strong>Klimaat-marktpartijen</strong> — aanbieders/certificeerders (Stichting Nationale Koolstofmarkt, Climate Cleanup), maar ook afnemers van credits: bedrijven met klimaatdoelen, luchtvaart en industrie die compliance- of vrijwillige offsets zoeken via Valuta voor Veen of het komende CRCF-kader.</p>\n\n<p><strong>Biodiversiteits-marktpartijen</strong> — nog onderontwikkeld, maar in opbouw: bouw- en infrasector als afnemer (mitigatie elders), gebiedsontwikkelaars, en organisaties als LandschappenNL en Vogelbescherming als aanbieders/certificeerders. EU-natuurkredietsysteem in ontwikkeling.</p>\n\n<p><strong>Bouw- en energiebedrijven</strong> <em style=\"color:var(--text3)\">(perifeer)</em> — lisdodde-vezels als isolatie/bouwmateriaal, paludicultuur als energiegewas. Komt later in beeld maar verbreedt het bedrijfsleven-spectrum.</p>\n\n<div style=\"background:var(--bg3);border:1px solid rgba(0,0,0,.08);border-left:3px solid var(--blue);border-radius:var(--radius);padding:1.25rem 1.5rem;margin:1.5rem 0 0;font-size:13.5px;line-height:1.65\">\n    <strong style=\"display:block;margin-bottom:8px;font-size:14px\">Wat dit betekent voor de doorgang</strong>\n    <p style=\"margin:0\">Deze drie groepen lopen niet synchroon. De bestaande agroketen kan binnen 2-3 jaar bewegen — certificaten bestaan, ketenpremies kunnen schalen. Banken kunnen binnen die tijd taxatiestelsels en kredietproducten aanpassen, mits prestatiecontracten en grondbeleid stabiel zijn. De marktpartijen voor maatschappelijke diensten hebben langer nodig: sommige markten (water) zijn er deels al, andere (biodiversiteit) zijn nog in opbouw. Maar zonder cluster 3 blijft akte III afhankelijk van overheidsgeld; mét cluster 3 ontstaat een dragend privaat-publiek systeem.</p>\n  </div>\n","werkstand":{"nummer":"12","ronde":"3","stand":"nog de bestuursversie, groeit naar een volwaardig hoofdstuk"},"skelet":[{"nummer":"12","titel":"Wat de markt doet","bron":"f3-bedrijfsleven","stand":"ronde 3","deel":"Deel IV — Veenweideboeren","kern":"Zolang al het geld van de overheid komt, houdt het weerwoord stand dat dit subsidie is met een ander etiket. Dit hoofdstuk zet de tweede geldstroom neer: de zuivelketen, banken en verzekeraars, de drinkwaterbedrijven, de koolstofmarkt. En het zegt eerlijk wat er nog niet is, want in het veenweidegebied betaalt vandaag geen enkele partij voor een geleverde dienst.","secties":[{"kop":"12.1 Waarom de markt erbij hoort","elementen":[{"t":"zolang alle inkomsten van de overheid komen, houdt het weerwoord stand dat dit subsidie is met een ander etiket","v":"tekst","h":"nieuw","n":""},{"t":"één betalende marktpartij weerlegt dat beter dan welke formulering ook","v":"tekst","h":"nieuw","n":""}]},{"kop":"12.2 Wie er kunnen aanschuiven","elementen":[{"t":"de bestaande agroketen: zuivel, voer, retail, akkerbouw","v":"tabel","h":"auteurs","n":""},{"t":"de financiers: banken, fondsen, verzekeraars","v":"tabel","h":"auteurs","n":""},{"t":"de afnemers van maatschappelijke diensten: drinkwater, koolstof, biodiversiteit","v":"tabel","h":"auteurs","n":""}]},{"kop":"12.3 Wat er nog niet is","elementen":[{"t":"geen markt voor CO₂ op veen, geen mestplatform, geen vergoeding voor regionale waterdiensten","v":"tekst","h":"verhuisd","n":"uit hoofdstuk 5"},{"t":"in het veenweidegebied betaalt geen drinkwaterbedrijf voor een dienst; die stap is elders gezet, op zandgrond","v":"tekst + fiche","h":"nieuw","n":""},{"t":"Vittel en München zijn een voorbeeld en geen bewijs dat het hier al zo werkt","v":"fiche","h":"auteurs","n":""},{"t":"wie er door deze kanteling aan tafel komt","v":"tekst","h":"verhuisd","n":"uit hoofdstuk 5"}]}],"noot":""}],"deel":"Deel IV — Veenweideboeren"},{"id":"g-perspectief","letter":"G","titel":"Terug naar de boer: wat kun je nu doen?","intro":"In hoofdstuk 3 zagen we dat de middengroep klem zit, 70-80% van de boeren in het veenweidegebied vandaag, zonder perspectief. Alles daartussen was het bewijs en het instrumentarium. Nu de vraag: wat biedt dit de boer van vandaag? Er liggen drie routes open, en één daarvan is nieuw.","html":"\n<h2>G — Terug naar de boer: wat kun je nu doen?</h2>\n\n<p>In hoofdstuk 3 zagen we dat de middengroep klem zit, 70-80% van de boeren in het veenweidegebied vandaag, zonder perspectief. Alles daartussen was het bewijs en het instrumentarium. Nu de vraag: wat biedt dit de boer van vandaag? Er liggen drie routes open, en één daarvan is nieuw.</p>\n\n<p>Wat dit document probeert te doen, voorbij de analyse, is iets dat in de meeste beleidsstukken ontbreekt: erkenning. Erkenning van het feit dat de middengroep niet faalt, maar klem zit in een systeem dat haar maar twee opties biedt. Pas als die erkenning wordt gevoeld, ontstaat ruimte om iets los te laten en iets nieuws te beginnen. De derde route hieronder is niet bedoeld als opgelegd alternatief, maar als een aanbod aan wie zelf de uitdaging ziet aankomen.</p>\n\n<div style=\"display:grid;grid-template-columns:repeat(3,1fr);gap:16px;margin:1.5rem 0\">\n\n    <div style=\"background:var(--bg3);border:1px solid rgba(0,0,0,.06);border-radius:var(--radius-lg);padding:1.5rem;border-top:3px solid var(--amber)\">\n      <div style=\"font-size:11px;text-transform:uppercase;letter-spacing:.08em;color:var(--text3);margin-bottom:6px;font-weight:600\">1 — Doorgaan zoals het is</div>\n      <p style=\"font-size:13px;color:var(--text2);line-height:1.5\">Blijven doen wat je doet, en dat volhouden: kosten drukken en hopen dat de marge het houdt. Op het grootste deel van het veenweidegebied kan dat gewoon, en dan is het een goede keuze. Waar de opgaven zich stapelen wordt het kwetsbaar, en is volhouden op een gegeven moment tegen de stroom in roeien.</p>\n    </div>\n\n    <div style=\"background:var(--bg3);border:1px solid rgba(0,0,0,.06);border-radius:var(--radius-lg);padding:1.5rem;border-top:3px solid var(--text3)\">\n      <div style=\"font-size:11px;text-transform:uppercase;letter-spacing:.08em;color:var(--text3);margin-bottom:6px;font-weight:600\">2 — Stoppen</div>\n      <p style=\"font-size:13px;color:var(--text2);line-height:1.5\">Het bedrijf beëindigen. Grond verkopen, een andere weg inslaan. Voor sommige ondernemers een bewuste, legitieme keuze — niet elk bedrijf leent zich voor omvorming, en dat is geen falen. Wie stopt omdat er geen opvolger is, kan het bedrijf ook eerst toekomstbestendig maken en het dán overdragen. De zorg ligt bij het grondbeleid: zonder actieve regie verdwijnt de grond naar grootschalige kopers van buiten het gebied.</p>\n    </div>\n\n    <div style=\"background:var(--bg3);border:1px solid rgba(0,0,0,.06);border-radius:var(--radius-lg);padding:1.5rem;border-top:3px solid var(--accent)\">\n      <div style=\"font-size:11px;text-transform:uppercase;letter-spacing:.08em;color:var(--accent);margin-bottom:6px;font-weight:600\">3 — Maatschappelijke diensten erbij, van één perceel tot het hele bedrijf</div>\n      <p style=\"font-size:13px;color:var(--text2);line-height:1.5\">Naast het vee iets doen waarvoor betaald wordt. Dat kan klein beginnen: één perceel weidevogelbeheer met een contract, water bergen op de laagste hoek. Het hoeft ook niet aan de grond te hangen: zorg of recreatie op het bedrijf hoort er net zo goed bij. Het kan verder gaan, tot melk één van meerdere producten is bij een lagere veedichtheid. En het kan helemaal doorlopen, tot een bedrijf zonder koeien waar de diensten het product zijn. Waar je op die schaal gaat staan, bepaal je zelf; de posities staan in hoofdstuk 9.</p>\n    </div>\n\n  </div>\n\n<p>De eerste twee routes bestaan al: dat zijn precies de twee die hoofdstuk 1 noemt, doorgaan zoals het is of uitkopen. De derde is wat dit document toevoegt, en die draait op één principe: inkomen verdienen zonder schaalvergroting — meer waarde per hectare, niet meer hectares. Waar een bedrijf op die schaal terechtkomt, hangt af van de plek en van de ondernemer, en beide bewegen.</p>\n\n<div style=\"background:var(--bg3);border:1px solid rgba(0,0,0,.08);border-left:3px solid var(--text2);border-radius:var(--radius);padding:1rem 1.25rem;margin:1.25rem 0;font-size:13px;line-height:1.6\">\n    <strong style=\"display:block;margin-bottom:4px\">Niet iedereen wíl meebewegen — en dat is geen verzet, dat is verlangen</strong>\n    Een aanzienlijk deel van de middengroep wil simpelweg boer blijven zoals altijd: koeien houden, gras maaien, land beheren. Niet uit principiële weerstand, maar uit een rustig verlangen om te doen wat ze al een leven lang doen. Zij zullen zich aan de laatste strohalm vasthouden. Dat is een gegeven waarmee dit verhaal rekent — niet iets om te bestrijden.\n  </div>\n\n<h3>Wie zijn deze veenweideboeren? Drie archetypen, drie contexten</h3>\n\n<p style=\"font-size:13.5px;color:var(--text2);line-height:1.6\">Het verhaal van dit document is niet anoniem. Achter \"de middengroep\" en \"de veenweideboer\" zitten herkenbare mensen op herkenbare plekken. Drie archetypen verschillen in karakter en bedrijfsschaal; drie contexten verschillen in fysieke uitgangssituatie. De combinatie bepaalt hoe het verhaal landt en welke route logisch is. Geen voorschrift, wel een spiegel — voor de boer die de eigen positie zoekt, en voor de beleidsmaker die weet dat één maatregel nooit hetzelfde uitwerkt op alle ondernemers.</p>\n\n<div style=\"background:var(--bg3);border:1px solid rgba(0,0,0,.06);border-radius:var(--radius-lg);padding:1.25rem 1.5rem;margin:1rem 0 1.25rem;overflow-x:auto\">\n    <table style=\"width:100%;border-collapse:collapse;font-size:12.5px;line-height:1.55\">\n      <thead>\n        <tr style=\"border-bottom:1px solid rgba(0,0,0,.1)\">\n          <th style=\"text-align:left;padding:.6rem .5rem;width:14%;font-weight:600;color:var(--text2);font-size:11px;text-transform:uppercase;letter-spacing:.05em\">&nbsp;</th>\n          <th style=\"text-align:left;padding:.6rem .75rem;width:28.5%;color:var(--text)\">\n            <div style=\"font-weight:700;font-size:13.5px\">De verkenner</div>\n            <div style=\"font-size:11px;color:var(--text3);font-weight:400;margin-top:1px\">open, klein, dicht bij natuur</div>\n          </th>\n          <th style=\"text-align:left;padding:.6rem .75rem;width:28.75%;color:var(--text)\">\n            <div style=\"font-weight:700;font-size:13.5px\">De bouwer</div>\n            <div style=\"font-size:11px;color:var(--text3);font-weight:400;margin-top:1px\">kritisch, middelgroot, dicht bij stad</div>\n          </th>\n          <th style=\"text-align:left;padding:.6rem .75rem;width:28.75%;color:var(--text)\">\n            <div style=\"font-weight:700;font-size:13.5px\">De pragmaticus</div>\n            <div style=\"font-size:11px;color:var(--text3);font-weight:400;margin-top:1px\">pragmatisch, de grootste binnen de middengroep</div>\n          </th>\n        </tr>\n      </thead>\n      <tbody>\n        <tr style=\"border-bottom:1px solid rgba(0,0,0,.06)\">\n          <td style=\"padding:.75rem .5rem;font-weight:600;color:var(--text);vertical-align:top\">Polder</td>\n          <td style=\"padding:.75rem .75rem;color:var(--text2);vertical-align:top\">Nieuwsgierig naar paludicultuur en natte teelt; ziet de polder als experimenteerruimte.</td>\n          <td style=\"padding:.75rem .75rem;color:var(--text2);vertical-align:top\">Combineert melk met waterberging en koolstof; zoekt schaal in diensten, niet in vee.</td>\n          <td style=\"padding:.75rem .75rem;color:var(--text2);vertical-align:top\">Strakke bedrijfsvoering met aangepast graslandbeheer; doet mee als het instrumenteel klopt.</td>\n        </tr>\n        <tr style=\"border-bottom:1px solid rgba(0,0,0,.06)\">\n          <td style=\"padding:.75rem .5rem;font-weight:600;color:var(--text);vertical-align:top\">Stadsrand</td>\n          <td style=\"padding:.75rem .75rem;color:var(--text2);vertical-align:top\">Zorgboerderij, recreatie, korte keten — verbindt natuurlijk met de stad.</td>\n          <td style=\"padding:.75rem .75rem;color:var(--text2);vertical-align:top\">Wonen-bij-de-boer, tiny houses, multifunctioneel — bouwt aan een nieuwe stedelijke rand.</td>\n          <td style=\"padding:.75rem .75rem;color:var(--text2);vertical-align:top\">Premium voedsel voor de stadsmarkt; ziet maatschappelijke diensten als tweede inkomensstroom.</td>\n        </tr>\n        <tr>\n          <td style=\"padding:.75rem .5rem;font-weight:600;color:var(--text);vertical-align:top\">Natuur</td>\n          <td style=\"padding:.75rem .75rem;color:var(--text2);vertical-align:top\">Vloeit het meest natuurlijk in de natuur-functie; biodiversiteit als verdienmodel.</td>\n          <td style=\"padding:.75rem .75rem;color:var(--text2);vertical-align:top\">Bufferbeheer rond Natura 2000 als hoofdactiviteit; bouwt een nieuw bedrijfsmodel op.</td>\n          <td style=\"padding:.75rem .75rem;color:var(--text2);vertical-align:top\">Schakelt om naar functiewijziging waar dat economisch zinniger is dan vasthouden.</td>\n        </tr>\n      </tbody>\n    </table>\n  </div>\n\n<p style=\"font-size:13.5px;color:var(--text2);line-height:1.6\">De middengroep — over wie dit document gaat — telt al deze typen op alle drie de contexten. Wie zich in de matrix herkent, ziet ook waar op de derde route hij of zij het meest natuurlijk staat: de verkenners voelen zich vaker thuis aan het verste eind, waar de diensten het product worden, en de bouwers en pragmatici zoeken het eerder in melk als één van meerdere producten. Geen wet — maar wel een patroon.</p>\n\n<div style=\"background:var(--accent-light);border-left:3px solid var(--accent);border-radius:var(--radius);padding:1rem 1.25rem;margin:1.25rem 0;font-size:13px;line-height:1.6\">\n    <strong style=\"display:block;margin-bottom:4px\">De cirkel is rond</strong>\n    In A zeiden we: de middengroep zit klem, en dat blokkeert alle opgaves. Nu is het antwoord compleet: de veenweideboer-categorie geeft die middengroep een nieuw kader, een nieuwe toolbox en een nieuw verdienmodel. De boer die klem zat wordt de ondernemer die de opgaves haalt, niet uit altruïsme, maar omdat het loont.\n  </div>\n\n<h3>Van visie naar ondernemersbod</h3>\n\n<p>Dit verhaal is niet alleen een analyse, het kan een aanbod worden. Niet de overheid die oplegt, maar de boerensector die zegt: <strong>dit willen wij leveren, onder deze voorwaarden.</strong></p>\n\n<p>Concreet: een ondernemersbod vanuit de veenweideboeren richting de overheid. Wij leveren maatschappelijke diensten: schoon water, vastgehouden koolstof, weidevogels, landschapskwaliteit. In ruil vragen wij: duidelijke kaders, langjarige zekerheid, juridische ruimte en eerlijke betaling. Dat is geen subsidieaanvraag. Dat is een zakelijke propositie.</p>\n\n<p>De veenweideboer-typologie wordt dan de <strong>basiswerkwijze voor gebiedsbiedingen</strong>. In de Alblasserwaard, in de Krimpenerwaard, in Friesland, overal waar veenweidegebieden tegen dezelfde keuze aanlopen, wordt dit het framework waarbinnen boeren en overheden tot een gebiedsbod komen. Niet één centraal plan, maar een herbruikbaar model dat per gebied wordt ingevuld.</p>\n","werkstand":{"nummer":"13","ronde":"3","stand":"bestuursversie, met de routes omgebouwd naar drie (19-8)"},"skelet":[{"nummer":"13","titel":"Wat de boer nu al kan doen (G — Terug naar de boer)","bron":"g-perspectief","stand":"ronde 3","deel":"Deel IV — Veenweideboeren","kern":"Drie routes: doorgaan zoals het is, stoppen, of maatschappelijke diensten erbij — van één perceel tot het hele bedrijf. De eerste twee bestaan al, de derde is wat dit document toevoegt. Dit is het enige hoofdstuk dat de ondernemer direct aanspreekt, met drie archetypen waarin hij of zij zich kan herkennen. Erkenning eerst, dan een bod.","secties":[{"kop":"13.1 Drie routes","elementen":[{"t":"**1 doorgaan zoals het is** (amber: kan gewoon op het grootste deel, wordt kwetsbaar waar de opgaven stapelen) · **2 stoppen** (neutraal, een legitieme keuze; met de overdracht-variant van Costas erbij) · **3 diensten erbij, van één perceel tot het hele bedrijf** (groen, dit is de schaal uit 9.2)","v":"kaarten","h":"auteurs + nieuw","n":""},{"t":"**de eerste twee bestaan al** — het zijn de twee die hoofdstuk 1 noemt, doorgaan of uitkopen — **en de derde is wat dit document toevoegt**","v":"tekst","h":"nieuw","n":"de verbinding met 1.1, en de reden dat het aanbod scherper is dan vier opties waarvan twee rood"},{"t":"de transitie als het bedrijf toekomstbestendig maken voor de volgende generatie","v":"tekst","h":"nieuw","n":"besluit 17-8, geland in de stoppen-kaart"},{"t":"de transitie als het bedrijf toekomstbestendig maken voor de volgende generatie","v":"tekst","h":"nieuw","n":"besluit 17-8"}]},{"kop":"13.2 Drie archetypen: hoe verschillende ondernemers het invullen","elementen":[{"t":"drie archetypen in drie contexten","v":"tabel","h":"auteurs","n":""},{"t":"niet iedereen wíl meebewegen, en dat is verlangen en geen verzet","v":"fiche","h":"auteurs","n":""}]},{"kop":"13.3 Van visie naar ondernemersbod","elementen":[{"t":"niet de overheid die oplegt, maar de ondernemer die biedt","v":"tekst","h":"auteurs","n":""}]}],"noot":"Waren vier; omgebouwd 19-8 (Tim). \"Veenweideboer worden\" is geen route meer, want dat is de lezer al, en \"nieuwe activiteiten\" was geen aparte keuze maar een verdere positie op dezelfde schaal."}],"deel":"Deel IV — Veenweideboeren"},{"id":"h-risicos","letter":"H","titel":"Waar het mis kan gaan","intro":"Akte III is geen garantie. Dezelfde goedbedoelde beleidslogica die akte II deed mislukken, kan ook akte III ondermijnen, als de onderliggende systeemkrachten niet worden aangepakt. Negen risico's om scherp op te zijn.","html":"\n<h2>H — Waar het mis kan gaan</h2>\n\n<p>Akte III is geen garantie. Dezelfde goedbedoelde beleidslogica die akte II deed mislukken, kan ook akte III ondermijnen, als de onderliggende systeemkrachten niet worden aangepakt. Negen risico's om scherp op te zijn.</p>\n\n<div class=\"question-list\">\n    <div class=\"question-item\">\n      <div class=\"q\" style=\"color:var(--red)\">① Schijntransitie</div>\n      <div class=\"ctx\">Meer geld beschikbaar, maar het oude model blijft dominant. Maatschappelijke diensten worden een extra inkomenslaag bovenop een systeem dat in de kern nog steeds draait op schaal en liters. De transitie lijkt te gebeuren, maar de structuur verandert niet.</div>\n    </div>\n    <div class=\"question-item\">\n      <div class=\"q\" style=\"color:var(--red)\">② Kapitalisatie in grondprijs</div>\n      <div class=\"ctx\">Nieuwe publieke betalingen verhogen de verdiencapaciteit van grond, en daarmee op termijn de grondprijs of pacht. Het geld dat bedoeld is voor de boer verdwijnt in de grondmarkt. Risico is groot als betalingen generiek aan hectares hangen in plaats van aan ondernemer, contract en prestatie.</div>\n    </div>\n    <div class=\"question-item\">\n      <div class=\"q\" style=\"color:var(--amber)\">③ Selectie op grote bedrijven</div>\n      <div class=\"ctx\">De best georganiseerde, best gefinancierde bedrijven trekken de meeste waarde naar zich toe. Regelingen die schaalneutraal lijken — generiek per hectare, vrij toegankelijk — zijn dat in de praktijk niet: aanvraagkracht en cashflow-buffer zijn schaalafhankelijk. Kleinere en middelgrote bedrijven — juist de verbonden ondernemers die akte III nodig heeft — vallen daardoor buiten de boot. Ontwerp tegen kaping is geen detail maar fundament.</div>\n    </div>\n    <div class=\"question-item\">\n      <div class=\"q\" style=\"color:var(--amber)\">④ Beleidsversnippering</div>\n      <div class=\"ctx\">Water, natuur, landbouw en grond blijven losse beleidsdossiers. De boer staat op het kruispunt van tegenstrijdige logica's en moet zelf de samenhang organiseren. Zonder één gebiedscontract dat alle opgaves integreert, werkt geen enkele pijler structureel.</div>\n    </div>\n    <div class=\"question-item\">\n      <div class=\"q\" style=\"color:var(--amber)\">⑤ Tijdsonzekerheid</div>\n      <div class=\"ctx\">Boeren geloven niet dat de spelregels lang genoeg blijven bestaan. Een melkveebedrijf verandert zijn structuur niet op basis van twee of drie jaar beleidszekerheid. Zolang contracten te kort zijn en beleid te wisselend, blijft de ondernemer rationeel vasthouden aan het oude model.</div>\n    </div>\n    <div class=\"question-item\">\n      <div class=\"q\" style=\"color:var(--amber)\">⑥ Bedrijfsoverdracht en instap</div>\n      <div class=\"ctx\">Zonder instap- en opvolgingsinstrument werkt akte III alleen voor wie al in het systeem zit. Hoge grondprijzen en toegang tot kapitaal zijn drempels voor nieuwe boeren en kleinere overnames. Concreet nodig: voorkeurspositie voor gezinsbedrijven en nieuwe toetreders bij gebiedsgrond, modulaire contracten die niet alleen op grote schaal rendabel zijn, en investeringssteun voor omschakelaars.</div>\n    </div>\n    <div class=\"question-item\">\n      <div class=\"q\" style=\"color:var(--amber)\">⑦ Boer als ambtenaar</div>\n      <div class=\"ctx\">Cynisch bekeken wordt de veenweideboer een ambtenaar in dienst van de overheid die produceert wat de overheid bestelt. Dat frame ondermijnt draagvlak en ondernemersidentiteit. Het weerwoord: de boer houdt eigen grond, eigen keuzes en eigen risico — en kan altijd besluiten iets anders te doen. En produceren voor de overheid geeft juist zekerheid: langjarige contracten, stabiel inkomen, geen afhankelijkheid van de wereldmarktprijs. Dat is geen ambtenarij, dat is een prettige manier van ondernemen.</div>\n    </div>\n    <div class=\"question-item\">\n      <div class=\"q\" style=\"color:var(--red)\">⑧ Stikstof-boemerang</div>\n      <div class=\"ctx\">Stikstof is het politieke vehikel dat het hele dossier nu in beweging brengt. Maar als de aanpak smal blijft — alleen ammoniakreductie via minder koeien — verdwijnen precies de familieondernemers die de zeven opgaves moeten dragen. De stikstofcijfers verbeteren op papier, terwijl sociale cohesie, landschap, kringloop en cultuur instorten omdat de dragers weg zijn. De maatschappelijke verborgen waarden die deze ondernemers gratis leverden (landbeheer, signalering, sociale aanwezigheid) komen niet terug zodra de grond in handen is van beleggers of partijen die op afstand bezitten. Stikstofbeleid zonder breder ondernemersperspectief is akte II onder een nieuwe naam.</div>\n    </div>\n    <div class=\"question-item\">\n      <div class=\"q\" style=\"color:var(--amber)\">⑨ Half bestaand, half nieuw</div>\n      <div class=\"ctx\">Een deel van de pijlers is verlenging of opschaling van bestaand instrumentarium: ANLb-uitbreiding, GLB-ecoregelingen differentiëren, Nationale Grondbank, koolstofcertificering via CRCF. Een ander deel vraagt nieuw instrumentarium: prestatiecontracten van 10-20 jaar, veenweidecategorie in het omgevingsplan, juridische ruimte voor paludicultuur buiten de GLB-landbouwdefinitie. Wie alles probeert te laten passen in het bestaande, sloopt de delen die juist nieuw moeten zijn. Wie alles als nieuw presenteert, mist de aanknopingspunten die er al zijn. Het onderscheid bewust maken — en in een aparte uitwerking expliciteren — is implementatiewerk dat na deze visie volgt.</div>\n    </div>\n  </div>\n","werkstand":{"nummer":"14","ronde":"4","stand":"nog de bestuursversie"},"skelet":[{"nummer":"14","titel":"Wat er moet gebeuren om dit te laten werken (H — Risico's)","bron":"h-risicos","stand":"ronde 4","deel":"Deel V — Sluitstukken","kern":"Hier staat wat er nog niet klopt, en dat is geen disclaimer maar een opdracht. Twee dingen: wat bewezen moet worden voordat de aannames staan, en waaraan het ontwerp van de regelingen moet voldoen om niet gekaapt te worden. Elk punt staat er met zijn antwoord ernaast, en waar wij dat antwoord niet hebben staat dat er ook.","secties":[{"kop":"14.1 Wat er nog bewezen moet worden","elementen":[{"t":"per aanname de agenda: een prijs die hoog genoeg is, een looptijd die lang genoeg is, en meten dat de dienst niet opeet","v":"tekst","h":"verhuisd","n":"uit hoofdstuk 2, aanname 1"},{"t":"één private partij die betaalt voor een dienst in plaats van voor schade, met een contract dat navolgbaar is","v":"tekst","h":"verhuisd","n":"uit aanname 2"},{"t":"en één publieke opdrachtgever die een dienst inkoopt in plaats van kosten te vergoeden; de gewoonte, de instrumenten en de cultuur daarvoor bestaan nog niet","v":"tekst","h":"nieuw","n":"Tim, 19-8: dit is de grootste horde en hij stond nergens"},{"t":"of de middengroep de omslag zelf wil, en de onderbouwing van de 70 tot 80 procent","v":"tekst","h":"verhuisd","n":"uit aanname 3, met het openstaande `[[CIJFER]]`"},{"t":"het Europese kader moet op tijd meebewegen","v":"tekst","h":"verhuisd","n":"uit aanname 4"},{"t":"de drie acties die bepalen of akte III werkelijkheid wordt","v":"tekst","h":"verhuisd","n":"uit het slot"}]},{"kop":"14.2 Waar het ontwerp aan moet voldoen","elementen":[{"t":"de zeven punten waar het mis kan gaan, elk als eis: dit kan gebeuren, dus moet het ontwerp dit doen","v":"lijst","h":"auteurs","n":""},{"t":"waar wij het antwoord niet hebben staat dat er, net als bij de aannames","v":"tekst","h":"nieuw","n":""},{"t":"het zijn onderliggende systeemkrachten, geen ondermijnende","v":"tekst","h":"auteurs","n":"besluit 17-8"},{"t":"het ontwerp moet voorkomen dat de stikstofaanpak akte II wordt","v":"tekst","h":"verhuisd","n":"uit de wachtkamer, besluit 18-8 — als eis en niet als oordeel"}]}],"noot":"Dit hoofdstuk en hoofdstuk 2 zijn twee kanten: 2 zegt waarop het verhaal rust, 14 wat er moet gebeuren voordat het staat. Dat onderscheid moet in de openingszin van beide hoofdstukken staan, anders leest het als dubbel."}],"deel":"Deel V — Sluitstukken"},{"id":"slot","letter":null,"titel":"Van visie naar uitvoering","intro":"Dit document begon bij de boer die klem zit, en eindigt bij de ondernemer die de opgaves draagt. Daartussen ligt geen wonder, maar een ontwerpkeuze: dezelfde maatregelen, dezelfde doelen, maar met de pijlers eronder die van compensatie een verdienmodel maken. Wat daarvoor nodig is, is geen nieuw geld — het is een andere logica: van subsidies naar vergoedingen voor geleverde maatschappelijke diensten.","html":"\n<h2>Van visie naar uitvoering</h2>\n\n<p>Dit document begon bij de boer die klem zit, en eindigt bij de ondernemer die de opgaves draagt. Daartussen ligt geen wonder, maar een ontwerpkeuze: dezelfde maatregelen, dezelfde doelen, maar met de pijlers eronder die van compensatie een verdienmodel maken. Wat daarvoor nodig is, is geen nieuw geld — het is een andere logica: van subsidies naar vergoedingen voor geleverde maatschappelijke diensten.</p>\n\n<p>Drie acties bepalen of akte III werkelijkheid wordt. Voer het gesprek over de juridische status van maatschappelijke diensten als primair landbouwproduct — in de eerste fase, niet de laatste. Zet de circa €1,3 miljard om van compensatielogica naar langjarig, voorspelbaar opdrachtgeverschap. En creëer de veenweidecategorie in het omgevingsplan, zodat de activiteiten die de opgaves dragen ook juridisch kunnen bestaan.</p>\n\n<p>Perspectief bieden aan ondernemers in het veenweidegebied — daar begon dit document. De veenweideboer als toekomstbestendige ondernemer die maatschappelijke diensten levert: dát is het perspectief. Voor de uitvoering ontwikkelt het Veenweiden Innovatiecentrum een afzonderlijk programmavoorstel.</p>\n","werkstand":{"nummer":"15","ronde":"4","stand":"nog de bestuursversie, wordt herschreven"},"skelet":[{"nummer":"15","titel":"Slot","bron":"slot","stand":"ronde 4","deel":"Deel V — Sluitstukken","kern":"Waar dit begon en waar het eindigt. En de vraag, in twee regels: wij vragen geen euro uit de lopende programma's, wel de ruimte om te bouwen wat de volgende ronde nodig heeft. Op tijd, dus nu.","secties":[{"kop":"15.1 Waar dit begon en waar het eindigt","elementen":[{"t":"het document begon bij de ondernemer die klem zit en eindigt bij de ondernemer die de opgaven draagt","v":"tekst","h":"auteurs","n":""},{"t":"de verbinding met de programma's: JUMP levert de bedrijfsconcepten, deze aanpak de bewijslast, BASE moet de betaling aantonen","v":"tekst","h":"verhuisd","n":"uit hoofdstuk 2"},{"t":"zonder \"pijlers\" en zonder de €1,3 miljard","v":"—","h":"","n":"besluit §8 en §9"}]},{"kop":"15.2 Wat wij vragen","elementen":[{"t":"geen wijziging van het huidige beleid en geen euro uit de lopende programma's","v":"tekst","h":"nieuw","n":"toetsregel 3"},{"t":"wel de ruimte om te bouwen wat de volgende ronde nodig heeft: het bewijs dat maatschappelijke diensten een verdienmodel kunnen zijn, en de spelregels die dat mogelijk maken","v":"tekst","h":"nieuw","n":""},{"t":"en het moet klaar zijn op het moment dat die volgende ronde wordt ingericht, niet erna","v":"tekst","h":"nieuw","n":"de zin die het bestuur op 2 september nodig heeft"}]}],"noot":""}],"deel":"Deel V — Sluitstukken"},{"id":"bijlage-driesporen","letter":"16","titel":"Bijlage: de aangekondigde veenweide-aanpak, gelezen door de aktes","intro":"Stand van zaken op 18 augustus 2026. Dit is de precieze inhoud van de gebiedsspecifieke aanpak waarnaar 1.2 verwijst: het driesporenbeleid zoals het is aangekondigd, en dat de Veenweidenbrief na de zomer moet bevestigen. Deze bijlage past de leesbril van de drie aktes daarop toe. Het is een diagnose van een specifiek moment, geen standpunt over het beleid: wij lezen mee om te leren hoe de volgende ronde beter kan worden ingericht, niet om deze ronde te herzien. De middelen die nu belegd zijn, zijn belegd.","html":"\n<h2>16 — Bijlage: de aangekondigde veenweide-aanpak, gelezen door de aktes</h2>\n\n<p><strong>Stand van zaken op 18 augustus 2026.</strong> Dit is de precieze inhoud van de gebiedsspecifieke aanpak waarnaar 1.2 verwijst: het driesporenbeleid zoals het is aangekondigd, en dat de Veenweidenbrief na de zomer moet bevestigen. Deze bijlage past de leesbril van de drie aktes daarop toe. Het is een diagnose van een specifiek moment, geen standpunt over het beleid: wij lezen mee om te leren hoe de volgende ronde beter kan worden ingericht, niet om deze ronde te herzien. De middelen die nu belegd zijn, zijn belegd.</p>\n\n<p>De aanpak is nog niet gepubliceerd. De Kamerbrief van 26 juni 2026 ordent het beleid voor het landelijk gebied in vijf hoofdlijnen en niet in drie sporen; de Veenweidenbrief wordt na de zomer verwacht. Navraag bij LVVN in augustus 2026 bevestigt dat de inhoud van de gebiedsspecifieke aanpak sindsdien niet is gewijzigd en dat de drie sporen nog staan. Zolang de brief er niet is, zijn de bedragen hieronder niet in publieke Kamerstukken terug te vinden en blijven ze staan met die bronaanduiding.</p>\n\n<div style=\"background:var(--amber-light);border-left:3px solid var(--amber);border-radius:var(--radius);padding:1.25rem 1.5rem;margin:1.5rem 0 0;font-size:13.5px;line-height:1.65\">\n    <strong style=\"display:block;margin-bottom:6px;font-size:14px\">De drie sporen, zoals aangekondigd</strong><span class=\"fiche-wrap\" style=\"margin-left:6px\"><button class=\"fiche-btn\" type=\"button\" aria-label=\"Bron tonen\">ⓘ</button><span class=\"fiche-popup\"><span class=\"fiche-label\">Bron (alle cijfers in dit blok)</span><span class=\"fiche-source\">Douwe Jonkers (LVVN), ambtelijke voorbespreking conceptbrief gebiedsspecifieke aanpak veenweide.</span><span class=\"fiche-note\">Nog niet publiek; bronaanduiding wordt aangevuld zodra de kamerbrief is verzonden.</span></span></span>\n    <p style=\"margin:0 0 .75rem\">Het Rijk werkt aan een driesporenbeleid voor het veenweidegebied: (1) intensivering [[CHECK DOUWE: juiste term voor spoor 1. Rond natuur wordt niet geïntensiveerd, dus dit woord klopt waarschijnlijk niet — Simon]] in urgentiegebieden, zones rond natuur en weidevogelkerngebieden, en gebieden met hoge emissies en sterke bodemdaling, op ca. 45.000 ha (€400 mln uit rijksmiddelen voor het landelijk gebied), (2) generieke fixatie van het slootwaterpeil op -20 tot -40 cm op het resterende areaal van ca. 90.000 ha [[CHECK DOUWE: spoor 2 betreft volgens de Unie van Waterschappen niet 90.000 ha maar het gehele veenweidegebied, als basismaatregel — Niel]], geflankeerd door een GLB-hectarepremie, en (3) omschakeling naar melkveehouderij met lagere veedichtheid op ca. 20.000 ha (€900 mln voor 50% grondafwaardering). Totaal: een zichtbare claim van circa €1,3 miljard tot 2035, los van de GLB-hectarepremie. De sporen tellen samen op tot circa 155.000 ha; voor de overige circa 45.000 ha grasland op veen, vooral klei-op-veen en delen die al nat liggen, voorziet het beleid geen specifieke ingreep. [[CHECK DOUWE: spoor 1 en 3 overlappen qua gebied. €400 mln is flankerend beleid op 45.000 ha, €900 mln is grondafwaardering op 20.000 ha volgens de CSV-methodiek — Niel]]</p>\n    <p style=\"margin:0\">Deze veenweideboeren-aanpak is geschreven omdat dit beleid, hoe doordacht ook, het risico in zich draagt om precies het tegenovergestelde effect te bereiken van wat het beoogt. Peilverhoging met uitsluitend compensatie, hoe royaal ook, vervangt geen bedrijfsperspectief. Compensatie vergoedt verlies; ze geeft geen richting. Boeren die willen produceren en beheren vertrekken toch, niet omdat het financieel niet uitkomt, maar omdat er geen toekomst meer te bouwen valt. En juist die boeren zijn nodig om de opgaves daadwerkelijk te halen. Het geld is er. De vraag is of het de motor voedt, of dat het hem afzet.</p>\n  </div>\n\n<!-- 19-8 verhuisd uit a-klem (hoofdstuk 3), met de correcties van Niel erin verwerkt bij de verhuizing -->\n\n<div style=\"background:var(--amber-light);border-left:3px solid var(--amber);border-radius:var(--radius);padding:1.25rem 1.5rem;margin:1.25rem 0;font-size:13.5px;line-height:1.65\">\n      <strong style=\"display:block;margin-bottom:6px;font-size:14px\">Spoor 3, de afbakening is smaller dan de opgave</strong>\n      <p style=\"margin:0\">Spoor 3 reserveert melkveehouderij met een lagere veedichtheid voor ca. 20.000 hectare, alleen daar waar opgaves zich stapelen, buiten zonering en weidevogelgebieden. Onze eigen analyse komt op 20 tot 30 procent van het areaal dat een fundamenteel ander bedrijfsmodel nodig heeft. Het verschil zit in de hagelslag: vernatting valt niet in aaneengesloten blokken maar verspreid over percelen, waardoor delen van bedrijven onbruikbaar raken voor reguliere melkveehouderij, ook in gebieden die volgens spoor 2 door kunnen gaan. Wat daaruit volgt voor de inrichting van de volgende ronde: de omschakeling is geen uitzonderingsregeling voor randgevallen maar een route die ook binnen spoor 1 en spoor 2 beschikbaar moet zijn.</p>\n    </div>\n\n<!-- 19-8 verhuisd uit g-perspectief (hoofdstuk 13), omgezet van stellingname naar diagnose -->\n\n<div style=\"background:var(--amber-light);border-left:3px solid var(--amber);border-radius:var(--radius);padding:1.25rem 1.5rem;margin:1.25rem 0;font-size:13.5px;line-height:1.65\">\n      <strong style=\"display:block;margin-bottom:6px;font-size:14px\">Drie sporen, of drie intensiteiten van dezelfde beweging</strong>\n      <p style=\"margin:0\">De aanpak ordent het gebied naar ingreep: urgentiegebieden, generieke fixatie van het slootwaterpeil, en omschakeling naar een lagere veedichtheid. Gelezen door de aktes valt op dat die drie ook te zien zijn als drie intensiteiten van één beweging: hetzelfde bedrijfsmodel in verschillende gradaties, gedragen door dezelfde ondernemers en gecoördineerd op polderniveau. Wat dat leert voor de inrichting van de volgende ronde: één bedrijfsmodel met een schuif erin is eenvoudiger te financieren en te controleren dan drie regelingen die elk hun eigen doelgroep moeten afbakenen — en die schuif is precies de schaal uit hoofdstuk 9.</p>\n    </div>\n\n<!-- 19-8 verhuisd uit akte III; de correcties uit correctielijst.md zijn hier nog niet verwerkt -->\n\n<div style=\"background:var(--amber-light);border-left:3px solid var(--amber);border-radius:var(--radius);padding:1.25rem 1.5rem;margin:1.25rem 0;font-size:13.5px;line-height:1.65\">\n      <strong style=\"display:block;margin-bottom:6px;font-size:14px\">Driesporenbeleid: €1,3 miljard, twee bestedingsroutes</strong>\n      <p style=\"margin:0\">Het driesporenbeleid claimt circa €1,3 miljard tot 2035: €400 mln voor spoor 1, €900 mln voor spoor 3, plus onbenoemde GLB-middelen voor spoor 2. Hetzelfde bedrag kan in akte II-logica óf in akte III-logica besteed worden. De €400 mln voor urgentiegebieden kan opgaan aan opkoop, nadeelcompensatie en uitvoeringskosten, óf aan prestatiecontracten en gebiedsregie via collectieven. De €900 mln voor \"50% grondafwaardering\" kan ondernemers het land uitduwen via opkoop, óf via een Nationale Grondbank, langjarige prestatiecontracten en transitiesteun juist op het land houden. De GLB-hectarepremie kan generieke compensatie zijn, óf gebiedsspecifieke basisvergoeding gekoppeld aan een vernattingsregime. Het geld is er. De keuze ligt in het instrument.</p>\n    </div>\n\n    <div style=\"background:var(--amber-light);border-left:3px solid var(--amber);border-radius:var(--radius);padding:1.25rem 1.5rem;margin:1.25rem 0;font-size:13.5px;line-height:1.65\">\n      <strong style=\"display:block;margin-bottom:6px;font-size:14px\">Spoor 3 specifiek: waarom afwaardering de verkeerde route is</strong>\n      <p style=\"margin:0\"><strong>De €900 mln voor \"50% grondafwaardering\" veroorzaakt drie problemen tegelijk.</strong> Ten eerste stuurt het verkeerd: het frame is \"boer levert iets in, overheid betaalt de schade\", de boer is verliezer, de overheid is hulpverlener. Dat reproduceert precies de subsidie-logica die dit document afwijst — geen zakelijke transactie, maar nadeelcompensatie. Ten tweede werkt het grondspeculatie in de hand: wanneer de overheid €900 mln aankondigt om grond af te waarderen, weet de markt twee dingen tegelijk dat de grond straks (administratief) minder waard wordt én dat er overheidsgeld in dit gebied komt — precies het signaal dat beleggers aantrekt in plaats van boeren. Ten derde bevriest het het oude denken: door af te waarderen accepteert de overheid impliciet dat de hectare nooit meer een goed verdienmodel kan opleveren, een bestuurlijke vorm van opgeven. Het alternatief is geen ander bedrag, maar een andere richting: dezelfde €900 mln in een meerjarige opdrachtenstroom voor maatschappelijke diensten zet de hectare niet op een lager waarde-niveau, maar op stapelbare langjarige inkomstenstromen — een opwaardering in plaats van een afwaardering.</p>\n    </div>\n\n<h3>16.2 De landelijke verdringingsreeks</h3>\n\n<p>Hoofdstuk 5 leunt hierop: bij watertekort bepaalt deze rangorde wie voorgaat. [[BRON: vindplaats van de landelijke verdringingsreeks in de huidige rijksregelgeving, na de inwerkingtreding van de Omgevingswet]]</p>\n\n<div style=\"overflow-x:auto\">\n    <table class=\"layer-table\">\n      <thead>\n        <tr>\n          <th style=\"width:12%\">Categorie</th>\n          <th style=\"width:56%\">Wat er bij watertekort voorgaat</th>\n          <th style=\"width:32%\">Waar dit gebied zit</th>\n        </tr>\n      </thead>\n      <tbody>\n        <tr>\n          <td><strong>1</strong></td>\n          <td>onomkeerbare schade: de stabiliteit van waterkeringen, dan klink en zetting in veen en hoogveen, dan natuur die aan de bodemgesteldheid gebonden is</td>\n          <td><strong>de veenbodem</strong>, op de tweede plaats van de hele reeks</td>\n        </tr>\n        <tr>\n          <td><strong>2</strong></td>\n          <td>nutsvoorzieningen, waaronder drinkwater</td>\n          <td>—</td>\n        </tr>\n        <tr>\n          <td><strong>3</strong></td>\n          <td>kleinschalig hoogwaardig gebruik</td>\n          <td>—</td>\n        </tr>\n        <tr>\n          <td><strong>4</strong></td>\n          <td>de overige belangen, waaronder de landbouw</td>\n          <td><strong>het gras</strong>, onderaan</td>\n        </tr>\n      </tbody>\n    </table>\n  </div>\n","werkstand":{"nummer":"16","ronde":"5","stand":"in aanbouw, 4 van de 9 blokken verhuisd"},"skelet":[{"nummer":"16","titel":"Bijlagen","bron":"bijlage-driesporen","stand":"ronde 5","deel":"Deel V — Sluitstukken","kern":"Alles om het na te rekenen: de aangekondigde veenweide-aanpak gelezen door de aktes, elk getal met zijn bron of label, de volledige toolbox en de begrippen. Wie een bewering wil nazoeken, is hier op de juiste plek.","secties":[{"kop":"16.1 De aangekondigde veenweide-aanpak, gelezen door de aktes","elementen":[{"t":"de drie sporen zoals aangekondigd, met datum en bron","v":"kader","h":"auteurs","n":""},{"t":"de kritiek per spoor als gedateerde diagnose, niet als stellingname","v":"tekst","h":"auteurs","n":""},{"t":"de negen driesporenblokken samengevoegd tot één doorlopende bijlage","v":"tekst","h":"auteurs","n":""}]},{"kop":"16.2 Cijfers en bronnen","elementen":[{"t":"elk getal uit het document met zijn bron of zijn label","v":"tabel","h":"nieuw","n":""}]},{"kop":"16.3 De toolbox","elementen":[{"t":"alle bouwstenen, per categorie, met literatuur","v":"tabel","h":"auteurs","n":""}]},{"kop":"16.4 Begrippen","elementen":[{"t":"opdrachten (de overheid koopt een dienst in) tegenover steun (geen tegenprestatie)","v":"tabel","h":"nieuw","n":""},{"t":"ecosysteemdienst (wat de natuur levert) tegenover maatschappelijke dienstverlening (wat de ondernemer levert)","v":"tabel","h":"nieuw","n":""},{"t":"veenweideboer · middengroep · lagere veedichtheid · ronde · grondwaterstand en slootwaterpeil","v":"tabel","h":"verhuisd","n":"uit het begrippenkader in de wachtkamer"},{"t":"de lijst wordt opgezocht en niet gelezen; in de tekst doet een fiche bij het eerste gebruik het werk","v":"fiche","h":"","n":""}]}],"noot":""}],"deel":"Deel V — Sluitstukken"}];
